# Select top expressed genes 
# UMI_count_mat_file = outdirectory + "/" + synthetic_countmat_file
# bed_file = gene_bedfile
def topGeneSelection(UMI_count_mat_file, n_top=10, mode="top"):
    """Select top expressed genes 

    Parameters
    ----------
    UMI_count_mat_file: `str`
        Path to input count matrix for selecting top expressed genes.
    n_top: 'int'
        Number of genes to be selected.
    mode: 'str'
        Specify the mode of gene selected. Supported modes include 'top' and 'hvg'.
    
    Output
    ------
    Indices of n_top top-expressed genes.
    """
    UMI_count_mat_df = pd.read_csv("%s" % (UMI_count_mat_file), header=None, delimiter="\t")
    UMI_count_mat = UMI_count_mat_df.iloc[:,1:].to_numpy() # geneXcell
    if mode == 'top':
        count_pergene = UMI_count_mat.sum(axis=1)
        ind_output = np.argsort(-count_pergene)[1:n_top]
    elif mode == 'hvg':
        scaling_fac = 1e6
        normalized_count_mat = UMI_count_mat / UMI_count_mat.sum(axis=0) * scaling_fac
        var_pergene = np.var(normalized_count_mat, axis=1)
        ind_output = np.argsort(-var_pergene)[1:n_top]
    return ind_output
        

def cellbarcode_generator(length, size=10):
    """Generate random cellbarcode.

    Parameters
    ----------
    length: `int`
        Number of cells.
    size: `int` (default: '10')
        Size of cell barcode. Default value is 10 bp.

    Return
    ------
    cb_list: `list`
        List of randomly generated cell barcodes.
    """
    chars = 'ACGT'
    cb_list = [''.join(random.choice(chars) for _ in range(size)) for cell in range(length)]
    return cb_list


def prepare_scIsoSim(outdirectory, gffread_dir, referenceGenome_file, isoform_annotation_file):
    """Generate cell barcodes and prepare transcriptome based on user input isoform annotation file.

    Parameters
    ----------
    outdirectory: `str`
        Specify the output directory for synthetic reads bed file.
    synthetic_cell_label_file: 'str'
       Cell label file storing cell labels for synthetic cells, generated by scReadSim.GenerateSyntheticCount.scRNA_GenerateSyntheticCount.
    gffread_dir: `str`
        Path to software gffread.
    referenceGenome_file: `str`
        Reference genome FASTA file.
    isoform_annotation_file: 'str'
        Path to the isoform annotation GTF file.
    OUTPUT_cells_barcode_file: 'str'
        Specify the file name storing the synthetic cell barcodes.
    CB_len: `int` (default: '16')
        Specify the length of synthetic cell barcodes. Default value is 16 bp.

    Output
    ------
    - Tanscriptome FASTA file generated based on reference genome and input isoform annotation file.
    - Synthetic cell barcode file.
    - Synthetic cell barcode file along with corresponding cell labels.
    """
    #  Read in synthetic cell cluster label
    # cell_cluster = pd.read_csv(synthetic_cell_label_file, header=None, delimiter="\t")
    # n_cell = len(cell_cluster)
    # # Generate synthetic cell barcode
    # random.seed(2023) # only affects random.choice (used in cellbarcode_generator), not affecting np.random
    # random_cellbarcode_list = cellbarcode_generator(n_cell, size=CB_len)
    # print("[scIsoSim] Generating Synthetic Cell Barcode...")
    # # Write out synthetic cell barcode file
    # with open(outdirectory + "/" + OUTPUT_cells_barcode_file, 'w') as f:
    # 	for item in random_cellbarcode_list:
    # 		f.write(item + "\n")
    # # Write out synthetic cell barcode with cell type label file
    # cellbarcode_list_withclusters = np.vstack((random_cellbarcode_list, list(cell_cluster[0]))).transpose()
    # with open(outdirectory + "/" + OUTPUT_cells_barcode_file + ".withSynthCluster", 'w') as f:
