    # 		f.write("\t".join(item) + "\n")
    # # Construct ref. transciptome from ref. genome and isoform annotation file
    # print("[scIsoSim] Creating Reference Transcriptome File...")
    extractTransFA_cmd = "%s/gffread -w %s/transcripts.fa -g %s %s" % (gffread_dir, outdirectory, referenceGenome_file, isoform_annotation_file)
