def generateIsoformProp(bed_file, isoform_annotation_file, outdirectory, isoform_proportion_file, transcript_term="transcript", gene_ind=None, mode="simple",target_n_isoform=2):
    """Generaet proportions for user-specified isoforms

    Parameters
    ----------
    bed_file: 'str'
        A bed file of metagenes to generate the synthetic reads (Generated by function `Utility.scRNA_CreateFeatureSets`).
    isoform_annotation_file: 'str'
        Path to the isoform annotation GTF file.
    outdirectory: 'str'
        Specify the output directory.
    isoform_proportion_file: 'str'
        Specify the name of output isoform proportion file.
    transcript_term: 'str', optional (default: 'transcript')
        Specify the key word representing an isoform record used in `isoform_annotation_file`.
    gene_ind: optional (default: None)
        Genes that are used for generating isoforms
    mode: 'str' (default: simple)
        Generate one isoform for each gene
    """
    annotation = gffpd.read_gff3(isoform_annotation_file)
    with open(bed_file) as open_peak:
        reader = csv.reader(open_peak, delimiter="\t")
        open_peak = np.asarray(list(reader))
    if gene_ind is None:
        meta_gene_list = open_peak
    else:
        if len(gene_ind) > 0:
            meta_gene_list = open_peak[gene_ind,]
        else:
            print("[ERROR]: Input gene selection list has zero elements.")
            return
    df = pd.DataFrame(columns=['MetageneID','Genes','IsoformID','Proportion'])
    df.to_csv("%s/%s" % (outdirectory, isoform_proportion_file), index=None, sep='\t')
    print("\n[scIsoSim] Generating Isoform Proportions according to Annotation File: %s" % isoform_annotation_file)
    # Loop over metagene list
    for gene_cur_ind in tqdm(range(len(meta_gene_list))):
        gene_cur = meta_gene_list[gene_cur_ind]
        overlapings = annotation.overlaps_with(type=transcript_term, seq_id=gene_cur[0],
                                            start=int(gene_cur[1]), end=int(gene_cur[2]))
        overlapings_attr_to_columns = overlapings.attributes_to_columns()
        if 'transcript_support_level' in overlapings_attr_to_columns.columns :
            overlapings_attr_to_columns['transcript_support_level'] = pd.to_numeric(overlapings_attr_to_columns['transcript_support_level'], errors='coerce').fillna(float('inf'))
            type_priority = {
            'processed_transcript': 1,
            'protein_coding': 1,
            }
            # Apply sorting to select trsutworthy isoforms
            overlapings_attr_to_columns = overlapings_attr_to_columns.sort_values(
                by=['transcript_type', 'transcript_support_level'],
                key=lambda col: col.map(type_priority) if col.name == 'transcript_type' else col
            )
        else:
            type_priority = {
            'processed_transcript': 1,
            'protein_coding': 1,
            }
            # Apply sorting to select trsutworthy isoforms
            overlapings_attr_to_columns = overlapings_attr_to_columns.sort_values(
                by=['transcript_type'],
                key=lambda col: col.map(type_priority) if col.name == 'transcript_type' else col
            )
        n_isoforms = overlapings_attr_to_columns.shape[0]
        if n_isoforms > 0:
            if mode == "simple":
                # Only allow one isoform per gene
                print("[scIsoSim] Metagene region %s found %s overlapping isoform annotation." % (gene_cur, n_isoforms))
                gene_cur_name = ';'.join(overlapings_attr_to_columns['Parent'].unique())
                # Sample multinomial prob. using Drichlet prior distribution
                isoform_prop = 1
                df_cur = pd.DataFrame({
                    'MetageneID': ["_".join(gene_cur)],
                    'Genes': [gene_cur_name],
                    'IsoformID': overlapings_attr_to_columns["ID"].iloc[0],
                    'Proportion': isoform_prop
                    })
                df_cur.to_csv("%s/%s" % (outdirectory, isoform_proportion_file), header=None, index=None, sep='\t', mode='a')
                print("\n[scIsoSim] Created:")
            elif mode == "complex":
                if n_isoforms > 1:
                    # 90% genes would contain RNA editing events in intronic regions
                    n_isoforms = np.random.choice([1, target_n_isoform], p=[0.1, 0.9])
                print("[scIsoSim] Metagene region %s found %s overlapping isoform annotation." % (gene_cur, n_isoforms))
                gene_cur_name = ';'.join(overlapings_attr_to_columns['Parent'].unique())
                # Sample multinomial prob. using Drichlet prior distribution
                alpha = 2
                dirch_alpha = [alpha] * n_isoforms
                isoform_prop = np.random.dirichlet(alpha=dirch_alpha, size=1)[0]
                df_cur = pd.DataFrame({
                    'MetageneID': ["_".join(gene_cur)] * n_isoforms,
                    'Genes': [gene_cur_name] * n_isoforms,
                    'IsoformID': overlapings_attr_to_columns["ID"][0:n_isoforms],
                    'Proportion': isoform_prop
                    })
                df_cur.to_csv("%s/%s" % (outdirectory, isoform_proportion_file), header=None, index=None, sep='\t', mode='a')
                print("\n[scIsoSim] Created:")
            
    print("[scIsoSim] Isoform Annotation Proportion File: %s/%s" % (outdirectory, isoform_proportion_file))
    print("[scIsoSim] Done.")



def interpolate_list(input_list, output_size):
    if len(input_list) < 2:
        raise ValueError("Input list must have at least 2 values for interpolation")
    # Create an array of indices for the output interpolation
    output_indices = np.linspace(start=0, stop=len(input_list)-1, num=output_size)
    # Interpolate the values at the specified indices
    interpolated_values = np.interp(output_indices, np.arange(len(input_list)), input_list)
    return interpolated_values.tolist()


def sampleStartPos10x(isoform_len, size, freq_list):
    # Check if the input list has 100 quantiles
    if len(freq_list) != 100:
        raise ValueError("Frequency list must have 100 quantiles")
    # Interpolate the frequency list to create a probability density function (PDF)
    pdf = interpolate_list(input_list=freq_list, output_size=isoform_len)
    # Normalize the PDF to ensure it sums to 1
    pdf /= np.sum(pdf)                     
    # Generate # of size random samples using the given PDF
    samples = np.random.choice(np.arange(1, isoform_len + 1), size=size, p=pdf)
    return samples

def sampleStartPosSmartSeq(isoform_len, size, freq_list):
    # Check if the input list has 100 quantiles
    if len(freq_list) != 100:
        raise ValueError("Frequency list must have 100 quantiles")
    # Interpolate the frequency list to create a probability density function (PDF)
    pdf = interpolate_list(input_list=freq_list, output_size=isoform_len)
    # Normalize the PDF to ensure it sums to 1
    pdf = np.array(pdf)
    # min-max normlaization to reduce the effects of outliers
    pdf = (pdf-min(pdf))/(max(pdf)-min(pdf))
    pdf /= np.sum(pdf)                     
    # Generate # of size random samples using the given PDF
    samples = np.random.choice(np.arange(1, isoform_len + 1), size=size, p=pdf)
    return samples
    

