def generateIsoformBED(bed_file, sub_count_mat, sub_cell_barcode, INPUT_bamfile, isoform_proportion_file, trancriptome_file, outdirectory, read_bedfile_prename, sequencing_protocol="10x", library_type="3prime", fragment_size_ditribution_file=None, read_start_empdist_dir=None, UMI_tag='UB:Z', read_len=126, UMI_len=10, min_read_len=30,mode="no_PCR",smartseq_mode="mechanistic",isoform_count_matrix_file="IsoformSyntheticRead.countmatrix.txt"):
    """Generate isoforms according to UMI count matrix and ground truth isoforms (with proportions)

    Parameters
    ----------
    bed_file: 'str'
        A bed file of metagenes to generate the synthetic reads (Generated by function `Utility.scRNA_CreateFeatureSets`).
    sub_count_mat: `pandas.dataframe`
        UMI count matrix for generating synthetic reads.
    sub_cell_barcode: `pandas.dataframe`
        Synthetic cell barcodes.
    INPUT_bamfile: 'str'
        Path to the input BAM file.
    isoform_proportion_file: 'str'
        Isoform proportion file generated by function `generateIsoformProp`.
    trancriptome_file: 'str'
        Transcript sequencing FASTQ file generated by prepare_scIsoSim.
    outdirectory: 'str'
        Specify the output directory for synthetic reads bed file.
    read_bedfile_prename: 'str'
        Specify the base name of output bed file.
    sequencing_protocol: 'str'
        Specify the protocol of sequencing reads (currently supported: '10x')
    library_type: 'str'
        Specify the library type for 10x protocol (currently supported: '3prime', '5prime')
    UMI_tag: 'str' (default: 'UB:Z')
        For 10x sequencing, specify the UMI tag of input BAM file, default value 'UB:Z' is the UMI tag for 10x scRNA-seq.
    read_len: 'int' (default: '126')
        Specify the length of synthetic reads. Default value is 126 bp.
    UMI_len: 'int' (default: 10)
        For 10x sequencing, specify the UMI length.
    Output
    ------
    - BED file containing coordinates for cell-type-specific reads.
    """
    valid_sequencing_protocols = {"10x", "SmartSeq2"}
    if sequencing_protocol not in valid_sequencing_protocols:
        raise ValueError("[Error]: scIsoSim-supported sequencing protocols must be one of %r." % valid_sequencing_protocols)
    isoform_prop_df = pd.read_csv("%s" % (isoform_proportion_file), header=0, delimiter="\t")
    metagene_list = isoform_prop_df['MetageneID'].unique()
    open_peak = pd.read_csv(bed_file, header=None, delimiter="\t")
    open_peak_df = open_peak[0].astype(str) + "_" + open_peak[1].astype(str) + "_" + open_peak[2].astype(str)
    samfile = pysam.AlignmentFile(INPUT_bamfile, "rb")
    transcript_dict = SeqIO.to_dict(SeqIO.parse(open(trancriptome_file), "fasta"))
    # Set random seed
    # np.random.seed(2023) # for not rng.generator
    rng = np.random.default_rng(2023) # for rng.generator (specifically, multinomial), does not affect or get affected by np.random.seed
    if sequencing_protocol == "10x":
        with open("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), 'w') as fp:
            pass
        # Provide 3' and 5' mulitple choices empirical frequency options
        valid_library_type = {"3prime", "5prime"}
        if library_type not in valid_library_type:
            raise ValueError("[Error]: scIsoSim-supported 10x library types must be one of %r." % valid_library_type)
        if read_start_empdist_dir is not None:
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        else:
            if library_type == "3prime":
                read_start_empdist_dir = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/NGS_chr1_coverage_count.csv'
            elif library_type == "5prime":
                read_start_empdist_dir = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/human_pbmc_coverage_count.csv'
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        read_start_empdist = read_start_empdist_df.iloc[:,1:].sum(axis=0)
        # Generate synthetic reads
        UMIcountmat_perisoform_percell_list = []
        for metagene_cur_id in tqdm(range(len(metagene_list))):
            metagene_cur = metagene_list[metagene_cur_id]
            rec = metagene_cur.split("_")
            UMI_read_dict_pergene = defaultdict(lambda: [])
            ## Model UMI-Read empirical distribution
            reads = samfile.fetch(rec[0], int(rec[1]), int(rec[2]))
            for read in reads:
                if read.has_tag(UMI_tag):
                    UMI = read.get_tag(UMI_tag)
                    CB = read.get_tag("CB")
                    UMI = CB + UMI
                    start = read.reference_start
                    if read.is_reverse==1:
                        strand = "-" 
                    else:
                        strand = "+"
                    UMI_read_dict_pergene[UMI].append(str(start) + ":" + str(strand))
            ## Real data: Obtain the empirical distribution of # reads of UMI in the gene 
            nread_perUMI = [len(x) for x in UMI_read_dict_pergene.values()] # return a vector with the length of # UMIs in the gene
            # No PCR bias in the output result
            if mode == "no_PCR":
                # nread_perUMI = nread_perUMI = [1] * len(UMI_read_dict_pergene.values())
                # modified by weijian 20241218, the function if nread_perUMI is for sampling, so the length doesn't matter
                nread_perUMI = nread_perUMI = [1] * 100
            ## Synthetic data   
            # Synthetic isoform proportion  
            isoform_prop_df_cur = isoform_prop_df.loc[isoform_prop_df['MetageneID'] == metagene_cur]
            # Synthetic UMI count per gene  
            UMI_count_permetagene = sub_count_mat[np.where(open_peak_df == metagene_cur)[0],:].flatten()
            # Sample synthetic isoform-level UMI count from isoform prop. and gene-wise UMI count: n_isoform by n_subcell
            isoform_level_UMIcount = np.transpose(rng.multinomial(n=UMI_count_permetagene, pvals=isoform_prop_df_cur['Proportion'])) # sample multinomial for each cell with different experments number (size = 1)
            isoform_nonzero_id = np.nonzero(isoform_level_UMIcount.sum(axis=1))[0]
            UMIcountmat_perisoform_percell_list.append(isoform_level_UMIcount) # store isoform level count matrix into tmp list
            for isoform_id in isoform_nonzero_id:
                isoform_name = isoform_prop_df_cur.iloc[isoform_id]['IsoformID']
                # isoform_name = isoform_prop_df.iloc[isoform_id]['IsoformID']
                print("[scIsoSim] Generating Synthetic Reads for Gene %s Isoform %s" % (metagene_cur, isoform_name))
                # Sample syntheitc UMI's read number
                UMI_count_vec = isoform_level_UMIcount[isoform_id,:] # Synthetic umi count
                nonzer_UMI_zero_id = np.nonzero(UMI_count_vec)[0]
                synthetic_nread_perUMI_percell = [np.random.choice(nread_perUMI, size=UMI_count_vec[i], replace=True) for i in nonzer_UMI_zero_id] # return a vector with the length of non-zero count cells, each entry idnicates the number of reads for each UMI
                nread_synthetic = sum(np.sum(x) for x in synthetic_nread_perUMI_percell) # total number of synthetic reads
                synthetic_nread_perUMI_percell_unlist = [xs for x in synthetic_nread_perUMI_percell for xs in list(x)]
                # Sample synthetic read starting position (relative to transcripts) according to pre-processed 10x frequency list
                isoform_len = len(transcript_dict[isoform_name].seq)
                synthetic_read_start_list = sampleStartPos10x(isoform_len=isoform_len - min_read_len, size=nread_synthetic, freq_list=read_start_empdist)
                # Assign strand infor to synthetic reads (relative to transcripts; for single-end read, should be +, since transcripts already contain strand infor)
                synthetic_read_strand_list = ["+"] * nread_synthetic
                # Creat synthetic UMI string
                UMI_synthetic_uniq = cellbarcode_generator(np.sum(UMI_count_vec), size=UMI_len)
                UMI_synthetic_list = np.repeat(np.array(UMI_synthetic_uniq), synthetic_nread_perUMI_percell_unlist)
                # Organize syntheitc CB string
                CB_synthetic_repeat = [np.sum(x) for x in synthetic_nread_perUMI_percell] # same length to nozero cells
                CB_synthetic_list = np.repeat(np.array(sub_cell_barcode)[nonzer_UMI_zero_id], CB_synthetic_repeat)
                # Create syntheitc read name string
                read_name_remaining_list = [str(metagene_cur) + ":"+ str(isoform_name) + "#" + str(count).zfill(4) for ind in range(len(CB_synthetic_repeat)) for count in range(CB_synthetic_repeat[ind])]
                read_name_list = [CB_synthetic_list[id] + UMI_synthetic_list[id] + ":" + read_name_remaining_list[id] for id in range(nread_synthetic)]
                # Create output table (seqID is not chr, but for isoform name)
                reads_cur = pd.DataFrame({
                    'seqID': isoform_name,
                    'r1_start_shifted': synthetic_read_start_list,
                    'r1_end_shifted': np.clip(synthetic_read_start_list + read_len, None, isoform_len), # make sure read is within transcript length
                    'read_name': read_name_list,
                    'read_length': read_len,
                    'strand': synthetic_read_strand_list
                    })
                reads_cur.to_csv("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
        # Output ground truth isoform read count matrix
        UMIcountmat_perisoform_percell = np.vstack(UMIcountmat_perisoform_percell_list)
        UMIcountmat_perisoform_percell_pd = pd.DataFrame(UMIcountmat_perisoform_percell, index=isoform_prop_df['IsoformID'])
        UMIcountmat_perisoform_percell_pd.columns = sub_cell_barcode.flatten()
        UMIcountmat_perisoform_percell_pd.to_csv('%s/%s.UMIcountmatrix.txt' % (outdirectory, read_bedfile_prename), sep="\t", header=True)
        print("\n[scIsoSim] Created:")
        print("[scIsoSim] Isoform UMI count matrix file: %s/%s.UMIcountmatrix.txt" % (outdirectory,read_bedfile_prename))
        print("[scIsoSim] Read bed file: %s/%s.read.bed" % (outdirectory, read_bedfile_prename))
    elif sequencing_protocol == "SmartSeq2":
        if 2*read_len > 200:
            print("[scIsoSim Warning] Read length, specified as %s, might lead to overlapped read1 and read2 (2 * %s is larger than the minimal SmartSeq2 fragment length 200 bp)." % (read_len, read_len))
        with open("%s/%s.read1.bed" % (outdirectory, read_bedfile_prename), 'w') as f_1:
            pass
        with open("%s/%s.read2.bed" % (outdirectory, read_bedfile_prename), 'w') as f_2:
            pass
        try: 
            if fragment_size_ditribution_file is not None:
                print("[scIsoSim] Detected input fragment_size_ditribution_file: %s" % (fragment_size_ditribution_file))
            else:
                # fragment_size_ditribution_file = "/home/guanao/Projects/scIsoSim/scripts/data/smartseq2/smartseq2_CMP.fragmentSize_Real.txt"
                fragment_size_ditribution_file = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/smartseq2_CMP.fragmentSize_Real.txt'
                # fragment_size_ditribution_file = "/home/guanao/Projects/scIsoSim/results/20230216_SmartSeq2/fragmentSize_Real.txt"
        except ValueError:
            print("[scIsoSim] No input fragment_size_ditribution_file specified for %s protocol. " % (sequencing_protocol))
        if read_start_empdist_dir is not None:
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        else:
            # read_start_empdist_dir = "/home/guanao/Projects/scIsoSim/scripts/data/smartseq2/smartseq2_CMP.readcoverage.csv"
            read_start_empdist_dir = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/smartseq2_CMP.readcoverage_uniform.csv'
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        read_start_empdist = read_start_empdist_df.iloc[:,1:].sum(axis=0)
        # Read in real fragment length dist.
        real_fragment_df = pd.read_csv(fragment_size_ditribution_file, delimiter="\t", skiprows=[0])
        # real_fragment_df = pd.read_csv("/home/guanao/Projects/scIsoSim/results/20230216_SmartSeq2/fragmentSize_Real.txt", delimiter="\t", skiprows=[0])
        real_fragment_dist = real_fragment_df['Size'].repeat(real_fragment_df['Occurrences']).reset_index(drop=True)
        # Process each metagene and output directly
        umi_output_path = '%s/%s' % (outdirectory, isoform_count_matrix_file)
        with open(umi_output_path, 'w') as umi_output_file:
            for metagene_cur_id in tqdm(range(len(metagene_list))):
                metagene_cur = metagene_list[metagene_cur_id]
                rec = metagene_cur.split("_")       
                ## Synthetic data   
                # Synthetic isoform proportion  chr1_143598800_143702893 ENSMUST00000161973.1 metagene_cur_id=73
                isoform_prop_df_cur = isoform_prop_df.loc[isoform_prop_df['MetageneID'] == metagene_cur]
                # Synthetic read pair count per gene  
                count_permetagene = sub_count_mat[np.where(open_peak_df == metagene_cur)[0],:].flatten()
                # Sample synthetic isoform-level UMI count from isoform prop. and gene-wise UMI count: n_isoform by n_subcell
                isoform_level_count = np.transpose(rng.multinomial(n=count_permetagene, pvals=isoform_prop_df_cur['Proportion']))
                isoform_nonzero_id = np.nonzero(isoform_level_count.sum(axis=1))[0]
                # Write current read count matrix to the output file
                isoform_ids = isoform_prop_df_cur['IsoformID'].tolist()
                for isoform_id, umi_counts in zip(isoform_ids, isoform_level_count):
                    umi_output_file.write(f"{isoform_id}\t" + "\t".join(map(str, umi_counts)) + "\n")
                for isoform_id in isoform_nonzero_id:
                    isoform_name = isoform_prop_df_cur.iloc[isoform_id]['IsoformID']
                    # isoform_name = isoform_prop_df.iloc[isoform_id]['IsoformID']
                    print("[scIsoSim] Generating Synthetic Reads for Gene %s Isoform %s" % (metagene_cur, isoform_name))
                    # Sample syntheitc read pairs
                    count_vec = isoform_level_count[isoform_id,:] # Synthetic read count
                    paircount_vec = np.rint(count_vec/2).astype(int)
                    nonzer_count_zero_id = np.nonzero(paircount_vec)[0]
                    nreadpair_synthetic = sum(paircount_vec) # total number of synthetic read pair
                    # Sample synthetic read starting position (relative to transcripts)
                    isoform_len = len(transcript_dict[isoform_name].seq)
                    # If isoform length is smaller than 200 bp, then no fragment is generated for the current isoform
                    if isoform_len < read_len:
                        print("[scIsoSim Warning] Isoform %s length is smaller than specified read length %s bp. Skip the isoform." % (isoform_name, read_len))
                        continue
                    if smartseq_mode == "mechanistic":
                        # Starting position
                        # modified by weijian
                        fragment_start_list = sampleStartPosSmartSeq(isoform_len=isoform_len-1, size=nreadpair_synthetic, freq_list=read_start_empdist)
                        # Fragment length uniform [200, 600]: here!
                        fragment_length_max = isoform_len - fragment_start_list
                        fragment_len = []
                        read_len_list = []
                        for fragment_max in fragment_length_max:
                            if fragment_max < read_len:
                                fragment_len.append(fragment_max)
                                read_len_list.append(fragment_max)
                            else:
                                fragment_length_tmp = real_fragment_dist[real_fragment_dist.between(read_len, fragment_max)]
                                fragment_length_tmp = np.random.choice(fragment_length_tmp, size=1)
                                fragment_len.append(fragment_length_tmp[0])
                                read_len_list.append(read_len)
                        # real_fragment_dist_trun = real_fragment_dist[real_fragment_dist.between(read_len, isoform_len-1)]
                        # fragment_len = np.random.choice(real_fragment_dist_trun, size=nreadpair_synthetic)
                    fragment_end_list = fragment_start_list + fragment_len # should be small or equal to isoform_lenth + 1 [0, isform+length)
                    synthetic_read1_start_list = fragment_start_list
                    synthetic_read2_start_list = fragment_end_list - read_len_list # no need to plus 1
                    # Assign strand infor to synthetic reads (relative to transcripts; for single-end read, should be +, since transcripts already contain strand infor)
                    synthetic_read1_strand_list = ["+"] * nreadpair_synthetic
                    synthetic_read2_strand_list = ["-"] * nreadpair_synthetic
                    # Organize syntheitc CB string
                    # print(len(paircount_vec))
                    # print(len(np.array(sub_cell_barcode)[nonzer_count_zero_id]))
                    CB_synthetic_list = np.repeat(np.array(sub_cell_barcode)[nonzer_count_zero_id], paircount_vec[nonzer_count_zero_id])
                    # Create syntheitc read name string
                    read_name_remaining_list = [str(metagene_cur) + ":"+ str(isoform_name) + "#" + str(count).zfill(4) for ind in range(len(paircount_vec)) for count in range(paircount_vec[ind])]
                    read_name_list = [CB_synthetic_list[id] + ":" + read_name_remaining_list[id] for id in range(nreadpair_synthetic)]
                    # Create output table (seqID is not chr, but for isoform name)
                    reads1_cur = pd.DataFrame({
                        'seqID': isoform_name,
                        'r1_start_shifted': synthetic_read1_start_list,
                        'r1_end_shifted': np.clip(synthetic_read1_start_list + read_len_list, None, isoform_len), # make sure read is within transcript length
                        'read_name': read_name_list,
                        'read_length': read_len_list,
                        'strand': synthetic_read1_strand_list
                        })
                    reads1_cur.to_csv("%s/%s.read1.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
                    # Create output table (seqID is not chr, but for isoform name)
                    reads2_cur = pd.DataFrame({
                        'seqID': isoform_name,
                        'r2_start_shifted': synthetic_read2_start_list,
                        'r2_end_shifted': np.clip(synthetic_read2_start_list + read_len_list, None, isoform_len), # make sure read is within transcript length
                        'read_name': read_name_list,
                        'read_length': read_len_list,
                        'strand': synthetic_read2_strand_list
                        })
                    reads2_cur.to_csv("%s/%s.read2.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
        print("\n[scIsoSim] Created:")
        print("[scIsoSim] Isoform read count matrix file: %s/%s" % (outdirectory, isoform_count_matrix_file))
        print("[scIsoSim] Read1 bed file: %s/%s.read1.bed" % (outdirectory, read_bedfile_prename))
        print("[scIsoSim] Read2 bed file: %s/%s.read2.bed" % (outdirectory, read_bedfile_prename))
        

def generateIsoformBED_tmp(bed_file, sub_count_mat, sub_cell_barcode, INPUT_bamfile, isoform_proportion_file, trancriptome_file, outdirectory, read_bedfile_prename, sequencing_protocol="10x", library_type="3prime", fragment_size_ditribution_file=None, read_start_empdist_dir=None,UMI_tag='UB:Z', read_len_10x=126, UMI_len=10,read_len_smartseq=75,smartseq_mode="empirical"):
    """Generate isoforms according to UMI count matrix and ground truth isoforms (with proportions)

    Parameters
    ----------
    bed_file: 'str'
        Gene bed file.
    sub_count_mat: `pandas.dataframe`
        UMI count matrix for generating synthetic reads.
    sub_cell_barcode: `pandas.dataframe`
        Synthetic cell barcodes.
    isoform_proportion_file: 'str'
        Isoform proportion file generated by function `generateIsoformProp`.
    trancriptome_file: 'str'
        Transcript sequencing FASTQ file generated by prepare_scIsoSim.
    outdirectory: `str`
        Specify the output directory for synthetic reads bed file.
    read_bedfile_prename: `str`
        Specify the base name of output bed file.
    read_len_10x: `int` (default: '126')
        Specify the length of synthetic reads for 10x technology. Default value is 126 bp.
    UMI_tag: `str` (default: 'UB:Z')
        If UMI_modeling is set to True, specify the UMI tag of input BAM file, default value 'UB:Z' is the UMI tag for 10x scRNA-seq.
    read_len_smartseq: `int` (default: '75')
        Specify the length of synthetic reads for smartseq2 technology. Default value is 75 bp.
    smartseq_mode: 'str' (default: 'empirical')
        Spefify the mode of generating smartseq2 fragment. 
    Output
    ------
    - BED file containing coordinates for cell-type-specific reads.
    """
    valid_sequencing_protocols = {"10x", "SmartSeq2"}
    if sequencing_protocol not in valid_sequencing_protocols:
        raise ValueError("[Error]: scIsoSim-supported sequencing protocols must be one of %r." % valid_sequencing_protocols)
    isoform_prop_df = pd.read_csv("%s" % (isoform_proportion_file), header=0, delimiter="\t")
    metagene_list = isoform_prop_df['MetageneID'].unique()
    open_peak = pd.read_csv(bed_file, header=None, delimiter="\t")
    open_peak_df = open_peak[0].astype(str) + "_" + open_peak[1].astype(str) + "_" + open_peak[2].astype(str)
    samfile = pysam.AlignmentFile(INPUT_bamfile, "rb")
    transcript_dict = SeqIO.to_dict(SeqIO.parse(open(trancriptome_file), "fasta"))
    # Set random seed
    # np.random.seed(2023) $ set outside the function
    rng = np.random.default_rng(2023) # for rng.generator (specifically, multinomial), does not affect or get affected by np.random.seed
    if sequencing_protocol == "10x":
        read_len = read_len_10x
        with open("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), 'w') as fp:
            pass
        # Provide 3' and 5' mulitple choices empirical frequency options
        valid_library_type = {"3prime", "5prime"}
        if library_type not in valid_library_type:
            raise ValueError("[Error]: scIsoSim-supported 10x library types must be one of %r." % valid_library_type)
        if read_start_empdist_dir is not None:
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        else:
            if library_type == "3prime":
                read_start_empdist_dir = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/NGS_chr1_coverage_count.csv'
            elif library_type == "5prime":
                read_start_empdist_dir = '/u/home/w/weijian/project-gxxiao/project/scEditSim/data/coverage/human_pbmc_coverage_count.csv'
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        read_start_empdist = read_start_empdist_df.iloc[:,1:].sum(axis=0)
        # Generate synthetic reads
        UMIcountmat_perisoform_percell_list = []
        for metagene_cur_id in tqdm(range(len(metagene_list))):
            metagene_cur = metagene_list[metagene_cur_id]
            rec = metagene_cur.split("_")
            UMI_read_dict_pergene = defaultdict(lambda: [])
            ## Model UMI-Read empirical distribution
            reads = samfile.fetch(rec[0], int(rec[1]), int(rec[2]))
            for read in reads:
                if read.has_tag(UMI_tag):
                    UMI = read.get_tag(UMI_tag)
                    start = read.reference_start
                    if read.is_reverse==1:
                        strand = "-" 
                    else:
                        strand = "+"
                    UMI_read_dict_pergene[UMI].append(str(start) + ":" + str(strand))
            ## Real data: Obtain the empirical distribution of # reads of UMI in the gene 
            nread_perUMI = [len(x) for x in UMI_read_dict_pergene.values()] # return a vector with the length of # UMIs in the gene
            ## Synthetic data   
            # Synthetic isoform proportion  
            isoform_prop_df_cur = isoform_prop_df.loc[isoform_prop_df['MetageneID'] == metagene_cur]
            # Synthetic UMI count per gene  
            UMI_count_permetagene = sub_count_mat[np.where(open_peak_df == metagene_cur)[0],:].flatten()
            # Sample synthetic isoform-level UMI count from isoform prop. and gene-wise UMI count: n_isoform by n_subcell
            isoform_level_UMIcount = np.transpose(rng.multinomial(n=UMI_count_permetagene, pvals=isoform_prop_df_cur['Proportion'])) # sample multinomial for each cell with different experments number (size = 1)
            isoform_nonzero_id = np.nonzero(isoform_level_UMIcount.sum(axis=1))[0]
            UMIcountmat_perisoform_percell_list.append(isoform_level_UMIcount) # store isoform level count matrix into tmp list
            for isoform_id in isoform_nonzero_id:
                isoform_name = isoform_prop_df_cur.iloc[isoform_id]['IsoformID']
                # isoform_name = isoform_prop_df.iloc[isoform_id]['IsoformID']
                print("[scIsoSim] Generating Synthetic Reads for Gene %s Isoform %s" % (metagene_cur, isoform_name))
                # Sample syntheitc UMI's read number
                UMI_count_vec = isoform_level_UMIcount[isoform_id,:] # Synthetic umi count
                nonzer_UMI_zero_id = np.nonzero(UMI_count_vec)[0]
                synthetic_nread_perUMI_percell = [np.random.choice(nread_perUMI, size=UMI_count_vec[i], replace=True) for i in nonzer_UMI_zero_id] # return a vector with the length of non-zero count cells, each entry idnicates the number of reads for each UMI
                nread_synthetic = sum(np.sum(x) for x in synthetic_nread_perUMI_percell) # total number of synthetic reads
                synthetic_nread_perUMI_percell_unlist = [xs for x in synthetic_nread_perUMI_percell for xs in list(x)]
                # Sample synthetic read starting position (relative to transcripts) according to pre-processed 10x frequency list
                isoform_len = len(transcript_dict[isoform_name].seq)
                synthetic_read_start_list = sampleStartPos10x(isoform_len=isoform_len, size=nread_synthetic, freq_list=read_start_empdist)
                # Assign strand infor to synthetic reads (relative to transcripts; for single-end read, should be +, since transcripts already contain strand infor)
                synthetic_read_strand_list = ["+"] * nread_synthetic
                # Creat synthetic UMI string
                UMI_synthetic_uniq = cellbarcode_generator(np.sum(UMI_count_vec), size=UMI_len)
                UMI_synthetic_list = np.repeat(np.array(UMI_synthetic_uniq), synthetic_nread_perUMI_percell_unlist)
                # Organize syntheitc CB string
                CB_synthetic_repeat = [np.sum(x) for x in synthetic_nread_perUMI_percell] # same length to nozero cells
                CB_synthetic_list = np.repeat(np.array(sub_cell_barcode)[nonzer_UMI_zero_id], CB_synthetic_repeat)
                # Create syntheitc read name string
                read_name_remaining_list = [str(metagene_cur) + ":"+ str(isoform_name) + "#" + str(count).zfill(4) for ind in range(len(CB_synthetic_repeat)) for count in range(CB_synthetic_repeat[ind])]
                read_name_list = [CB_synthetic_list[id] + UMI_synthetic_list[id] + ":" + read_name_remaining_list[id] for id in range(nread_synthetic)]
                # Create output table (seqID is not chr, but for isoform name)
                reads_cur = pd.DataFrame({
                    'seqID': isoform_name,
                    'r1_start_shifted': synthetic_read_start_list,
                    'r1_end_shifted': np.clip(synthetic_read_start_list + read_len, None, isoform_len), # make sure read is within transcript length
                    'read_name': read_name_list,
                    'read_length': read_len,
                    'strand': synthetic_read_strand_list
                    })
                reads_cur.to_csv("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
        # Output ground truth isoform read count matrix
        UMIcountmat_perisoform_percell = np.vstack(UMIcountmat_perisoform_percell_list)
        UMIcountmat_perisoform_percell_pd = pd.DataFrame(UMIcountmat_perisoform_percell, index=isoform_prop_df['IsoformID'])
        UMIcountmat_perisoform_percell_pd.to_csv('%s/IsoformSyntheticRead.UMIcountmatrix.txt' % outdirectory, sep="\t", header=False)
        print("\n[scIsoSim] Created:")
        print("[scIsoSim] Isoform UMI count matrix file: %s/IsoformSyntheticRead.UMIcountmatrix.txt" % (outdirectory))
        print("[scIsoSim] Read bed file: %s/%s.read.bed" % (outdirectory, read_bedfile_prename))
    elif sequencing_protocol == "SmartSeq2":
        read_len = read_len_smartseq
        if 2*read_len > 200:
            print("[scIsoSim Warning] Read length, specified as %s, might lead to overlapped read1 and read2 (2 * %s is larger than the minimal SmartSeq2 fragment length 200 bp)." % (read_len, read_len))
        with open("%s/%s.read1.bed" % (outdirectory, read_bedfile_prename), 'w') as f_1:
            pass
        with open("%s/%s.read2.bed" % (outdirectory, read_bedfile_prename), 'w') as f_2:
            pass
        try: 
            if fragment_size_ditribution_file is not None:
                print("[scIsoSim] Detected input fragment_size_ditribution_file: %s" % (fragment_size_ditribution_file))
            else:
                fragment_size_ditribution_file = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data/smartseq2/smartseq2_CMP.fragmentSize_Real.txt')
                # fragment_size_ditribution_file = "/home/guanao/Projects/scIsoSim/results/20230216_SmartSeq2/fragmentSize_Real.txt"
        except ValueError:
            print("[scIsoSim] No input fragment_size_ditribution_file specified for %s protocol. " % (sequencing_protocol))
        if read_start_empdist_dir is not None:
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        else:
            read_start_empdist_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), 'data/smartseq2/smartseq2_CMP.readcoverage.csv')
            read_start_empdist_df = pd.read_csv(read_start_empdist_dir, header=0, delimiter=",")
        read_start_empdist = read_start_empdist_df.iloc[:,1:].sum(axis=0)
        # Read in real fragment length dist.
        real_fragment_df = pd.read_csv(fragment_size_ditribution_file, delimiter="\t", skiprows=[0])
        # real_fragment_df = pd.read_csv("/home/guanao/Projects/scIsoSim/results/20230216_SmartSeq2/fragmentSize_Real.txt", delimiter="\t", skiprows=[0])
        real_fragment_dist = real_fragment_df['Size'].repeat(real_fragment_df['Occurrences']).reset_index(drop=True)
        # Create isoform per cell synthetic read count matrix
        countmat_perisoform_percell_list = []
        for metagene_cur_id in tqdm(range(len(metagene_list))):
            metagene_cur = metagene_list[metagene_cur_id]
            rec = metagene_cur.split("_")       
            ## Synthetic data   
            # Synthetic isoform proportion  
            isoform_prop_df_cur = isoform_prop_df.loc[isoform_prop_df['MetageneID'] == metagene_cur]
            # Synthetic read pair count per gene  
            count_permetagene = sub_count_mat[np.where(open_peak_df == metagene_cur)[0],:].flatten()
            # Sample synthetic isoform-level UMI count from isoform prop. and gene-wise UMI count: n_isoform by n_subcell
            isoform_level_count = np.transpose(rng.multinomial(n=count_permetagene, pvals=isoform_prop_df_cur['Proportion'])) # sample multinomial for each cell with different experments number (size = 1)
            isoform_nonzero_id = np.nonzero(isoform_level_count.sum(axis=1))[0]
            countmat_perisoform_percell_list.append(isoform_level_count) # store isoform level count matrix into tmp list
            for isoform_id in isoform_nonzero_id:
                isoform_name = isoform_prop_df_cur.iloc[isoform_id]['IsoformID']
                # isoform_name = isoform_prop_df.iloc[isoform_id]['IsoformID']
                print("[scIsoSim] Generating Synthetic Reads for Gene %s Isoform %s" % (metagene_cur, isoform_name))
                # Sample syntheitc read pairs
                count_vec = isoform_level_count[isoform_id,:] # Synthetic read count
                paircount_vec = np.rint(count_vec/2).astype(int)
                nonzer_count_zero_id = np.nonzero(paircount_vec)[0]
                nreadpair_synthetic = sum(paircount_vec) # total number of synthetic read pair
                # Sample synthetic read starting position (relative to transcripts)
                isoform_len = len(transcript_dict[isoform_name].seq)
                # If isoform length is smaller than 200 bp, then no fragment is generated for the current isoform
                if isoform_len < read_len:
                    print("[scIsoSim Warning] Isoform %s length is smaller than specified read length %s bp. Skip the isoform." % (isoform_name, read_len))
                    continue
                if smartseq_mode == "mechanistic":
                    ## Uniform sampling
                    fragment_start_list = np.random.randint(low=1, high=isoform_len-fragment_len + 1)
                    # Fragment length
                    real_fragment_dist_trun = real_fragment_dist[real_fragment_dist.between(read_len, isoform_len-1)]
                    fragment_len = np.random.choice(real_fragment_dist_trun, size=nreadpair_synthetic)
                elif smartseq_mode == "empirical":
                    # Starting position
                    # modified by weijian
                    fragment_start_list = sampleStartPosSmartSeq(isoform_len=isoform_len-1, size=nreadpair_synthetic, freq_list=read_start_empdist)
                    # Fragment length uniform [200, 600]: here!
                    fragment_length_max = isoform_len - fragment_start_list
                    fragment_len = []
                    read_len_list = []
                    for fragment_max in fragment_length_max:
                        if fragment_max < 75:
                            fragment_len.append(fragment_max)
                            read_len_list.append(fragment_max)
                        else:
                            fragment_length_tmp = real_fragment_dist[real_fragment_dist.between(read_len, fragment_max)]
                            fragment_length_tmp = np.random.choice(fragment_length_tmp, size=1)
                            fragment_len.append(fragment_length_tmp[0])
                            read_len_list.append(read_len)
                    # real_fragment_dist_trun = real_fragment_dist[real_fragment_dist.between(read_len, isoform_len-1)]
                    # fragment_len = np.random.choice(real_fragment_dist_trun, size=nreadpair_synthetic)
                fragment_end_list = fragment_start_list + fragment_len # should be small or equal to isoform_lenth + 1 [0, isform+length)
                synthetic_read1_start_list = fragment_start_list
                synthetic_read2_start_list = fragment_end_list - read_len_list # no need to plus 1
                # Assign strand infor to synthetic reads (relative to transcripts; for single-end read, should be +, since transcripts already contain strand infor)
                synthetic_read1_strand_list = ["+"] * nreadpair_synthetic
                synthetic_read2_strand_list = ["-"] * nreadpair_synthetic
                # Organize syntheitc CB string
                # print(len(paircount_vec))
                # print(len(np.array(sub_cell_barcode)[nonzer_count_zero_id]))
                CB_synthetic_list = np.repeat(np.array(sub_cell_barcode)[nonzer_count_zero_id], paircount_vec[nonzer_count_zero_id])
                # Create syntheitc read name string
                read_name_remaining_list = [str(metagene_cur) + ":"+ str(isoform_name) + "#" + str(count).zfill(4) for ind in range(len(paircount_vec)) for count in range(paircount_vec[ind])]
                read_name_list = [CB_synthetic_list[id] + ":" + read_name_remaining_list[id] for id in range(nreadpair_synthetic)]
                # Create output table (seqID is not chr, but for isoform name)
                reads1_cur = pd.DataFrame({
                    'seqID': isoform_name,
                    'r1_start_shifted': synthetic_read1_start_list,
                    'r1_end_shifted': np.clip(synthetic_read1_start_list + read_len_list, None, isoform_len), # make sure read is within transcript length
                    'read_name': read_name_list,
                    'read_length': read_len_list,
                    'strand': synthetic_read1_strand_list
                    })
                reads1_cur.to_csv("%s/%s.read1.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
                # Create output table (seqID is not chr, but for isoform name)
                reads2_cur = pd.DataFrame({
                    'seqID': isoform_name,
                    'r2_start_shifted': synthetic_read2_start_list,
                    'r2_end_shifted': np.clip(synthetic_read2_start_list + read_len_list, None, isoform_len), # make sure read is within transcript length
                    'read_name': read_name_list,
                    'read_length': read_len_list,
                    'strand': synthetic_read2_strand_list
                    })
                reads2_cur.to_csv("%s/%s.read2.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
        # Output ground truth isoform read count matrix
        countmat_perisoform_percell = np.vstack(countmat_perisoform_percell_list)
        countmat_perisoform_percell_pd = pd.DataFrame(countmat_perisoform_percell, index=isoform_prop_df['IsoformID'])
        countmat_perisoform_percell_pd.to_csv('%s/IsoformSyntheticRead.countmatrix.txt' % outdirectory, sep="\t", header=False)
        print("\n[scIsoSim] Created:")
        print("[scIsoSim] Isoform UMI count matrix file: %s/IsoformSyntheticRead.countmatrix.txt" % (outdirectory))
        print("[scIsoSim] Read1 bed file: %s/%s.read1.bed" % (outdirectory, read_bedfile_prename))
        print("[scIsoSim] Read2 bed file: %s/%s.read2.bed" % (outdirectory, read_bedfile_prename))

        

def extract_sequence(referenceTranscriptome, transcript_id):
    """Extract and print the sequence for a given transcript ID."""
    records = SeqIO.parse(referenceTranscriptome, 'fasta')
    for record in records:
        if record.id == transcript_id:
            return record.seq

def extract_sequence_genome(row, reference_genome):
    seqname = row['seqname']  # Chromosome or contig name
    start = int(row['start']) - 1  # Convert to 0-based index for Biopython
    end = int(row['end'])
    strand = row['strand']
    
    # Extract the sequence from the genome
    sequence = reference_genome[seqname].seq[start:end]
    
    # If the strand is negative, we need to reverse complement the sequence
    if strand == '-':
        sequence = sequence.reverse_complement()
    
    return str(sequence)

def find_edit_position(sequence, mut_percentile, intron_start, intron_end, strand, char='A'):
    if intron_start is not None and intron_end is not None:
        if strand == "+":
            mut_percentile = mut_percentile
        else:
            mut_percentile = 1 - mut_percentile
        position = int((intron_end - intron_start)*mut_percentile)
        for i in range(intron_start + position, intron_end):
            if sequence[i] == char:
                index = i
                break
        return index  
    else:  
        """Automatically generate the position of A to G mutation"""
        position = int(len(sequence) * mut_percentile)
        for i in range(position, len(sequence)):
            if sequence[i] == char:
                index = i
                break
        return index  

def mutate_sequence(sequence, position, original_base, new_base,strand):
    """Introduce a mutation at a specific position in the sequence."""
    if strand == "-":
        sequence_list = list(sequence)
        complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
        if  sequence_list[len(sequence_list)-position-1] == complement[original_base]:
            sequence_list[len(sequence_list)-position-1] = complement[new_base]
            return ''.join(sequence_list)
    else:
        sequence_list = list(sequence)
        if sequence_list[position] == original_base:
            sequence_list[position] = new_base
        return ''.join(sequence_list)

def get_complementary_sequence(sequence):
    # Define the complement mapping
    complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
    
    # Generate the complementary sequence
    complementary_sequence = ''.join(complement[base] for base in sequence)
    
    return complementary_sequence

