def generate_intron_retention(isoform_proportion_file, outdirectory, isoform_annotation_file, n_editing=None,max_intron_length = 3000,n_retained_intron = 1):
    df = pd.read_csv(isoform_annotation_file, sep='\t', comment='#', header=None, names=[
        'seqname', 'source', 'feature', 'start', 'end', 'score', 'strand', 'frame', 'attribute'])
    df = df[df['feature'].isin(['transcript', 'exon'])]
    isoform_prop_df = pd.read_csv("%s" % (isoform_proportion_file), header=0, delimiter="\t")
    isoform_prop_df['IR'] = 'N'
    # Randomly choose n_editing rows
    isoform_prop_df = isoform_prop_df.head(n=n_editing)
    transcriptome_contain_intron = pd.DataFrame()
    # Process the DataFrame
    for metageneid, group in isoform_prop_df.groupby('MetageneID'):
        if len(group) == 1:
            transcript_id = isoform_prop_df.loc[group.index, 'IsoformID'].values[0]
            transcript_df = df[df['attribute'].str.contains(f'ID={transcript_id}|Parent={transcript_id}')]
            count_exon = transcript_df[transcript_df['feature'] == 'exon'].shape[0]
            exon_df = transcript_df[transcript_df['feature'].isin(['exon'])]
            exon_df['transcript'] = transcript_id
            # deal with condition the same transcript id would be found in different chromosomes
            if exon_df['seqname'].nunique() != 1:
                continue
            strand = exon_df.iloc[0]['strand']
            introns = []
            for i in range(1, len(exon_df)):
                if strand == '+':
                    intron_start = exon_df.iloc[i-1]['end'] + 1
                    intron_end = exon_df.iloc[i]['start'] - 1
                elif strand == '-':
                    intron_start = exon_df.iloc[i]['end'] + 1
                    intron_end = exon_df.iloc[i-1]['start'] - 1
                
                if intron_start <= intron_end:  # Valid intron
                    intron = {
                        'seqname': exon_df.iloc[i]['seqname'],
                        'source': exon_df.iloc[i]['source'],
                        'feature': 'intron',
                        'start': intron_start,
                        'end': intron_end,
                        'score': '.',
                        'strand': strand,
                        'frame': '.',
                        'attribute': exon_df.iloc[i]['attribute'],
                        'length':intron_end - intron_start + 1
                    }
                    introns.append(intron)
            intron_df = pd.DataFrame(introns)
            
            if count_exon > 1 and intron_df['length'].min() < max_intron_length:
                isoform_prop_df.loc[group.index, 'IR'] = 'Y'
                
                selected_intron = pd.DataFrame(introns)
                selected_intron = selected_intron[selected_intron['length']<max_intron_length]
                if n_retained_intron ==1:
                    intron_df = selected_intron.sample(n=1)
                elif n_retained_intron == "all":
                    intron_df = selected_intron
                intron_df['transcript'] = transcript_id
                intron_df = intron_df.drop(columns=['length'])
                result_df = pd.concat([exon_df, intron_df], ignore_index=True)
                if result_df.iloc[0]['strand'] == "+":
                    result_df = result_df.sort_values(by=['start'])
                else:
                    result_df = result_df.sort_values(by=['start'],ascending=False)
            else:
                isoform_prop_df.loc[group.index, 'IR'] = 'N'
                result_df = exon_df
            
        # else:
        #     random_choice = np.random.choice(group.index, 1)
        #     isoform_prop_df.loc[random_choice, 'IR_retention'] = 'Y'
        #     result_df = exon_df
        transcriptome_contain_intron = pd.concat([transcriptome_contain_intron,result_df],ignore_index=True)
    transcriptome_contain_intron.to_csv("%s/%s.csv" % (outdirectory, "isoform_structure_contain_intron"), index=None, sep='\t', mode='a')

    output_df = isoform_prop_df[['IsoformID','IR']]
    # Save to a new file
    output_file_path =  outdirectory + "/" + "IR.csv" # Replace with the desired output file path
    output_df.to_csv(output_file_path, sep='\t', index=False, header=['isoform_name','IR'])
    print("The IR event has been saved to", output_file_path)
    
def incorporate_intron_in_reference_transcriptome(referenceTranscriptome,referenceGenome_file,outdirectory, isoform_structure_file):
    isoform_structure_df = pd.read_csv(isoform_structure_file, delimiter='\t')
    reference_genome = SeqIO.to_dict(SeqIO.parse(referenceGenome_file, "fasta"))

    # extract sequence from reference genome
    concatenated_sequences = {}
    current_transcript_id = None
    full_sequence = Seq("")
    strand = None
    records = list(SeqIO.parse(referenceTranscriptome, 'fasta'))
    # Iterate over each row in the DataFrame
    for index, row in isoform_structure_df.iterrows():
        transcript_id = row['transcript']
        # Check if we are processing a new transcript
        if transcript_id != current_transcript_id:
            if current_transcript_id is not None:
                concatenated_sequences[current_transcript_id] = str(full_sequence)
                for record in records:
                    if record.id == current_transcript_id:
                        record.seq = Seq(concatenated_sequences[current_transcript_id])
            # Initialize for new transcript
            current_transcript_id = transcript_id
            full_sequence = Seq("")  # Reset the sequence for the new transcript
            strand = row['strand']  # Store the strand information
        
        # Extract the sequence for the current row and add it to the full sequence
        seq = extract_sequence_genome(row, reference_genome)
        full_sequence += Seq(seq)
    # Add the last transcript's sequence
    if current_transcript_id is not None:
        concatenated_sequences[current_transcript_id] = str(full_sequence)
        for record in records:
                    if record.id == current_transcript_id:
                        record.seq = Seq(concatenated_sequences[current_transcript_id])
    SeqIO.write(records, outdirectory + "/"+"transcripts_contain_IR.fa", 'fasta')
    print('Modified sequence have been saved')
            
            
        
        
        

        

def generateEditedTranscriptome(referenceTranscriptome_contain_IR,outdirectory,isoform_annotation_file, isoform_annotation_file_for_intron,editing_level_file,mut_percentile=0.2):
    transcript_df = pd.read_csv(isoform_annotation_file, sep='\t', comment='#', header=None, names=[
        'seqname', 'source', 'feature', 'start', 'end', 'score', 'strand', 'frame', 'attribute'])
    transcript_df_intron = pd.read_csv(isoform_annotation_file_for_intron, sep='\t', comment='#', header=None, names=[
        'seqname', 'source', 'feature', 'start', 'end', 'score', 'strand', 'frame', 'attribute','transcript'])
    edit_level_df = pd.read_csv(editing_level_file,sep='\t')
    with open(editing_level_file, 'r') as file:
        header = file.readline()
    # Loop through each line in the file
        transcript_id = []
        edit_pos = []
        orig_seq = []
        chr = []
        start = []
        end = []
        edit_position_whole_genome = []
        edit_position_relatve_transcript_without_strand = []
        edit_level = []
        mutation_place_list = []
        strand_list = []
        for line in file:
            elements = line.strip().split()
            isoform_id = elements[0]
            mutation_place = elements[2]
            mutation_place_list.append(mutation_place)
            if mutation_place == "intron":
                transcript_df_used = transcript_df_intron
                isoform_rows = transcript_df_used[transcript_df_used['attribute'].str.contains(isoform_id)]
                strand = isoform_rows['strand'].unique()[0]
                if strand == "+":
                    intron_start = find_intron_position(isoform_rows)[0]
                    intron_end = find_intron_position(isoform_rows)[1]
                else:
                    isoform_rows = isoform_rows.iloc[::-1].reset_index(drop=True)
                    intron_start = find_intron_position(isoform_rows)[0]
                    intron_end = find_intron_position(isoform_rows)[1]
            else:
                transcript_df_used = transcript_df
                isoform_rows = transcript_df_used[transcript_df_used['attribute'].str.contains(isoform_id)]
                strand = isoform_rows['strand'].unique()[0]
                intron_start = None
                intron_end = None
            transcript_id.append(isoform_id)
            seq = str(extract_sequence(referenceTranscriptome_contain_IR,isoform_id))
            if strand == "+" :
                orig_seq.append(list(seq)[find_edit_position(seq,mut_percentile,intron_start,intron_end,strand)]) 
            else:
            # if a transctipt is on the reverse strand of the DNA, the transcript.fa sequence should be
            # first reverse and then complemented. and the records in the gtf file, the exons position 
            # starts from far position to low position. 
                seq = get_complementary_sequence(seq[::-1])
                orig_seq.append(list(seq)[find_edit_position(seq,mut_percentile,intron_start,intron_end,strand)]) 
            strand_list.append(strand)
            edit_pos.append(find_edit_position(seq,mut_percentile,intron_start,intron_end,strand))
            chr.append(isoform_rows.iloc[0]['seqname'])
            start.append(isoform_rows['start'].min())
            end.append(isoform_rows['end'].max())
            edit_position_whole_genome.append(find_nucleotide_position_relateve_genome(isoform_rows,find_edit_position(seq,mut_percentile,intron_start,intron_end,strand),strand))
            if strand == "+":
                edit_position_relatve_transcript_without_strand.append(find_edit_position(seq,mut_percentile,intron_start,intron_end,strand))
            else:
                edit_position_relatve_transcript_without_strand.append(len(seq)-find_edit_position(seq,mut_percentile,intron_start,intron_end,strand)-1)
            edit_level.append(edit_level_df.loc[edit_level_df['isoform_name'] == isoform_id, 'editing_level'].values[0])
    Edit_df = pd.DataFrame({
            'isoform_name': transcript_id,
            'editing_position':edit_pos,
            'orig_seq':orig_seq,
            "mutated_seq":'G',
            'chr': chr,
            'start':start,
            'end':end,
            'edit_position_whole_genome':edit_position_whole_genome,
            'edit_level':edit_level,
            'strand':strand_list,
            'mutation_place': mutation_place_list,
            'edit_position_relatve_transcript_without_strand':edit_position_relatve_transcript_without_strand
            })
    Edit_df.to_csv("%s/%s.csv" % (outdirectory, "editing_position"), index=None, sep='\t', mode='a')
    isoform_vec = list(Edit_df['isoform_name'])
    records = SeqIO.parse(referenceTranscriptome_contain_IR, 'fasta')
    modified_records = []
    for record in records:
        if record.id in isoform_vec:
            mutation_position = Edit_df[Edit_df['isoform_name'] == record.id]['editing_position'].tolist()[0]
            mutation_place = Edit_df[Edit_df['isoform_name'] == record.id]['mutation_place'].tolist()[0]
            original_base = Edit_df[Edit_df['isoform_name'] == record.id]['orig_seq'].tolist()[0]
            new_base = Edit_df[Edit_df['isoform_name'] == record.id]['mutated_seq'].tolist()[0]
            strand = Edit_df[Edit_df['isoform_name'] == record.id]['strand'].tolist()[0]
            seq = record.seq
            modified_seq = mutate_sequence(str(seq), mutation_position, original_base, new_base,strand)
            record.seq = Seq(str(modified_seq))
            if mutation_place == 'intron':
                record.id = record.id + "_with_intron"
                record.name = record.name + "_with_intron"
                record.description = record.description + ' with intron'
        modified_records.append(record)

    SeqIO.write(modified_records, outdirectory+"/"+"transcripts_contain_IR_edited.fa", 'fasta')
    print(f'Modified sequence saved to {outdirectory+"/"+"transcripts_contain_IR_edited.fa"}')

def optimize_reference_transcriptome(referenceTranscriptome,referenceTranscriptome_contain_IR,outdirectory,isoform_proportion_file,IR_list,retained_intron_prop_mean=0.1,retained_intron_prop_sd = 0.02):
    IR_df = pd.read_csv(IR_list,sep='\t')
    # editing_position_df = pd.read_csv(editing_position_file,sep='\t')
    reference = list(SeqIO.parse(referenceTranscriptome, 'fasta'))
    reference_contain_IR = SeqIO.parse(referenceTranscriptome_contain_IR, "fasta")
    isoform_prop_df = pd.read_csv("%s" % (isoform_proportion_file), header=0, delimiter="\t")
    reference_dict = {record.id: record for record in reference_contain_IR}
    #
    for index, row in IR_df.iterrows():
        if row['IR'] == 'Y':
            isoform_name = row['isoform_name']
            intron_isoform_name = f"{isoform_name}_with_intron"
            
            # Find the corresponding sequence in reference
            seq_record = reference_dict[isoform_name]
            
            # Create a new SeqRecord for the intron-modified transcript
            new_seq_record = seq_record[:]
            new_seq_record.id = intron_isoform_name
            new_seq_record.name = intron_isoform_name
            new_seq_record.description = f"{seq_record.description} (with intron modification)"
            
            # Add to reference_contain_IR
            reference.append(new_seq_record)
            # Update isoform_prop_df
            # Modify proportion for the original isoform
            # new_proportion = random.uniform(1-intron_retention_rate-0.05, 1-intron_retention_rate + 0.05)
            new_proportion = np.random.normal(retained_intron_prop_mean, retained_intron_prop_sd)
            isoform_prop_df.loc[isoform_prop_df['IsoformID'] == isoform_name, 'Proportion'] = 1 - new_proportion
            
            # Add a new row for the intron-modified transcript
            new_row = {
                'MetageneID': isoform_prop_df.loc[isoform_prop_df['IsoformID'] == isoform_name, 'MetageneID'].values[0],
                'Genes': isoform_prop_df.loc[isoform_prop_df['IsoformID'] == isoform_name, 'Genes'].values[0],
                'IsoformID': intron_isoform_name,
                'Proportion': new_proportion
            }
            isoform_prop_df = pd.concat([isoform_prop_df, pd.DataFrame([new_row])], ignore_index=True)

    # Convert reference_contain_IR back to a SeqRecord list
    reference_contain_IR_records = reference

    # Save the updated isoform_prop_df (optional)
    df = pd.DataFrame(columns=['MetageneID','Genes','IsoformID','Proportion'])
    df.to_csv("%s" % (outdirectory + "/" + "IsoformProportion_intron_retained.txt"), index=None, sep='\t')
    isoform_prop_df.to_csv(outdirectory + "/" + "IsoformProportion_intron_retained.txt",header=None, index=None, sep='\t', mode='a')

    # Save the updated reference_contain_IR
    SeqIO.write(reference_contain_IR_records, referenceTranscriptome_contain_IR, "fasta")
    # with open(referenceTranscriptome_contain_IR, "w") as output_handle:
    #     SeqIO.write(reference_contain_IR, output_handle, "fasta")
    # edit_level_df['isoform_name'] = edit_level_df.apply( lambda row: row['isoform_name'] + '_with_intron' if row['mutation_place'] == 'intron' else row['isoform_name'], axis=1)
    # edit_level_df.to_csv(outdirectory + "/" + "editing_level_celltype1.csv",sep='\t', index=False, header=['isoform_name', 'editing_level','mutation_place'])
    # editing_position_df['isoform_name'] = editing_position_df.apply( lambda row: row['isoform_name'] + '_with_intron' if row['mutation_place'] == 'intron' else row['isoform_name'], axis=1)
    # editing_position_df.to_csv(editing_position_file,sep='\t', index=False)


def seperateBed(editing_position_file, original_bed,outdirectory, read_bedfile_prename):
    edit_pos = pd.read_csv(editing_position_file,delimiter="\t")
    bed_data = pd.read_csv(original_bed, sep='\t', header=None)
    bed_data_for_trim = bed_data
    # Extract the first three columns for matching purposes
    bed_data_for_matching = bed_data.iloc[:, :3]
    bed_data_for_matching.columns = ['isoform_name', 'start', 'end']
    # Create empty dataframes for matched and unmatched rows
    matched_data = pd.DataFrame(columns=bed_data.columns)
    unmatched_data = pd.DataFrame(columns=bed_data.columns)
    for _, row in edit_pos.iterrows():
        isoform_name = row['isoform_name']
        editing_position = row['edit_position_relatve_transcript_without_strand']
        editing_level = edit_pos.loc[edit_pos['isoform_name'] == isoform_name, 'edit_level'].values[0]
        # Filter the BED data for matching isoform names
        matching_isoforms = bed_data_for_matching[bed_data_for_matching['isoform_name'] == isoform_name]
        
        # Check if the editing position is within the range of start and end positions
        within_range = matching_isoforms[
            (matching_isoforms['start'] <= int(editing_position)) & 
            (matching_isoforms['end'] >= int(editing_position))
        ]
        
        # Get the corresponding full rows from the original bed_data
        if not within_range.empty:
            matched_full_rows = bed_data.iloc[within_range.index]
        
        # Randomly select rows to move to unmatched_data
        sample_size = max(1, int((1-editing_level) * len(matched_full_rows)))  # Ensure at least one row is selected if possible
        matched_data_sample = matched_full_rows.sample(n=sample_size, random_state=42)
        
        # Append the selected rows to the unmatched data
        unmatched_data = pd.concat([unmatched_data, matched_data_sample])
        
        # Remove the selected rows from the matched_full_rows
        matched_full_rows = matched_full_rows.drop(matched_data_sample.index)
        
        # Add the remaining rows to matched_data
        matched_data = pd.concat([matched_data, matched_full_rows])
    
         # Get rows that are outside of the within_range and add them to unmatched_data
        outside_range = matching_isoforms.index.difference(within_range.index)
        unmatched_full_rows = bed_data.iloc[outside_range]
        unmatched_data = pd.concat([unmatched_data, unmatched_full_rows])
        bed_data_for_trim = bed_data_for_trim[bed_data_for_trim.iloc[:, 0] != isoform_name]
    if not bed_data_for_trim.empty:
        unmatched_data = pd.concat([unmatched_data,bed_data_for_trim])
    matched_data.to_csv(outdirectory + "/" + read_bedfile_prename +'.read.edited.read.bed', sep='\t', header=False, index=False)
    unmatched_data.to_csv(outdirectory + "/" + read_bedfile_prename + '.read.unedited.read.bed', sep='\t', header=False, index=False)       
    

def find_nucleotide_position_relateve_genome(isoform_rows,nucleotide_index,strand):
    # if isoform_rows.iloc[0]['start'] == isoform_rows.iloc[1]['start'] and isoform_rows.iloc[0]['end'] == isoform_rows.iloc[1]['end']:
    # # Drop the first row
    #     isoform_rows = isoform_rows.drop(isoform_rows.index[0])
    isoform_rows = isoform_rows[isoform_rows['feature'].isin(['intron','exon'])]
    if strand == "-":
        if isoform_rows.shape[0] > 1:  # Check if there are multiple rows
            if isoform_rows.iloc[0, 3] > isoform_rows.iloc[-1, 3]:  # Check if the first row's  start value is greater than the last row's start  value
                isoform_rows = isoform_rows.iloc[::-1]
    cumulative_length = 0
    for _, exon in isoform_rows.iterrows():
        exon_length = int(exon['end']) - int(exon['start']) + 1
        if cumulative_length + exon_length >= nucleotide_index:
            position_in_exon = nucleotide_index - cumulative_length
            genomic_position = int(exon['start']) + position_in_exon
            return(genomic_position) 
        cumulative_length += exon_length


def find_intron_position(input_df):
    # Initialize variables to track relative position and concatenation
    current_position = 0
    positions = []
    for _, row in input_df.iterrows():
        length = int(row['end']) - int(row['start']) + 1
        if row['feature'] == 'intron':
            # Calculate the relative position of the intron
            relative_position_start = current_position - 1
            relative_position_end = current_position - 1 + length
            positions.append(relative_position_start)
            positions.append(relative_position_end)

        current_position += length

    return pd.Series(positions)

# Helper function to extract the allele value from the 'Substitution' object string
def extract_alt_allele(alt_obj):
    if isinstance(alt_obj, vcfpy.Substitution):
        return alt_obj.value  # Extract the value attribute from Substitution objects
    else:
        return str(alt_obj)  # Handle cases where alt_obj is already a string

##################################################################################################################
# extract tissue-specific-RED list and SNV list
# old function for scEditSim: samples 33% of 3' UTR RNA editing sites and extract rna editing sites from REDIportal
##################################################################################################################
def get_SNP_RED_list(INPUT_SNP_site,INPUT_RED_site, outdirectory, threeprime_scale_factor=1,min_edit = 0.05, max_edit = 0.95, tissue = "Lung",include_SNPs = True):
    snps = []
    reader = vcfpy.Reader.from_path(INPUT_SNP_site)
    # for record in reader:
    #     chrom = record.CHROM
    #     pos = record.POS
    #     ref = record.REF
        
    #     # Extract alternate alleles, converting Substitution objects to strings
    #     alt_alleles = [extract_alt_allele(alt) for alt in record.ALT]
        
    #     # Extract CAF values directly as a list of frequencies, handling None and missing values
    #     caf_values = record.INFO.get('CAF', [])
    #     frequencies = [float(freq) if isinstance(freq, (str, float, int)) and freq not in ['.', None] else 0.0 for freq in caf_values]
        
    #     # Pair each alternate allele with its frequency, or assign 0.0 if frequency is missing
    #     for alt, freq in zip(alt_alleles, frequencies):
    #         snps.append({
    #             'chrom': chrom,
    #             'pos': pos,
    #             'ref': ref,
    #             'alt': alt,
    #             'freq': freq
    #         })
    for record in reader:
        chrom = record.CHROM
        pos = record.POS
        ref = record.REF
        
        # Extract alternate alleles, converting Substitution objects to strings
        alt_alleles = [extract_alt_allele(alt) for alt in record.ALT]
        
        # Extract CAF values directly as a list of frequencies, handling None and missing values
        caf_values = record.INFO.get('CAF', [])
        frequencies = [float(freq) if isinstance(freq, (str, float, int)) and freq not in ['.', None] else 0.0 for freq in caf_values]
        
        # Ensure that frequencies include the reference frequency as the first value
        if frequencies:
            ref_freq = frequencies[0]  # Reference allele frequency
            alt_freq = frequencies[1] if len(frequencies) > 1 else 0.0  # Minor allele frequency (or 0.0 if missing)
        else:
            ref_freq = 0.0
            alt_freq = 0.0

        # Pair each alternate allele with its minor allele frequency
        for alt in alt_alleles:
            snps.append({
                'chrom': chrom,
                'pos': pos,
                'ref': ref,
                'alt': alt,
                'freq': alt_freq  # Minor allele frequency as the second value
            })
    snps_df = pd.DataFrame(snps)
     # keep only SNVs in the result
    snps_df = snps_df[(snps_df['ref'].str.len() == 1) & 
                      (snps_df['alt'].str.len() == 1) & 
                      (snps_df['ref'].isin(['A', 'T', 'C', 'G'])) & 
                      (snps_df['alt'].isin(['A', 'T', 'C', 'G']))]
    snps_df = snps_df.drop_duplicates(subset=['chrom', 'pos'], keep='first')
    red_df = pd.read_csv(INPUT_RED_site,delimiter="\t")
    red_df_edit_level_per_tissue = red_df['PlotsBody'].str.split('-', expand=True)
    column_names = [
    "Adipose-Subcutaneous", "Adipose-Visceral", "Adrenal_Gland", "Artery-Aorta", "Artery-Coronary", 
    "Artery-Tibial", "Bladder", "Brain-Amygdala", "Brain-Anterior_cingulate_cortex", "Brain-Caudate", 
    "Brain-Cerebellar Hemisphere", "Brain-Cerebellum", "Brain-Cortex", "Brain-Frontal Cortex", "Brain-Hippocampus", 
    "Brain-Hypothalamus", "Brain-Nucleus-accumbens", "Brain-Putamen", "Brain-Spinal cord", "Brain-Substantia nigra", 
    "Breast-Mammary tissue", "Cells-EBV-transformed_lymphocytes", "Cells-Leukemia cell line", "Cells-Transformed_fibroblast", "Cervix-Ectocervix", "Cervix-Endocervix",
    "Colon-Sigmoid", "Colon-Transverse", "Esophagus-Gastroesophageal_Junction", "Esophagus-Mucosa", "Esophagus-Muscularis", 
    "Fallopian_Tube", "Heart-Atrial Appendage", "Heart-Left_Ventricle", "Kidney", "Kidney-Cortex", 
    "Liver", "Lung", "Minor_Salivary_Gland.", "Muscle-Abdominal_Striated", "Muscle-Skeletal",
    "Nerve-Tibial", "Ovary", "Pancreas", "Pituitary", "Prostate", 
    "Skin-Not_Sun_Exposed", "Skin-Sun_Exposed", "Small_Intestine-Terminal_ileum", "Spleen", "Stomach", 
    "Testis", "Thyroid", "Uterus", "Vagina", "Whole-Blood"]

    red_df_edit_level_per_tissue.columns = column_names
    red_df = pd.concat([red_df,red_df_edit_level_per_tissue], axis=1)

    red_df[tissue] = red_df[tissue].apply(lambda x: [float(i) for i in x.split(',') if i != ''])

    # only keep editing sites in the specified tissue with editing level > 0 
    red_df_filtered = red_df[red_df[tissue].apply(lambda x: not all(i == 0 for i in x))]
    
    # mean editing level got from GTEx were the first value --> use for simulation
    red_df_filtered[tissue] = red_df_filtered[tissue].apply(lambda x: x[0] if len(x) > 0 else 0 )
    
    red_df_filtered = red_df_filtered[red_df_filtered['Func.wgEncodeGencodeBasicV45'].isin(['intronic', 'exonic', 'UTR3', 'UTR5'])]
    
    # Filter rna editing sites that are also snps
    red_df_filtered = red_df_filtered[~red_df_filtered['Position'].isin(snps_df['pos'])]
    red_df_filtered = red_df_filtered[['Accession','Region','Position','Ref','Ed','Strand','type','Func.wgEncodeGencodeBasicV45','Gene.wgEncodeGencodeBasicV45',tissue]]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue]>= min_edit]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue]<= max_edit]

    # shrink the number of editing sites in 3' UTR
    utr3_mask = red_df_filtered['Func.wgEncodeGencodeBasicV45'] == 'UTR3'
    non_utr3_mask = ~utr3_mask

    # Get UTR3 rows and sample 33% of them without replacement
    utr3_rows = red_df_filtered[utr3_mask]
    utr3_sample = utr3_rows.sample(frac=threeprime_scale_factor)  

    # Get non-UTR3 rows (keeping all of them)
    non_utr3_rows = red_df_filtered[non_utr3_mask]

    # Concatenate the sampled UTR3 rows with all non-UTR3 rows
    red_df_filtered = pd.concat([utr3_sample, non_utr3_rows])

    red_df_filtered.to_csv("%s" % (outdirectory + "/" + "RNA_editing_sites_levels.txt"), index=None, sep='\t')
    
    # select SNPs based on its frequencies
    # snps_df['keep'] = np.random.rand(len(snps_df)) > snps_df['freq']
    # snps_df['keep'] = np.random.rand(len(snps_df)) >=0
    snps_df['keep'] = snps_df['freq'] >= 0
    snps_df = snps_df[snps_df['keep']]
    # update 20250111 use all SNPs
    # snps_df = snps_df.sample(frac=0.5, random_state=2024)  # Use random_state for reproducibility
    #
    snps_df['chrom'] = 'chr' + snps_df['chrom'].astype(str)
    snps_df.columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep']
    homozygous_snp_size = len(snps_df)//2
    allelic = np.concatenate([
        ['homo']*(homozygous_snp_size),  # 50% of them as homozygous
        np.random.choice([0, 1],len(snps_df) - homozygous_snp_size)  
        ])
    np.random.shuffle(allelic)
    snps_df['allelic']=allelic
    snps_df['editing_level'] = 1
    
    snps_df_positive = snps_df.copy()
    snps_df_positive['Strand'] = "+"
    
    snps_df_negative = snps_df.copy()
    snps_df_negative['Strand'] = "-"
    
    # snps_df_negative['Ref'] = snps_df_negative['Ref'].apply(get_complement)
    # snps_df_negative['Ed'] = snps_df_negative['Ed'].apply(get_complement)
    snps_df = pd.concat([snps_df_positive,snps_df_negative])
    snps_df['category'] = 'snp'

    ## Do not include SNPs in simulation (used for black-list)
    if include_SNPs == False:
        snps_df = pd.DataFrame()
    
    # half_size = len(snps_df)//2
    # allelic_ratios = np.concatenate([
    #     np.ones(half_size),  # Half of them as 1
    #     np.random.normal(0.5, 0.15, len(snps_df) - half_size)  # Half with values from normal distribution
    #     ])
    # np.random.shuffle(allelic_ratios)
    # snps_df['editing_level'] = allelic_ratios
    #
    snps_df.to_csv("%s" % (outdirectory + "/" + "SNPs.txt"), index=None, sep='\t')
    
def prepare_SNP_RED_list(INPUT_SNP_site,INPUT_INDEL_site,INPUT_RED_site, outdirectory,min_edit = 0.05, max_edit = 0.95,tissue='Lung', include_SNPs = True):
    snps = []
    reader = vcfpy.Reader.from_path(INPUT_SNP_site)
    for record in reader:
        chrom = record.CHROM
        pos = record.POS
        ref = record.REF
        # Extract alternate alleles, converting Substitution objects to strings
        alt_alleles = [extract_alt_allele(alt) for alt in record.ALT]
        # Extract CAF values directly as a list of frequencies, handling None and missing values
        frequencies = float(record.INFO.get('AF', [0])[0])
        # caf_values = record.INFO.get('AF', [])
        # frequencies = [float(freq) if isinstance(freq, (str, float, int)) and freq not in ['.', None] else 0.0 for freq in caf_values]
        # Ensure that frequencies include the reference frequency as the first value
        # if frequencies:
        # 	ref_freq = frequencies[0]  # Reference allele frequency
        # 	alt_freq = frequencies[1] if len(frequencies) > 1 else 0.0  # Minor allele frequency (or 0.0 if missing)
        # else:
        # 	ref_freq = 0.0
        # 	alt_freq = 0.0
        # Pair each alternate allele with its minor allele frequency
        for alt in alt_alleles:
            snps.append({
                'chrom': chrom,
                'pos': pos,
                'ref': ref,
                'alt': alt,
                'freq': frequencies  # Minor allele frequency as the second value
            })
    snps_df = pd.DataFrame(snps)

    indels = []
    reader = vcfpy.Reader.from_path(INPUT_INDEL_site)
    for record in reader:
        chrom = record.CHROM
        pos = record.POS
        ref = record.REF
        # Extract alternate alleles, converting Substitution objects to strings
        alt_alleles = [extract_alt_allele(alt) for alt in record.ALT]
        # Extract CAF values directly as a list of frequencies, handling None and missing values
        frequencies = float(record.INFO.get('AF', [0])[0])
        # caf_values = record.INFO.get('AF', [])
        # frequencies = [float(freq) if isinstance(freq, (str, float, int)) and freq not in ['.', None] else 0.0 for freq in caf_values]
        # Ensure that frequencies include the reference frequency as the first value
        # if frequencies:
        # 	ref_freq = frequencies[0]  # Reference allele frequency
        # 	alt_freq = frequencies[1] if len(frequencies) > 1 else 0.0  # Minor allele frequency (or 0.0 if missing)
        # else:
        # 	ref_freq = 0.0
        # 	alt_freq = 0.0
        # Pair each alternate allele with its minor allele frequency
        for alt in alt_alleles:
            indels.append({
                'chrom': chrom,
                'pos': pos,
                'ref': ref,
                'alt': alt,
                'freq': frequencies  # Minor allele frequency as the second value
            })
    indels_df = pd.DataFrame(indels)

    # For multi-allelic indels, randomly keep one ALT per position
    indels_df = indels_df.groupby(['chrom', 'pos'], group_keys=False).apply(
        lambda g: g.sample(n=1, random_state=None) if len(g) > 1 else g
    ).reset_index(drop=True)

     # keep only SNVs in the result
    # indels_df = snps_df[~((snps_df['ref'].str.len() == 1) &
    #                   (snps_df['alt'].str.len() == 1) &
    #                   (snps_df['ref'].isin(['A', 'T', 'C', 'G'])) &
    #                   (snps_df['alt'].isin(['A', 'T', 'C', 'G'])))]  
    allelic_indels = []
    for freq in indels_df['freq']:
        if freq >= 0.9:  # Consider >= 0.9 as homozygous
            allelic_indels.append('homo')
        else:  # Heterozygous - randomly assign to allele 0 or 1
            allelic_indels.append(np.random.choice([0, 1]))
    indels_df['allelic'] = allelic_indels
    # print(f"Number of indels: {len(indels_df)}")
    snps_df = snps_df[(snps_df['ref'].str.len() == 1) & 
                      (snps_df['alt'].str.len() == 1) & 
                      (snps_df['ref'].isin(['A', 'T', 'C', 'G'])) & 
                      (snps_df['alt'].isin(['A', 'T', 'C', 'G']))]
    snps_df = snps_df.drop_duplicates(subset=['chrom', 'pos'], keep='first')
    red_df_filtered = pd.read_csv(INPUT_RED_site,delimiter="\t")
    # Filter rna editing sites that are also snps
    red_df_filtered = red_df_filtered[~red_df_filtered['Position'].isin(snps_df['pos'])]
    red_df_filtered = red_df_filtered[~red_df_filtered['Position'].isin(indels_df['pos'])]
    # red_df_filtered = red_df_filtered[['Accession','Region','Position','Ref','Ed','Strand','type','Func.wgEncodeGencodeBasicV45','Gene.wgEncodeGencodeBasicV45',tissue]]
    # Cope with different input from REDIportal and DARNED
    preferred_columns = ['Accession', 'Region', 'Position', 'Ref', 'Ed', 'Strand', 
                    'type', 'Func.wgEncodeGencodeBasicV45', 'Gene.wgEncodeGencodeBasicV45', tissue]
    # Essential columns that must be extracted if they exist
    essential_columns = ['Region', 'Position', 'Ref', 'Ed', 'Strand', tissue]
    # Get columns that actually exist in the DataFrame
    existing_preferred = [col for col in preferred_columns if col in red_df_filtered.columns]
    existing_essential = [col for col in essential_columns if col in red_df_filtered.columns]
    # Use preferred columns if enough exist, otherwise use essential columns
    if len(existing_preferred) >= 9:  # Adjust threshold as needed
        red_df_filtered = red_df_filtered[existing_preferred]
    else:
        red_df_filtered = red_df_filtered[existing_essential]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue]>= min_edit]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue]<= max_edit]
    red_df_filtered.to_csv("%s" % (outdirectory + "/" + "RNA_editing_sites_levels.txt"), index=None, sep='\t')
    # select SNPs based on its frequencies
    # snps_df['keep'] = np.random.rand(len(snps_df)) > snps_df['freq']
    # snps_df['keep'] = np.random.rand(len(snps_df)) >=0
    snps_df['keep'] = snps_df['freq'] >= 0
    snps_df = snps_df[snps_df['keep']]
    # update 20250111 use all SNPs
    # snps_df = snps_df.sample(frac=0.5, random_state=2024)  # Use random_state for reproducibility
    #
    snps_df['chrom'] = snps_df['chrom'].astype(str)
    snps_df.columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep']
    homozygous_snp_size = len(snps_df)//2
    # allelic = np.concatenate([
    # 	['homo']*(homozygous_snp_size),  # 50% of them as homozygous
    # 	np.random.choice([0, 1],len(snps_df) - homozygous_snp_size)  
    # 	])
    # np.random.shuffle(allelic)
    allelic = []
    for freq in snps_df['frequency']:
        if freq >= 0.9:  # Consider >= 0.9 as homozygous
            allelic.append('homo')
        else:  # Heterozygous
            allelic.append(np.random.choice([0, 1]))
    snps_df['allelic']=allelic

    # Biological constraint: one allele cannot carry both a SNP and an indel at the
    # same site. For each indel, check SNPs within its ref span [pos, pos + len(ref) - 1].
    # - Homozygous indel: both alleles carry the indel, so any overlapping SNP is impossible
    #   on either allele and must be removed entirely.
    # - Heterozygous indel: the SNP is forced onto the opposite allele.
    snps_to_remove = set()
    for _, indel_row in indels_df.iterrows():
        indel_chrom = indel_row['chrom']
        indel_pos   = int(indel_row['pos'])
        indel_end   = indel_pos + len(str(indel_row['ref'])) - 1
        overlap_mask = (
            (snps_df['Region'] == indel_chrom) &
            (snps_df['Position'] >= indel_pos) &
            (snps_df['Position'] <= indel_end)
        )
        if indel_row['allelic'] == 'homo':
            # Both alleles carry the indel — no allele available for any overlapping SNP.
            snps_to_remove.update(snps_df[overlap_mask].index)
        else:
            # One allele carries the indel — no overlapping SNP can exist on that allele.
            # Homozygous SNPs are also impossible (they would require the indel allele to
            # carry the SNP too), so remove them. Heterozygous SNPs are forced to the
            # opposite allele.
            indel_allele = int(indel_row['allelic'])
            snps_to_remove.update(snps_df[overlap_mask & (snps_df['allelic'] == 'homo')].index)
            het_mask = overlap_mask & (snps_df['allelic'] != 'homo')
            snps_df.loc[het_mask, 'allelic'] = 1 - indel_allele
    if snps_to_remove:
        snps_df = snps_df.drop(index=snps_to_remove)

    snps_df['editing_level'] = 1
    snps_df_positive = snps_df.copy()
    snps_df_positive['Strand'] = "+"
    snps_df_negative = snps_df.copy()
    snps_df_negative['Strand'] = "-"
    # snps_df_negative['Ref'] = snps_df_negative['Ref'].apply(get_complement)
    # snps_df_negative['Ed'] = snps_df_negative['Ed'].apply(get_complement)
    snps_df = pd.concat([snps_df_positive,snps_df_negative])
    snps_df['category'] = 'snp'
    ## Do not include SNPs in simulation (used for black-list)
    if include_SNPs == False:
        snps_df = pd.DataFrame()
    # half_size = len(snps_df)//2
    # allelic_ratios = np.concatenate([
    #     np.ones(half_size),  # Half of them as 1
    #     np.random.normal(0.5, 0.15, len(snps_df) - half_size)  # Half with values from normal distribution
    #     ])
    # np.random.shuffle(allelic_ratios)
    # snps_df['editing_level'] = allelic_ratios
    #
    snps_df.to_csv("%s" % (outdirectory + "/" + "SNPs.txt"), index=None, sep='\t')
    indels_df.to_csv("%s" % (outdirectory + "/" + "indels.txt"), index=None, sep='\t')


# Function to mutate the sequence
def mutate_sequence_snp(sequence, snp_data):
    sequence = list(sequence)  # Convert sequence to list for mutability
    for snp in snp_data:
        chrom, pos, ref, alt, freq, keep = snp
        if keep and sequence[pos - 1] == ref:  # Apply mutation only if 'keep' is True and ref matches
            sequence[pos - 1] = alt  # Change the base at the position to the alternate base
    return ''.join(sequence)

def imbed_SNP_in_reference_genome(referenceGenome_file, outdirectory, SNP_list):
    # Read SNP file
    snp_data = []
    with open(SNP_list, 'r') as snp_file:  # Adjust filename as necessary
        for line in snp_file:
            if not line.startswith('chrom'):
                chrom, pos, ref, alt, freq, keep = line.strip().split()
                snp_data.append((chrom, int(pos), ref, alt, float(freq), keep == 'True'))

    # Dictionary to store mutated sequences for each chromosome
    mutated_sequences = {}

    # Read reference genome and apply mutations
    for record in SeqIO.parse(referenceGenome_file, 'fasta'):  # Adjust filename as necessary
        chrom = record.id  # Assuming chromosome names match
        sequence = str(record.seq)
        snp_for_chrom = [snp for snp in snp_data if 'chr' + snp[0] == chrom]
        if snp_for_chrom:
            mutated_seq = mutate_sequence_snp(sequence, snp_for_chrom)
            mutated_sequences[chrom] = mutated_seq
        else:
            mutated_sequences[chrom] = sequence  # No mutations, keep original
    mutated_records = []
    for chrom, seq in mutated_sequences.items():
        # Create a SeqRecord for each sequence
        record = SeqRecord(Seq(seq), id=chrom, description="contain_snps")
        mutated_records.append(record)
    # Write mutated sequences to a new FASTA file
    SeqIO.write(mutated_records, outdirectory + "/"+"reference_genome_contain_SNPs.fa", 'fasta')
    
# Function to check if a transcript range covers at least one RNA editing site

def get_complement(nucleotide):
    complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
    return complement.get(nucleotide, nucleotide)

def prepare_editing(outdirectory,read_bedfile_prename,RNA_editing_list,isoform_structure,SNPs):
    reads_df = pd.read_csv(outdirectory + "/" + read_bedfile_prename + ".read.bed", sep='\t', header=None, names=['transcript', 'start', 'end', 'read_name', 'length', 'strand'])
    isoform_df = pd.read_csv(isoform_structure, sep='\t')
    rna_editing_df = pd.read_csv(RNA_editing_list, sep='\t')
    rna_editing_df.rename(columns={rna_editing_df.columns[-1]: 'editing_level'}, inplace=True)

    # include SNPs into the RNA editing df
    snps_df = pd.read_csv(SNPs,sep='\t')
    # snps_df['chrom'] = 'chr' + snps_df['chrom'].astype(str)
    # snps_df.columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep']
    # snps_df_positive = snps_df.copy()
    # snps_df_positive['Strand'] = "+"
    
    # snps_df_negative = snps_df.copy()
    # snps_df_negative['Strand'] = "-"
    
    # snps_df_negative['Ref'] = snps_df_negative['Ref'].apply(get_complement)
    # snps_df_negative['Ed'] = snps_df_negative['Ed'].apply(get_complement)
    # snps_df = pd.concat([snps_df_positive,snps_df_negative])
    # snps_df['category'] = 'snp'
    # half_size = len(snps_df)//2
    # allelic_ratios = np.concatenate([
    #     np.ones(half_size),  # Half of them as 1
    #     np.random.normal(0.5, 0.15, len(snps_df) - half_size)  # Half with values from normal distribution
    #     ])
    # np.random.shuffle(allelic_ratios)
    # snps_df['editing_level'] = allelic_ratios
    rna_editing_df['category'] = "RNA_editing"
    rna_editing_df['allelic'] = "homo"
    rna_editing_df = pd.concat([snps_df, rna_editing_df], ignore_index=True, sort=False)
    #
    output_df = []
    all_overlapping_edits = []
    #filter rna_editing_df
    transcripts_covering_sites = []
    # Iterate over each row in isoform_df to check if it covers any RNA editing site
    for _, isoform in isoform_df.iterrows():
        chromosome = isoform['seqname']  # Assuming `seqname` contains chromosome info
        start = isoform['start']
        end = isoform['end']
        
        # Filter rna_editing_df to check if any position is covered by the current transcript
        covered_sites = rna_editing_df[
            (rna_editing_df['Region'] == chromosome) &
            (rna_editing_df['Position'] >= start) &
            (rna_editing_df['Position'] <= end)
        ]
        if not covered_sites.empty:
            for idx, site in covered_sites.iterrows():
                transcripts_covering_sites.append({
                    'Position': site['Position'],
                    'Region': site['Region'],
                    'transcript': isoform['transcript']
                })

    transcripts_df = pd.DataFrame(transcripts_covering_sites)
    # Concatenate all the covered sites to form the final filtered dataframe
    rna_editing_df = rna_editing_df[rna_editing_df['Position'].isin(transcripts_df['Position'])]
    #filter reads_df
    reads_df['normalized_transcript'] = reads_df['transcript'].str.replace('_with_intron', '', regex=False)
    reads_df = reads_df[reads_df['normalized_transcript'].isin(transcripts_df['transcript'])]
    #
    
    for _, read in tqdm(reads_df.iterrows(), total=len(reads_df), desc="Preparing RNA editing"):
        #read = reads_df[reads_df['read_name'] == 'ACACAGGCCCAACCAAGGTACCTAGT:chr1_147172744_147517875:ENST00000441068.6#0001'].reset_index(drop=True).iloc[0]
        transcript_name = read['transcript']
        read_start = read['start']
        read_end = read['end'] - 1
        if read_end < read_start:
            continue
        read_name = read['read_name']
        
        if "with_intron" in transcript_name:
            transcript_name = transcript_name.replace('_with_intron', '')
            transcript_exons = isoform_df[(isoform_df['transcript'] == transcript_name)]
            transcript_exons = transcript_exons.sort_values(by='start')
        else:
            transcript_exons = isoform_df[(isoform_df['transcript'] == transcript_name) & (isoform_df['feature'] == 'exon')]
            transcript_exons = transcript_exons.sort_values(by='start')
            
        strand = transcript_exons['strand'].iloc[0]
        if strand == "-":
            transcript_exons = transcript_exons[::-1]
            
        cumulative_length = 0
        read_genomic_positions = []

        for _, exon in transcript_exons.iterrows():
            exon_start = exon['start']
            exon_end = exon['end']
            exon_length = exon_end - exon_start + 1
            
            # Check if the read starts within this exon
            if read_start >= cumulative_length and read_start <= cumulative_length + exon_length:
                # The read starts within this exon
                if strand == "+":
                    genomic_start = exon_start + (read_start - cumulative_length)
                else:
                    genomic_start = exon_end - (read_start - cumulative_length)
                
                # Check if the read also ends within this exon
                if read_end <= cumulative_length + exon_length:
                    # Read ends within the same exon
                    if strand == "+":
                        genomic_end = exon_start + (read_end - cumulative_length)
                    else:
                        genomic_end = exon_end - (read_end - cumulative_length)
                    read_genomic_positions.append((genomic_start, genomic_end))
                    break
                else: 
                    if strand == "+":
                        read_genomic_positions.append((genomic_start, exon_end))
                    else:
                        read_genomic_positions.append((genomic_start, exon_start))
            elif read_start < cumulative_length and read_end > cumulative_length and read_end <= cumulative_length + exon_length:
                # The read starts in a previous exon and continues in this exon
                if strand == "+":
                    genomic_end = exon_start + (read_end - cumulative_length)
                    read_genomic_positions.append((exon_start, genomic_end))
                else:
                    genomic_end = exon_end - (read_end - cumulative_length)
                    read_genomic_positions.append((exon_end, genomic_end))
                break
            elif read_start < cumulative_length and read_end > cumulative_length + exon_length:
                if strand == "+":
                    read_genomic_positions.append((exon_start, exon_end))
                else:
                    read_genomic_positions.append((exon_end, exon_start))
            # Update cumulative length for the next exon
            cumulative_length += exon_length
        if strand == "-":
            # read_genomic_positions[0] = (read_genomic_positions[0][1],read_genomic_positions[0][0])
            read_genomic_positions = [(end, start) for start, end in read_genomic_positions]
        # Choose the allele of a read
        read_allelic = random.choices([0, 1], k = 1)
        if read_allelic == [0]:
            rna_editing_df_allelic = rna_editing_df.copy()
            rna_editing_df_allelic.loc[rna_editing_df_allelic['allelic'] == "1", 'editing_level'] = 0
        elif read_allelic == [1]:
            rna_editing_df_allelic = rna_editing_df.copy()
            rna_editing_df_allelic.loc[rna_editing_df_allelic['allelic'] == "0", 'editing_level'] = 0
        # Identify RNA editing positions overlapping the read's mapped genomic positions
        for genomic_start, genomic_end in read_genomic_positions:
            overlapping_edits = rna_editing_df_allelic[(rna_editing_df_allelic['Region'] == transcript_exons.iloc[0]['seqname']) &
                                            (rna_editing_df_allelic['Position'] >= genomic_start) &
                                            (rna_editing_df_allelic['Position'] <= genomic_end)]
            overlapping_edits = overlapping_edits[
                overlapping_edits.apply(
                    lambda row: any(
                        (row['Position'] >= start) and (row['Position'] <= end)
                        for start, end in zip(transcript_exons['start'], transcript_exons['end'])),axis=1)]
            if not overlapping_edits.empty:
                # Calculate relative positions within the read for the overlapping RNA editing
                # overlapping_edits = overlapping_edits[overlapping_edits['Strand'] == strand]
                all_overlapping_edits.append(overlapping_edits)
                for _, edit in overlapping_edits.iterrows():
                    covered_length = 0
                    for _, exon in transcript_exons.iterrows():
                        exon_start = exon['start']
                        exon_end = exon['end']
                        exon_length = exon_end - exon_start + 1
                        
                        if  exon_start <= edit['Position'] <= exon_end:
                            # the edit_position is 0-based
                            if strand == "+":
                                edit_position_in_read = edit['Position'] - exon_start + covered_length + 1 - read_start
                            else: 
                                edit_position_in_read = exon_end - edit['Position'] + covered_length + 1 - read_start
                            break
                        covered_length += exon_length
                        
                    if strand == edit['Strand']:
                        if strand == "+":
                            output_df.append({
                                'read_name': read_name,
                                'edit_position': edit_position_in_read,
                                'ref': edit['Ref'],
                                'alt': edit['Ed'],
                                'editing_level': edit['editing_level'],
                                'strand': strand,
                                'Region' : edit['Region'],
                                'Position_genome' : edit['Position'],
                                'category': edit['category'],
                                'include':'T',
                                'allelic':edit['allelic']
                            })
                        else:
                            output_df.append({
                                'read_name': read_name,
                                'edit_position': edit_position_in_read,
                                'ref': str(Seq(edit['Ref']).complement()),
                                'alt': str(Seq(edit['Ed']).complement()),
                                'editing_level': edit['editing_level'],
                                'strand': strand,
                                'Region' : edit['Region'],
                                'Position_genome' : edit['Position'],
                                'category': edit['category'],
                                'include':'T',
                                'allelic':edit['allelic']
                            })
                    elif edit['category'] == "RNA_editing":
                        if strand == "+":
                            output_df.append({
                                'read_name': read_name,
                                'edit_position': edit_position_in_read,
                                'ref': edit['Ref'],
                                'alt': edit['Ed'],
                                'editing_level': edit['editing_level'],
                                'strand': strand,
                                'Region' : edit['Region'],
                                'Position_genome' : edit['Position'],
                                'category': edit['category'],
                                'include':'F',
                                'allelic':edit['allelic']
                            })
                        else:
                            output_df.append({
                                'read_name': read_name,
                                'edit_position': edit_position_in_read,
                                'ref': str(Seq(edit['Ref']).complement()),
                                'alt': str(Seq(edit['Ed']).complement()),
                                'editing_level': edit['editing_level'],
                                'strand': strand,
                                'Region' : edit['Region'],
                                'Position_genome' : edit['Position'],
                                'category': edit['category'],
                                'include':'F',
                                'allelic':edit['allelic']
                                })
    output_df = pd.DataFrame(output_df)
    output_df.to_csv(outdirectory + "/" + 'read_editing_positions.csv', index=False)
    
    all_overlapping_edits_df = pd.concat(all_overlapping_edits, ignore_index=True)
    all_overlapping_edits_df['unedited_reads'] = 0
    all_overlapping_edits_df['edited_reads'] = 0
    # Remove duplicate rows from the concatenated DataFrame
    all_overlapping_edits_df = all_overlapping_edits_df.drop_duplicates()
    all_overlapping_edits_df = all_overlapping_edits_df[all_overlapping_edits_df['editing_level'] != 0]

    # Save the overlapping edits to a CSV file
    all_overlapping_edits_df.to_csv(outdirectory + "/" +'Synthetic_RNA_editing_events.csv', index=False)

