def prepare_editing_parallel_new(outdirectory,read_bedfile_prename,RNA_editing_list,SNPs, n_jobs = 32,mode = "10x"):
    if mode == '10x':
        reads_df = pd.read_csv(outdirectory + "/" + read_bedfile_prename + ".read.bed", sep='\t', header=None, names=['chr', 'start', 'end', 'read_name', 'length', 'strand'])
        reads_df['allele'] = [random.choice([0, 1]) for _ in range(len(reads_df))]
        allele_file = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
        reads_df[['read_name', 'allele']].to_csv(allele_file, sep='\t', index=False)
        print(f"Saved read allele assignments to {allele_file}")
        
        rna_editing_df = pd.read_csv(RNA_editing_list, sep='\t')
        rna_editing_df.rename(columns={rna_editing_df.columns[-1]: 'editing_level'}, inplace=True)

        try:
            snps_df = pd.read_csv(SNPs, sep='\t')
        except pd.errors.EmptyDataError:
            columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep', 'allelic',
            'editing_level', 'Strand', 'category']
            snps_df = pd.DataFrame(columns=columns)
        
        rna_editing_df['category'] = "RNA_editing"
        rna_editing_df['allelic'] = "homo"
        rna_editing_df = pd.concat([snps_df, rna_editing_df], ignore_index=True, sort=False)

        read_chunks = [reads_df.iloc[i:i + 10000] for i in range(0, len(reads_df), 10000)]

        # Process in parallel
        results = Parallel(n_jobs=n_jobs, backend='loky', batch_size='auto')(
            delayed(process_read_chunk_parallel_new)(chunk, rna_editing_df) 
            for chunk in tqdm(read_chunks, desc="Processing RNA editing chunks")
        )

        #
        output_df = []
        all_overlapping_edits = []
        # Combine results
        for result in results:
            output_df.extend(result[0])
            all_overlapping_edits.extend(result[1])
        
        output_df = pd.DataFrame(output_df)
        output_df.to_csv(outdirectory + "/" + 'read_editing_positions.csv', index=False)
        
        # all_overlapping_edits_df = pd.DataFrame(all_overlapping_edits)
        all_overlapping_edits_df = pd.concat(all_overlapping_edits, ignore_index=True)
        all_overlapping_edits_df['unedited_reads'] = 0
        all_overlapping_edits_df['edited_reads'] = 0
        # Remove duplicate rows from the concatenated DataFrame
        all_overlapping_edits_df = all_overlapping_edits_df.drop_duplicates()
        all_overlapping_edits_df = all_overlapping_edits_df[all_overlapping_edits_df['editing_level'] != 0]

        # Save the overlapping edits to a CSV file
        all_overlapping_edits_df.to_csv(outdirectory + "/" +'Synthetic_RNA_editing_events.csv', index=False)
        
def process_read_chunk_parallel_new(chunk, rna_editing_df):
    """
    Process a chunk of reads to find RNA editing sites/SNPs they cover and sample editing.
    This function is designed to be called in parallel.
    
    Parameters:
    -----------
    chunk : pandas.DataFrame
        Chunk of reads DataFrame with columns: ['chr', 'start', 'end', 'read_name', 'length', 'strand']
    rna_editing_df : pandas.DataFrame  
        DataFrame containing RNA editing sites/SNPs
    Returns:
    --------
    tuple: (output_list, overlapping_edits_list)
    """
    output_df = []
    all_overlapping_edits = []
    for _, read in tqdm(chunk.iterrows(), total=len(chunk), desc="Processing reads"):
        read_strand = read['strand']
        chr_name = read['chr']
        read_start = read['start'] + 1
        ## bed file is 0-based
        read_end = read['end'] 
        read_name = read['read_name']
        
        # Skip invalid reads
        if read_end <= read_start:
            continue
            
        # Sample allelic state for this read (0 or 1 for heterozygous SNPs)
        read_allelic = read['allele'] 
        
        # Create allelic-specific copy of editing sites
        rna_editing_df_allelic = rna_editing_df.copy()
        
        # For heterozygous allelic sites, set editing_level to 0 for non-matching allele
        if read_allelic == 0:
            rna_editing_df_allelic.loc[rna_editing_df_allelic['allelic'] == "1", 'editing_level'] = 0
        elif read_allelic == 1:
            rna_editing_df_allelic.loc[rna_editing_df_allelic['allelic'] == "0", 'editing_level'] = 0
            
        # Find overlapping editing sites/SNPs
        overlapping_edits = rna_editing_df_allelic[
            (rna_editing_df_allelic['Region'] == chr_name) &
            (rna_editing_df_allelic['Position'] >= read_start) &
            (rna_editing_df_allelic['Position'] <= read_end)
        ]
        
        if not overlapping_edits.empty:
            all_overlapping_edits.append(overlapping_edits)
            for _, edit in overlapping_edits.iterrows():
                if edit['category'] == 'RNA_editing':
                    # Determine ref and alt based on strand
                    if read_strand == edit['Strand']:
                        include_edit = "T"  # Default to include
                        if read_strand == "+":
                            ref_base = edit['Ref']
                            alt_base = edit['Ed']
                        else:
                            complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
                            ref_base = complement.get(edit['Ref'], edit['Ref'])
                            alt_base = complement.get(edit['Ed'], edit['Ed'])   
                    else:
                        # If strands don't match, use complement
                        complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
                        ref_base = complement.get(edit['Ref'], edit['Ref'])
                        alt_base = complement.get(edit['Ed'], edit['Ed'])
                        include_edit = "F"
                elif edit['category'] == 'snp':
                    if read_strand == edit['Strand']:
                        include_edit = "T"  # Default to include
                        if read_strand == "+":
                            ref_base = edit['Ref']
                            alt_base = edit['Ed']
                        else:
                            complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
                            ref_base = complement.get(edit['Ref'], edit['Ref'])
                            alt_base = complement.get(edit['Ed'], edit['Ed'])   
                    else:
                        if read_strand == "+":
                            ref_base = edit['Ref']
                            alt_base = edit['Ed']
                        else:
                            complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
                            ref_base = complement.get(edit['Ref'], edit['Ref'])
                            alt_base = complement.get(edit['Ed'], edit['Ed'])   
                        include_edit = "F"
                if read_strand == "+":
                        # Forward strand: position from start of read
                        edit_position_in_read = edit['Position'] - read_start + 1
                else:
                    # Reverse strand: position from end of read (reverse complement)
                    edit_position_in_read = read_end - edit['Position'] + 1
                original_editing_level = edit['editing_level']
                if include_edit == 'T' and original_editing_level > 0:
                    # Sample whether this site is edited based on original editing level
                    is_edited = random.random() < original_editing_level
                    binary_editing_level = 1 if is_edited else 0
                else:
                    # Not included or no editing possible
                    binary_editing_level = 0
                # Add to output
                output_df.append({
                    'read_name': read_name,
                    'edit_position': edit_position_in_read,
                    'ref': ref_base,
                    'alt': alt_base,
                    'editing_level': binary_editing_level,
                    'strand': read_strand,
                    'Region': edit['Region'],
                    'Position_genome': edit['Position'],
                    'category': edit['category'],
                    'include': include_edit,
                    'allelic': edit['allelic']
                })
    
    
    return output_df, all_overlapping_edits

def mutate_fastq_sequences(read_editing_pos, input_read2, synthetic_editing,outdirectory,ErrorInclude=False,output_per_cell_editing_matrix=True):
    """
    Mutates sequences in a FASTQ file based on mutation data provided in a CSV file.

    Parameters:
        mutation_file (str): Path to the CSV file containing mutation data.
        input_read2 (str): Path to the input FASTQ file.
        output_read2 (str): Path to the output FASTQ file where mutated sequences will be saved.
    """
    if ErrorInclude == False:
        prefix=""
    else:
        prefix="ErrorIncluded_"
    # Step 1: Read the mutation data from the CSV file into a dictionary
    mutations = {}
    with open(read_editing_pos, 'r') as file:
        next(file) 
        for line in file:
            read_name, edit_position, ref, alt, editing_level, strand, Region, Position_genome, category, include, allelic = line.strip().split(',')
            if read_name not in mutations:
                mutations[read_name] = []
            mutations[read_name].append((int(edit_position), ref, alt, editing_level, strand, Region, Position_genome, category, include, allelic ))  # Store position as integer
    synthetic_editing_df = pd.read_csv(synthetic_editing)

    # Dictionary to hold edited and unedited counts
    edited_counts = {}
    unedited_counts = {}

    # Initialize sets for cell barcodes and editing events
    cell_barcodes = set()
    editing_events = set()

    mutated_records = []
    for record in SeqIO.parse(input_read2, "fastq"):
        read_id = record.id
        sequence = str(record.seq)
        # Step 3: Check for mutations in the read sequence
        if read_id in mutations:
            seq_list = list(sequence)  # Convert sequence to a list for mutability
            for position, ref, alt, editing_level,strand, Region, Position_genome, category, include, allelic in mutations[read_id]:
                if strand == "+":
                    editing_event = f"{Region}-{Position_genome}-{ref}-{alt}"
                elif strand == "-":
                    editing_event = f"{Region}-{Position_genome}-{get_complement(ref)}-{get_complement(alt)}"
                editing_events.add(editing_event)
                cell_barcode = read_id.split(':')[0][:16]
                cell_barcodes.add(cell_barcode)
                # Apply mutation if the reference matches
                if seq_list[position-1] == ref and include == "T": 
                    if random.random() <= float(editing_level):
                        seq_list[position-1] = alt
                        synthetic_editing_df.loc[(synthetic_editing_df['Position'] == int(Position_genome)) & (synthetic_editing_df['Region'] == Region) & (synthetic_editing_df['category'] == category) & (synthetic_editing_df['Strand'] == strand), 'edited_reads'] += 1
                        if cell_barcode not in edited_counts:
                            edited_counts[cell_barcode] = {}
                        edited_counts[cell_barcode][editing_event] = edited_counts[cell_barcode].get(editing_event, 0) + 1
                    else:
                        synthetic_editing_df.loc[(synthetic_editing_df['Position'] == int(Position_genome)) & (synthetic_editing_df['Region'] == Region) & (synthetic_editing_df['category'] == category) & (synthetic_editing_df['Strand'] == strand), 'unedited_reads'] += 1
                        if cell_barcode not in unedited_counts:
                            unedited_counts[cell_barcode] = {}
                        unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
                    # print(f"Reference match at {position} in read {read_id}. Done")
                elif seq_list[position-1] != ref or include == "F": 
                    synthetic_editing_df.loc[(synthetic_editing_df['Position'] == int(Position_genome)) & (synthetic_editing_df['Region'] == Region) & (synthetic_editing_df['category'] == category) & (synthetic_editing_df['Strand'] != strand), 'unedited_reads'] += 1
                    if cell_barcode not in unedited_counts:
                            unedited_counts[cell_barcode] = {}
                    unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
                # else:
                    # print(seq_list[position-1])
                    # print(ref)
                    # print(f"Reference mismatch at {position} in read {read_id}. Skipping mutation.")
            # Convert list back to string
            record.seq = Seq(''.join(seq_list))

        # Add the mutated record to the list
        mutated_records.append(record)
    
    synthetic_editing_df = synthetic_editing_df[~(((synthetic_editing_df['edited_reads'] == 0) & (synthetic_editing_df['unedited_reads'] == 0)))]
    # merge + and - strand for snps
    # df_plus = synthetic_editing_df[synthetic_editing_df['Strand'] == '+']
    # df_result = synthetic_editing_df.groupby(['Region', 'Position', 'category'])[['unedited_reads', 'edited_reads']].sum().reset_index()
    # df_result = pd.merge(df_plus, df_sum, on=['Region', 'Position', 'category'], suffixes=('', '_total'))
    # df_result = df_result.drop(columns=['unedited_reads', 'edited_reads'])
    df_result = synthetic_editing_df.copy()
    df_result['editing_level'] = df_result['edited_reads'] / (df_result['edited_reads'] + df_result['unedited_reads'])
    if ErrorInclude == True :
        df_result.to_csv(outdirectory + "/" + "ErrorIncluded_Synthetic_RNA_editing_events.csv", index=False)
    else:
        df_result.to_csv(synthetic_editing, index=False)
    # Step 4: Overwrite the original FASTQ file with mutated records
    with open(input_read2, 'w') as out_file:
        SeqIO.write(mutated_records, out_file, "fastq")

    print(f"Mutation process completed. Original file {input_read2} has been overwritten.")
    
    ########### Ouput single cell by editing events matrix
    # Step 2: Convert dictionaries into DataFrames (cellbarcode x editing events)
    # Ensure all cell barcodes and editing events are represented in the matrix
    if output_per_cell_editing_matrix == True:
        sorted_cell_barcodes = sorted(cell_barcodes)
        sorted_editing_events = sorted(editing_events)

        # Create empty matrices
        edited_matrix = pd.DataFrame(0, index=sorted_cell_barcodes, columns=sorted_editing_events)
        unedited_matrix = pd.DataFrame(0, index=sorted_cell_barcodes, columns=sorted_editing_events)

        # Fill in the matrices with the counts from the dictionaries
        for cell_barcode, events in edited_counts.items():
            for event, count in events.items():
                edited_matrix.at[cell_barcode, event] = count

        for cell_barcode, events in unedited_counts.items():
            for event, count in events.items():
                unedited_matrix.at[cell_barcode, event] = count
        # Output matrices
        edited_matrix_transposed = edited_matrix.T
        edited_matrix_transposed.to_csv(outdirectory + "/" + prefix + 'edited_events_by_cell_matrix.csv')
        
        unedited_matrix_transposed = unedited_matrix.T
        unedited_matrix_transposed.to_csv(outdirectory + "/" + prefix + 'unedited_events_by_cell_matrix.csv')
    

def process_mutations_parallel(chunk, mutations):
    edited_counts = {}
    unedited_counts = {}
    cell_barcodes = set()
    editing_events = set()
    mutated_records = []
    for record in chunk:
        read_id = record.id
        sequence = str(record.seq)
        if read_id in mutations:
            seq_list = list(sequence)
            for position, ref, alt, editing_level,strand, Region, Position_genome, category, include, allelic in mutations[read_id]:
                if strand == "+":
                    editing_event = f"{Region}-{Position_genome}-{ref}-{alt}-{category}"
                elif strand == "-":
                    editing_event = f"{Region}-{Position_genome}-{get_complement(ref)}-{get_complement(alt)}-{category}"
                editing_events.add(editing_event)
                cell_barcode = read_id.split(':')[0][:16]
                cell_barcodes.add(cell_barcode)
                # Apply mutation if the reference matches
                if seq_list[position-1] == ref and include == "T": 
                    if random.random() <= float(editing_level):
                        seq_list[position-1] = alt
                        if cell_barcode not in edited_counts:
                            edited_counts[cell_barcode] = {}
                        edited_counts[cell_barcode][editing_event] = edited_counts[cell_barcode].get(editing_event, 0) + 1
                    else:
                        if cell_barcode not in unedited_counts:
                            unedited_counts[cell_barcode] = {}
                        unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
                    # print(f"Reference match at {position} in read {read_id}. Done")
                elif seq_list[position-1] != ref and include == "T": 
                    if cell_barcode not in unedited_counts:
                            unedited_counts[cell_barcode] = {}
                    unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
                elif seq_list[position-1] == ref and include != "T": 
                    if category != "snp":
                        if cell_barcode not in unedited_counts:
                                unedited_counts[cell_barcode] = {}
                        unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
                elif seq_list[position-1] != ref and include != "T": 
                    if category == 'RNA_editing':
                        if cell_barcode not in unedited_counts:
                                unedited_counts[cell_barcode] = {}
                        unedited_counts[cell_barcode][editing_event] = unedited_counts[cell_barcode].get(editing_event, 0) + 1
            record.seq = Seq(''.join(seq_list))
        mutated_records.append(record)
    return mutated_records, edited_counts, unedited_counts, cell_barcodes, editing_events

def mutate_fastq_sequences_parallel(read_editing_pos, input_read1, input_read2, output_read1, output_read2, synthetic_editing,outdirectory,ErrorInclude=False,n_jobs=32,output_per_cell_editing_matrix=True):
    """
    Mutates sequences in a FASTQ file based on mutation data provided in a CSV file.

    Parameters:
        mutation_file (str): Path to the CSV file containing mutation data.
        input_read2 (str): Path to the input FASTQ file.
        output_read2 (str): Path to the output FASTQ file where mutated sequences will be saved.
    """
    if ErrorInclude == False:
        prefix=""
    else:
        prefix="ErrorIncluded_"
    # Step 1: Read the mutation data from the CSV file into a dictionary
    mutations = {}
    with open(read_editing_pos, 'r') as file:
        next(file) 
        for line in file:
            read_name, edit_position, ref, alt, editing_level, strand, Region, Position_genome, category, include, allelic = line.strip().split(',')
            if read_name not in mutations:
                mutations[read_name] = []
            mutations[read_name].append((int(edit_position), ref, alt, editing_level, strand, Region, Position_genome, category, include, allelic ))  # Store position as integer
    synthetic_editing_df = pd.read_csv(synthetic_editing)
    # report the rna editing sites that are on the opposite strand in the synthetic data and is not covered at all inthe simulated data
    df = pd.read_csv(read_editing_pos, sep=',')
    rna_editing_df = df[df['category'] == 'RNA_editing'].copy()
    grouped = rna_editing_df.groupby(['Region', 'Position_genome'])
    sites_all_false = []
    
    for (region, position), group in grouped:
        # Check if ALL entries for this site have include='F'
        if (group['include'] == 'F').all():
            # Calculate some statistics for this site
            site_info = {
                'Region': region,
                'Position': position,
            }
            sites_all_false.append(site_info)
    
    unsimulated_sites_df = pd.DataFrame(sites_all_false)
    unsimulated_sites_df.to_csv(outdirectory + "/" + 'unsimulated_editing_sites.csv', index=False)
    # 
    records = list(SeqIO.parse(input_read2, "fastq"))
    chunk_size = len(records) // 100
    chunks = [records[i:i + chunk_size] for i in range(0, len(records), chunk_size)]
    results = Parallel(n_jobs=n_jobs, backend='loky', batch_size=1,verbose=10)(
        delayed(process_mutations_parallel)(chunk, mutations)
        for chunk in tqdm(chunks, desc="Embedding mutations")
    )

    print("Combining results...")

    all_mutated_records = []
    all_edited_counts = {}
    all_unedited_counts = {}
    all_cell_barcodes = set()
    all_editing_events = set()

    for mutated_records, edited_counts, unedited_counts, cell_barcodes, editing_events in results:
        all_mutated_records.extend(mutated_records)
        
        # Combine counts
        for cell_barcode, events in edited_counts.items():
            if cell_barcode not in all_edited_counts:
                all_edited_counts[cell_barcode] = {}
            for event, count in events.items():
                all_edited_counts[cell_barcode][event] = all_edited_counts[cell_barcode].get(event, 0) + count
        
        for cell_barcode, events in unedited_counts.items():
            if cell_barcode not in all_unedited_counts:
                all_unedited_counts[cell_barcode] = {}
            for event, count in events.items():
                all_unedited_counts[cell_barcode][event] = all_unedited_counts[cell_barcode].get(event, 0) + count
        
        all_cell_barcodes.update(cell_barcodes)
        all_editing_events.update(editing_events)

    # Update synthetic_editing_df with combined counts
    for cellbarcode, events in all_edited_counts.items():
        for event, count in events.items():
            components = event.split('-')
            Region, Position_genome, Ref, Ed, category = components
            mask = (
                (synthetic_editing_df['Position'] == int(Position_genome)) & 
                (synthetic_editing_df['Region'] == Region) & 
                (synthetic_editing_df['category'] == category)
            )
            synthetic_editing_df.loc[mask, 'edited_reads'] += count

    for cellbarcode, events in all_unedited_counts.items():
        for event, count in events.items():
            components = event.split('-')
            Region, Position_genome, Ref, Ed, category = components
            mask = (
                (synthetic_editing_df['Position'] == int(Position_genome)) & 
                (synthetic_editing_df['Region'] == Region) & 
                (synthetic_editing_df['category'] == category)
            )
            synthetic_editing_df.loc[mask, 'unedited_reads'] += count

    synthetic_editing_df = synthetic_editing_df[~(((synthetic_editing_df['edited_reads'] == 0) & (synthetic_editing_df['unedited_reads'] == 0)))]
    # merge + and - strand for snps
    # df_plus = synthetic_editing_df[synthetic_editing_df['Strand'] == '+']
    # df_result = synthetic_editing_df.groupby(['Region', 'Position', 'category'])[['unedited_reads', 'edited_reads']].sum().reset_index()
    # df_result = pd.merge(df_plus, df_sum, on=['Region', 'Position', 'category'], suffixes=('', '_total'))
    # df_result = df_result.drop(columns=['unedited_reads', 'edited_reads'])
    df_result = synthetic_editing_df.copy()
    df_result['editing_level'] = df_result['edited_reads'] / (df_result['edited_reads'] + df_result['unedited_reads'])
    if ErrorInclude == True :
        df_result.to_csv(outdirectory + "/" + "ErrorIncluded_Synthetic_RNA_editing_events.csv", index=False)
    else:
        df_result.to_csv(synthetic_editing, index=False)
    # Step 4: Overwrite the original FASTQ file with mutated records
    with open(output_read2, 'w') as out_file:
        SeqIO.write(all_mutated_records, out_file, "fastq")

    print(f"Mutation process completed. Original file {input_read2} has been overwritten.")
    
    records = SeqIO.parse(input_read1, "fastq")
    SeqIO.write(records, output_read1, "fastq")

    ########### Ouput single cell by editing events matrix
    # Step 2: Convert dictionaries into DataFrames (cellbarcode x editing events)
    # Ensure all cell barcodes and editing events are represented in the matrix
    if output_per_cell_editing_matrix == True:
        sorted_cell_barcodes = sorted(all_cell_barcodes)
        sorted_editing_events = sorted(all_editing_events)

        edited_matrix = pd.DataFrame(0, index=sorted_cell_barcodes, columns=sorted_editing_events)
        unedited_matrix = pd.DataFrame(0, index=sorted_cell_barcodes, columns=sorted_editing_events)

        for cell_barcode, events in all_edited_counts.items():
                for event, count in events.items():

                    # first_four_elements = event.split("-")[:4]
                    # # Join the first four elements back with "-"
                    # event = "-".join(first_four_elements)

                    edited_matrix.at[cell_barcode, event] += count

        for cell_barcode, events in all_unedited_counts.items():
                for event, count in events.items():
                    # first_four_elements = event.split("-")[:4]
                    # # Join the first four elements back with "-"
                    # event = "-".join(first_four_elements)
                    
                    unedited_matrix.at[cell_barcode, event] += count

        edited_matrix.T.to_csv(f"{outdirectory}/{prefix}edited_events_by_cell_matrix.csv")
        unedited_matrix.T.to_csv(f"{outdirectory}/{prefix}unedited_events_by_cell_matrix.csv")
        print(f"Per-cell editing caculation has been done")

