def get_mapped_reference_sequence(read, reference):
    """
    Extract only the mapped portions of the reference sequence for a read,
    excluding any intronic/spliced regions.
    """
    if read.is_unmapped:
        return None
    
    chrom = read.reference_name
    ref_pos = read.reference_start
    mapped_seq = ""
    
    # Process each operation in the CIGAR string
    for cigar_op, length in read.cigartuples:
        # Match or mismatch (M) or sequence match (=) or sequence mismatch (X)
        if cigar_op in (0, 7, 8):  
            # Fetch this mapped segment from the reference
            segment = reference.fetch(chrom, ref_pos, ref_pos + length)
            mapped_seq += segment
            ref_pos += length
        # Deletion from the reference (D)
        elif cigar_op == 2:  
            # Include deletion - these are bases in the reference that aren't in the read
            segment = reference.fetch(chrom, ref_pos, ref_pos + length)
            mapped_seq += segment
            ref_pos += length
        # Skipped region from the reference (N) - this is your splice!
        elif cigar_op == 3:  
            # Skip this region (intron)
            ref_pos += length
        # Insertion to the reference (I) or soft clipping (S) or hard clipping (H)
        # or padding (P) - these don't consume reference bases
        else:
            continue
            
    return mapped_seq

def cal_gray_list_p_values(black_list_sites_file, outdirectory, reference_file, editing_info_file, upstream_bp=150, downstream_bp=150, min_coverage=1,max_coverage = 100,max_edit_sites = 15):
    """
    Analyze reads that may have been edited, calculate their original sequences,
    and determine probabilities related to editing.
    
    Parameters:
    -----------
    black_list_sites_file : str
        Path to the file containing RNA editing sites (CSV format)
    bam_file : str
        Path to the BAM file to analyze
    reference_file : str
        Path to the reference genome FASTA file
    editing_info_file : str
        Path to file containing read name, edit position, ref, alt, and editing level
    upstream_bp : int
        Number of base pairs to check upstream
    downstream_bp : int
        Number of base pairs to check downstream
    min_coverage : int
        Minimum number of reads to consider a position as "covered"
    
    Returns:
    --------
    Dictionary with edit positions as keys, and values containing:
    - "chr": chromosome name
    - "coverage_regions": list of tuples with (start, end) positions
    - "reads": list of dictionaries with read analysis information
    - "read_count": number of reads found for this site
    """
    
    
    # Read the editing sites file
    df_sites = pd.read_csv(black_list_sites_file)
    
    # Read the editing info file
    df_editing = pd.read_csv(editing_info_file)
    
    # Create a dictionary for quick lookup of editing information by read name
    editing_info = {}
    for _, row in df_editing.iterrows():
        read_name = row['read_name']
        
        if read_name not in editing_info:
            editing_info[read_name] = []
            
        editing_info[read_name].append({
            'edit_position': row['edit_position'],
            'ref': row['ref'],
            'alt': row['alt'],
            'editing_level': row.get('editing_level', 1.0),  # Default to 1.0 if not provided
            'position_genome': row.get('Position_genome', None),
            'category': row['category'],
            'strand':row['strand'],
            'include':row['include'],
            'chr':row['Region']
        })
    
    # Open the reference genome file
    try:
        reference = pysam.FastaFile(reference_file)
    except Exception as e:
        print(f"ERROR: Could not open reference genome file {reference_file}: {str(e)}")
        return {}
    
    # Create dictionary to store results
    results = {}
    
    # Process each editing site
    for _, row in tqdm(df_sites.iterrows(), total=len(df_sites), desc="Processing edit sites"):
        chrom = row['chr']
        position = int(row['edit_position_whole_genome'])
        aligner = row['aligner']
        if aligner == "STAR":
            bam_file = outdirectory + "/" + "whole_genome_aligned_synthetic_10x_20250103edited_celltypeAligned.sortedByCoord.out.bam"
        elif aligner == "BWA":
            if row['method'] == "RED_ML":
                bam_file = outdirectory + "/" + "whole_genome_aligned_synthetic_10x_20250103edited_celltypeAligned_bwa_red_ml_sorted.bam"
            else:
                bam_file = outdirectory + "/" + "whole_genome_aligned_synthetic_10x_20250103edited_celltypeAligned_bwa_sorted.bam"
        elif aligner == "HISAT2":
            bam_file = outdirectory + "/" + "whole_genome_aligned_synthetic_10x_20250103edited_celltypeAligned_hisat2_sorted.bam"
        # Open the BAM file
        bam = pysam.AlignmentFile(bam_file, "rb")
        # Define the region to check
        start = max(0, position - upstream_bp)
        end = position + downstream_bp
        # Initialize variables for regions and reads
        regions = []
        all_reads = {}
        read_probability = {}  # Dictionary to store read name -> read info
        current_region = None
        ### get the number of reads within a region
        coverage_whole_region = bam.count(chrom, start, end)
        ## Discard the region with too many reads(usually caused by alignment error in the original chr) --> save running time
        if coverage_whole_region >= max_coverage:
            continue
        # Process both upstream and downstream in one loop
        for pos in range(start, end + 1):
            coverage = bam.count_coverage(chrom, pos, pos+1, quality_threshold=0)
            total_coverage = sum(sum(x) for x in coverage)
            
            if total_coverage >= min_coverage:
                if current_region is None:
                    current_region = [pos, pos]
                else:
                    current_region[1] = pos
                
                # Collect read names that cover this position
                for read in bam.fetch(chrom, pos, pos+1):
                    if read.get_overlap(pos, pos+1) > 0:
                        # Only add the read if it's not already in our dictionary
                        if read.query_name not in all_reads:
                            # Get reference coordinates for this read
                            ref_start = read.reference_start
                            ref_end = read.reference_end
                            # Get reference sequence
                            ref_sequence = get_mapped_reference_sequence(read,reference)
                            # Get the read sequence
                            read_sequence = read.query_sequence
                            mapped_strand = "-" if read.is_reverse else "+"
                            if mapped_strand == "-":
                                ref_sequence = get_complementary_sequence(ref_sequence)[::-1]
                                read_sequence = get_complementary_sequence(read_sequence)[::-1]
                            # Store basic read information
                            read_info = {
                                "name": read.query_name,
                                "ref_start": ref_start,
                                "ref_end": ref_end,
                                "ref_sequence": ref_sequence,
                                "read_sequence": read_sequence,
                                "original_sequence": None,  # Will be modified if editing is found
                                "probability_smaller_needle_to_ref": None,
                                "editing_sites": [],
                                "mapped_strand":mapped_strand,
                                "original_region": None
                            }
                            # Look up editing information for this read
                            if read.query_name in editing_info:
                                # Get all editing sites for this read
                                edit_sites = editing_info[read.query_name]
                                edit_sites = [site for site in edit_sites if site['include'] == 'T']
                                if len(edit_sites) ==0 or len(edit_sites) >= max_edit_sites:
                                    continue
                                read_info["editing_sites"] = edit_sites
                                read_strand = next(iter(set(site["strand"] for site in edit_sites)))
                                #####################################################################
                                #####################################################################
                                #####################################################################
                                #####################################################################
                                # Modification 20250409   
                                #####################################################################
                                #####################################################################
                                #####################################################################
                                #####################################################################
                                ## Get the original sequence of the read
                                index_site = edit_sites[0]
                                index_position_whole_genome = index_site['position_genome']
                                index_position_in_read = index_site['edit_position']
                                read_original_chr = index_site['chr']
                                if read_strand == "+":
                                    read_start_whole_genome = index_position_whole_genome - index_position_in_read
                                    read_end_whole_genome = index_position_whole_genome + len(read_sequence) - index_position_in_read 
                                    original_sequence = reference.fetch(read_original_chr, read_start_whole_genome, read_end_whole_genome)
                                    read_info["original_region"] = {
                                            "chr": read_original_chr,
                                            "start": read_start_whole_genome,
                                            "end": read_end_whole_genome,
                                            "strand": read_strand
                                        }
                                elif read_strand == "-":
                                    read_end_whole_genome = index_position_whole_genome + index_position_in_read - 1
                                    read_start_whole_genome = index_position_whole_genome - (len(read_sequence) - index_position_in_read) - 1
                                    original_sequence = reference.fetch(read_original_chr, read_start_whole_genome, read_end_whole_genome)
                                    original_sequence = get_complementary_sequence(original_sequence)[::-1]
                                    read_info["original_region"] = {
                                            "chr": read_original_chr,
                                            "start": read_start_whole_genome,
                                            "end": read_end_whole_genome,
                                            "strand": read_strand
                                        }
                                read_info["original_sequence"] = original_sequence
                                edit_sites = [site for site in edit_sites if site['category'] == 'RNA_editing']
                                ### compre read sequence with its origin
                                needle_syntheitc_read_original = pairwise2.align.globalms(read_sequence, original_sequence, 1, -1, -1, -0.5)
                                needle_syntheitc_read_ref = pairwise2.align.globalms(read_sequence, ref_sequence, 1, -1, -1, -0.5)
                                delta_needle_real = needle_syntheitc_read_original[0][2] - needle_syntheitc_read_ref[0][2]
                                if len(edit_sites) > 0:
                                    # Generate all possible combinations of edits
                                    total_prob = 0.0
                                    
                                    # For all possible binary combinations (edit or don't edit)
                                    for combo in product([0, 1], repeat=len(edit_sites)):
                                        # Apply this combination of edits to a copy of the original sequence
                                        edited_seq = list(original_sequence)
                                        combo_prob = 1.0
                                        
                                        for i, apply_edit in enumerate(combo):
                                            edit_site = edit_sites[i]
                                            read_pos = edit_site['edit_position'] - 1
                                            if 0 <= read_pos < len(edited_seq):
                                                if apply_edit:
                                                    # Apply this edit
                                                    edited_seq[read_pos] = edit_site['alt']
                                                    combo_prob *= edit_site['editing_level']
                                                else:
                                                    # Don't apply this edit
                                                    combo_prob *= (1 - edit_site['editing_level'])
                                        
                                            # Calculate Hamming distance for the edited sequence
                                        edited_seq_str = ''.join(edited_seq)
                                         ###### Needleman-wunsch algorithm
                                         ###### 1: match score, -1: mismatch penalty, -1 gap openning penalty, -0.5 gap extension penalty
                                        needle_wrong = pairwise2.align.globalms(edited_seq_str, ref_sequence, 1, -1, -1, -0.5)
                                        original_sequence = ''.join(original_sequence)
                                        needle_original = pairwise2.align.globalms(edited_seq_str, original_sequence, 1, -1, -1, -0.5)
                                        delta_needle_theoretical = needle_original[0][2] - needle_wrong[0][2]
                                        # print(delta_needle_theoretical)
                                        # print("number of mismatch introduced:", sum(combo))
                                        # print("needle distance to wrong region:", needle_wrong[0][2])
                                        # print("needle distance to original region:", needle_original[0][2])
                                        # Check if this edited sequence has a smaller Hamming distance
                                        if delta_needle_theoretical <= delta_needle_real:
                                            total_prob += combo_prob
                                read_info["probability_smaller_needle_to_ref"] = total_prob                            
                                all_reads[read.query_name] =  read_info
                                read_probability[read.query_name] = read_info["probability_smaller_needle_to_ref"]              
        ### not due to rna editing, there's no rna editing in this region, solely due to alignment error 
        if len(all_reads) == 0:
            continue
        if current_region is not None:
            regions.append((current_region[0], current_region[1]))
        # Convert all_reads dictionary to a list of read info dictionaries
        read_list = all_reads.values()
        original_regions = []
        for read_info in read_list:
            if read_info.get("original_region") is not None:
                region = read_info.get("original_region")
                original_regions.append({
                    "chr": region["chr"],
                    "start": region["start"],
                    "end": region["end"],
                    "strand": region["strand"],
                    "read_name": read_info["name"]
                })
        temp_regions = {}
        for region in original_regions:
            chr_key = region["chr"]
            if chr_key not in temp_regions:
                temp_regions[chr_key] = {
                    "starts": [region["start"]],
                    "ends": [region["end"]],
                    "strand_counts": {region["strand"]: 1}
                }
            else:
                temp_regions[chr_key]["starts"].append(region["start"])
                temp_regions[chr_key]["ends"].append(region["end"])
                if region["strand"] in temp_regions[chr_key]["strand_counts"]:
                    temp_regions[chr_key]["strand_counts"][region["strand"]] += 1
                else:
                    temp_regions[chr_key]["strand_counts"][region["strand"]] = 1
        summarized_regions = {}
        for chr_key, data in temp_regions.items():
            # For starts, filter outliers (consider using percentiles or IQR method)
            starts = sorted(data["starts"])
            ends = sorted(data["ends"])
            
            # Filter using IQR method (1.5 * IQR rule for outliers)
            if len(starts) >= 4:  # Only apply filtering if we have enough data points
                # Calculate quartiles and IQR for starts
                q1_start_idx = len(starts) // 4
                q3_start_idx = 3 * len(starts) // 4
                q1_start = starts[q1_start_idx]
                q3_start = starts[q3_start_idx]
                iqr_start = q3_start - q1_start
                start_lower_bound = q1_start - 1.5 * iqr_start
                start_upper_bound = q3_start + 1.5 * iqr_start
                
                # Calculate quartiles and IQR for ends
                q1_end_idx = len(ends) // 4
                q3_end_idx = 3 * len(ends) // 4
                q1_end = ends[q1_end_idx]
                q3_end = ends[q3_end_idx]
                iqr_end = q3_end - q1_end
                end_lower_bound = q1_end - 1.5 * iqr_end
                end_upper_bound = q3_end + 1.5 * iqr_end
                
                # Filter outliers
                filtered_starts = [s for s in starts if start_lower_bound <= s <= start_upper_bound]
                filtered_ends = [e for e in ends if end_lower_bound <= e <= end_upper_bound]
                
                # Use filtered values if available, otherwise use all values
                min_start = min(filtered_starts) if filtered_starts else min(starts)
                max_end = max(filtered_ends) if filtered_ends else max(ends)
            else:
                # Not enough data points for IQR filtering
                min_start = min(starts)
                max_end = max(ends)
            
            # Store the results
            summarized_regions[chr_key] = {
                "min_start": min_start,
                "max_end": max_end,
                "strand_count": data["strand_counts"],
                "total_reads": len(starts),
                "filtered_reads": len(filtered_starts) if 'filtered_starts' in locals() else len(starts)
            }
        # Summarize the original regions (min start, max end per chromosome)
        # summarized_regions = {}
        # for region in original_regions:
        #     chr_key = region["chr"]
        #     if chr_key not in summarized_regions:
        #         summarized_regions[chr_key] = {
        #             "min_start": region["start"],
        #             "max_end": region["end"],
        #             "strand_count": {"+" if region["strand"] == "+" else "-": 1}
        #         }
        #     else:
        #         summarized_regions[chr_key]["min_start"] = min(summarized_regions[chr_key]["min_start"], region["start"])
        #         summarized_regions[chr_key]["max_end"] = max(summarized_regions[chr_key]["max_end"], region["end"])
        # Store the results with chromosome information and read count
        p_values = list(read_probability.values())
        mean_read_p = float(np.mean(p_values))  # compute mean
        results[position] = {
            'position': pos,
            "chr": chrom,
            "coverage_regions": regions,
            "mean_read_p": mean_read_p,
            "summarized_original_regions": summarized_regions
        }
        # Close the BAM file
        bam.close()
    # rows = []
    # for pos, info in results.items():
    #     median_read = float(np.median(info['reads']))  # compute median
    #     row = {
    #         'position': pos,
    #         'chr': info['chr'],
    #         'coverage_regions': info['coverage_regions'],
    #         'read_count': info['read_count'],
    #         'median_p_value': median_read
    #     }
    #     rows.append(row)
    rows = []
    for pos, info in results.items():
        # Format original regions for better readability
        original_regions_formatted = []
        if 'summarized_original_regions' in info:
            for chr_key, region_data in info['summarized_original_regions'].items():
                # Determine predominant strand
                original_regions_formatted.append({
                    'chr': chr_key,
                    'start': region_data['min_start'],
                    'end': region_data['max_end']
                })
        row = {
            'position': pos,
            'chr': info['chr'],
            'coverage_regions': info['coverage_regions'],
            'mean_read_p': info['mean_read_p'],
            'original_chr':original_regions_formatted[0]['chr'],
            'original_start':original_regions_formatted[0]['start'],
            'original_end':original_regions_formatted[0]['end']
        }
        rows.append(row)
    # Create DataFrame
    gray_list_p_values = pd.DataFrame(rows)
    
    # Close the reference genome file
    reference.close()
    return gray_list_p_values
    # Original code

def scRNA_GenerateBAMCoord(bed_file, UMI_count_mat_file, synthetic_cell_label_file, read_bedfile_prename, INPUT_bamfile, outdirectory, OUTPUT_cells_barcode_file, jitter_size=5, read_len=90, UMI_tag='UB:Z'):
    """Generate Synthetic reads in BED format.

    Parameters
    ----------
    bed_file: `str`
        Features' bed file to generate the synthetic reads (Generated by function `Utility.scRNA_CreateFeatureSets`).
    UMI_count_mat_file: `str`
        The path to synthetic UMI count matrix.
    synthetic_cell_label_file: `str`
        Synthetic cell label file generated by `scRNA_GenerateSyntheticCount`.
    read_bedfile_prename: `str`
        Specify the base name of output bed file.
    INPUT_bamfile: `str`
        Input BAM file for anlaysis.
    outdirectory: `str`
        Specify the output directory for synthetic reads bed file.
    OUTPUT_cells_barcode_file: `str`
        Specify the file name storing the synthetic cell barcodes.
    jitter_size: `int` (default: '5')
        Specify the range of random shift to avoid replicate synthetic reads. Default value is 5 bp.
    read_len: `int` (default: '90')
        Specify the length of synthetic reads. Default value is 90 bp.
    UMI_tag: `str` (default: 'UB:Z')
        If UMI_modeling is set to True, specify the UMI tag of input BAM file, default value 'UB:Z' is the UMI tag for 10x scRNA-seq.
    """
    UMI_count_mat_df = pd.read_csv("%s" % (UMI_count_mat_file), header=None, delimiter="\t")
    # Remove count matrix first column: feature names
    UMI_count_mat = UMI_count_mat_df.iloc[: , 1:].to_numpy()
    UMI_count_mat_cluster = pd.read_csv(synthetic_cell_label_file, header=None, delimiter="\t").to_numpy().flatten()	
    n_cell = np.shape(UMI_count_mat)[1]
    samfile = pysam.AlignmentFile(INPUT_bamfile, "rb")
    with open(bed_file) as open_peak:
        reader = csv.reader(open_peak, delimiter="\t")
        open_peak = np.asarray(list(reader))
    peak_nonzero_id = np.nonzero(UMI_count_mat.sum(axis=1))[0]
    random.seed(2022)
    random_cellbarcode_list = cellbarcode_generator(n_cell, size=16)
    with open(outdirectory + "/" + OUTPUT_cells_barcode_file, 'w') as f:
        for item in random_cellbarcode_list:
            f.write(item + "\n")
    cellbarcode_list_withclusters = np.vstack((random_cellbarcode_list, UMI_count_mat_cluster)).transpose()
    with open(outdirectory + "/" + OUTPUT_cells_barcode_file + ".withSynthCluster", 'w') as f:
        for item in cellbarcode_list_withclusters:
            f.write("\t".join(item) + "\n")
    with open("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), 'w') as fp:
        pass
    print("[scReadSim] Generating synthetic reads in BED file...")
    for relative_peak_ind in tqdm(range(len(peak_nonzero_id))):
        peak_ind = peak_nonzero_id[relative_peak_ind]
        rec = open_peak[peak_ind]
        rec_name = '_'.join(rec)
        UMI_read_dict_pergene = defaultdict(lambda: [])
        reads = samfile.fetch(rec[0], int(rec[1]), int(rec[2]))
        for read in reads:
            if read.has_tag(UMI_tag):
                UMI = read.get_tag(UMI_tag)
                start = read.reference_start
                if read.is_reverse==1:
                    strand = "-" 
                else:
                    strand = "+"
                # strand = read.is_reverse
                UMI_read_dict_pergene[UMI].append(str(start) + ":" + str(strand))
        ## Real data: Obtain the empirical distribution of # reads of UMI in the gene 
        UMI_real_vec = list(UMI_read_dict_pergene.keys())
        ## remove pcr effects
        nread_perUMI = [len(x) for x in UMI_read_dict_pergene.values()] # return a vector with the length of # UMIs in the gene
        # nread_perUMI_prob = nread_perUMI / np.sum(nread_perUMI)
        ## Synthetic data
        # Sample syntheitc UMI's read number and assign real UMI to synthetic UMI (only for sampling reads)
        UMI_count_vec = UMI_count_mat[peak_ind,:] # Synthetic umi count
        nonzer_UMI_zero_id = np.nonzero(UMI_count_vec)[0]
        synthetic_nread_perUMI_percell = [np.random.choice(nread_perUMI, size=UMI_count_vec[i], replace=True) for i in nonzer_UMI_zero_id] # return a vector with the length of non-zero count cells, each entry idnicates the number of reads for each UMI
        nread_synthetic = sum(np.sum(x) for x in synthetic_nread_perUMI_percell) # total number of synthetic reads
        # Assign real UMI to synthetic UMI based on read number per UMI
        # Construct a dic with keys as number of reasd per UMI and values as the corresponding UMI strings
        nread_UMI_dic = defaultdict(lambda: [])
        for i,item in enumerate(nread_perUMI):
            nread_UMI_dic[item].append(UMI_real_vec[i])
        synthetic_nread_perUMI_percell_unlist = [xs for x in synthetic_nread_perUMI_percell for xs in list(x)]
        synthetic_realUMI_assign_array = np.array(synthetic_nread_perUMI_percell_unlist).astype(str)
        synthetic_nread_perUMI_percell_unlist_array = np.array(synthetic_nread_perUMI_percell_unlist)
        for i in set(synthetic_nread_perUMI_percell_unlist):
            tmp_ind = np.where(synthetic_nread_perUMI_percell_unlist_array == i)[0]
            synthetic_realUMI_assign_array[tmp_ind] = np.random.choice(nread_UMI_dic[i], size=len(tmp_ind), replace=True)
        synthetic_realUMI_assign_vec = list(synthetic_realUMI_assign_array) # a vectir sane length to synthetic_nread_perUMI_percell_unlist, synthetic UMI's number 
        # synthetic_realUMI_assign_vec = [np.random.choice(nread_UMI_dic[nread], size=1, replace=True) for nread in synthetic_nread_perUMI_percell_unlist]
        # Sample reads for each synthetic UMI
        synthetic_read_list = [np.random.choice(UMI_read_dict_pergene[synthetic_realUMI_assign_vec[id]], size=synthetic_nread_perUMI_percell_unlist[id], replace=True) for id in range(len(synthetic_realUMI_assign_vec))]
        synthetic_read_unlist = [xs for x in synthetic_read_list for xs in list(x)]
        synthetic_read_start_list = [int(xs.split(':', 1)[0]) - 1  for xs in synthetic_read_unlist]  # -1 accounts for the BAM coordinates is +1 compared with getfasta bedtools
        synthetic_read_strand_list = [str(xs.split(':', 1)[1]) for xs in synthetic_read_unlist]
        # Creat synthetic UMI string
        UMI_synthetic_uniq = cellbarcode_generator(np.sum(UMI_count_vec), size=10)
        UMI_synthetic_list = np.repeat(np.array(UMI_synthetic_uniq), synthetic_nread_perUMI_percell_unlist)
        # Create syntheitc CB string
        CB_synthetic_repeat = [np.sum(x) for x in synthetic_nread_perUMI_percell] # same length to nozero cells
        CB_synthetic_list = np.repeat(np.array(random_cellbarcode_list)[nonzer_UMI_zero_id], CB_synthetic_repeat)
        # Create syntheitc read name string
        read_name_remaining_list = ["CellNo" + str(nonzer_UMI_zero_id[ind] + 1) + ":" + str(rec_name) + "#" + str(count).zfill(4) for ind in range(len(CB_synthetic_repeat)) for count in range(CB_synthetic_repeat[ind])]
        read_name_list = [CB_synthetic_list[id] + UMI_synthetic_list[id] + ":" + read_name_remaining_list[id] for id in range(nread_synthetic)]
        # Create output table
        jitter_value_vec = np.random.randint(-jitter_size,jitter_size,size=nread_synthetic)  # nrow(reads_cur) should equal to nfrag_cur
        reads_cur = pd.DataFrame({
            'chr': rec[0],
            'r1_start_shifted': synthetic_read_start_list  + jitter_value_vec,
            'r1_end_shifted': synthetic_read_start_list + jitter_value_vec + read_len,
            'read_name': read_name_list,
            'read_length': read_len,
            'strand': synthetic_read_strand_list
            })
        reads_cur.to_csv("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), header=None, index=None, sep='\t', mode='a')
    print("\n[scReadSim] Created:")
    print("[scReadSim] Read bed file: %s/%s.read.bed" % (outdirectory, read_bedfile_prename))


##############################################################################
# Splice-aware read generation (new functions, original above is unchanged)
##############################################################################

def _get_read_splice_blocks(read):
    """Extract relative exon block positions from a pysam read's CIGAR.

    Returns list of (rel_start, rel_end) tuples relative to read.reference_start
    if the read spans a splice junction (CIGAR 'N' operation), else returns None.
    """
    if read.cigartuples is None:
        return None
    if not any(op == 3 for op, _ in read.cigartuples):
        return None
    ref_start = read.reference_start
    blocks = read.get_blocks()  # list of (abs_start, abs_end) aligned segments
    if len(blocks) <= 1:
        return None
    return [(s - ref_start, e - ref_start) for s, e in blocks]


def _encode_splice_blocks(rel_blocks):
    """Encode relative splice blocks as 'relStart1-relEnd1,relStart2-relEnd2,...'"""
    return ",".join("%d-%d" % (s, e) for s, e in rel_blocks)


def _decode_splice_blocks(block_str, read_len):
    """Decode block string back to list of (rel_start, rel_end) tuples.
    Returns [(0, read_len)] (single unspliced block) when block_str is empty.
    """
    if not block_str:
        return [(0, read_len)]
    blocks = []
    for seg in block_str.split(","):
        s, e = seg.split("-")
        blocks.append((int(s), int(e)))
    return blocks


def _make_bed12_row(chrom, abs_start, read_name, score, strand, rel_blocks):
    """Build a 12-column BED row from splice-block structure.

    abs_start : int  - 0-based genomic start (chromStart)
    rel_blocks : list of (rel_start, rel_end) relative to abs_start
    score      : int  - value for BED column 5 (kept for compat; typically read_len)
    """
    chrom_end = abs_start + rel_blocks[-1][1]
    block_sizes = ",".join(str(e - s) for s, e in rel_blocks)
    block_starts = ",".join(str(s) for s, _ in rel_blocks)
    return [chrom, abs_start, chrom_end, read_name, score, strand,
            abs_start, chrom_end, 0, len(rel_blocks), block_sizes, block_starts]


def scRNA_GenerateBAMCoord_spliced(bed_file, UMI_count_mat_file, synthetic_cell_label_file,
                                    read_bedfile_prename, INPUT_bamfile, outdirectory,
                                    OUTPUT_cells_barcode_file, jitter_size=5, read_len=90,
                                    UMI_tag='UB:Z'):
    """Generate synthetic reads in BED format, modelling RNA splicing.

    Splice-aware version of scRNA_GenerateBAMCoord. Records the CIGAR-derived
    exon-block structure from each real BAM read and writes two output files:

    * ``<read_bedfile_prename>.read.bed``  – standard BED6, identical in semantics
      to the original function; used by downstream functions such as
      assign_read_alleles and prepare_editing_parallel_spliced.
    * ``<read_bedfile_prename>.read.bed12`` – BED12 with per-read splice-block
      information; consumed by scRNA_BED2FASTQ_spliced / combine_bed12 so that
      bedtools getfasta -split extracts only exonic sequence (no intronic bases).

    Parameters
    ----------
    bed_file: `str`
        Features' bed file (produced by Utility.scRNA_CreateFeatureSets).
    UMI_count_mat_file: `str`
        Path to synthetic UMI count matrix.
    synthetic_cell_label_file: `str`
        Synthetic cell label file from scRNA_GenerateSyntheticCount.
    read_bedfile_prename: `str`
        Base name for output BED files.
    INPUT_bamfile: `str`
        Input BAM file.
    outdirectory: `str`
        Output directory.
    OUTPUT_cells_barcode_file: `str`
        File name for synthetic cell barcodes.
    jitter_size: `int` (default: 5)
        Random positional jitter range (bp) to avoid duplicate reads.
    read_len: `int` (default: 90)
        Synthetic read length (bp); used as the fallback block length for
        unspliced reads.
    UMI_tag: `str` (default: 'UB:Z')
        BAM tag carrying the UMI string.
    """
    UMI_count_mat_df = pd.read_csv("%s" % (UMI_count_mat_file), header=None, delimiter="\t")
    UMI_count_mat = UMI_count_mat_df.iloc[:, 1:].to_numpy()
    UMI_count_mat_cluster = pd.read_csv(synthetic_cell_label_file, header=None, delimiter="\t").to_numpy().flatten()
    n_cell = np.shape(UMI_count_mat)[1]
    samfile = pysam.AlignmentFile(INPUT_bamfile, "rb")
    with open(bed_file) as open_peak:
        reader = csv.reader(open_peak, delimiter="\t")
        open_peak = np.asarray(list(reader))
    peak_nonzero_id = np.nonzero(UMI_count_mat.sum(axis=1))[0]
    random.seed(2022)
    random_cellbarcode_list = cellbarcode_generator(n_cell, size=16)
    with open(outdirectory + "/" + OUTPUT_cells_barcode_file, 'w') as f:
        for item in random_cellbarcode_list:
            f.write(item + "\n")
    cellbarcode_list_withclusters = np.vstack((random_cellbarcode_list, UMI_count_mat_cluster)).transpose()
    with open(outdirectory + "/" + OUTPUT_cells_barcode_file + ".withSynthCluster", 'w') as f:
        for item in cellbarcode_list_withclusters:
            f.write("\t".join(item) + "\n")
    # Initialise output files
    open("%s/%s.read.bed" % (outdirectory, read_bedfile_prename), 'w').close()
    open("%s/%s.read.bed12" % (outdirectory, read_bedfile_prename), 'w').close()
    print("[scEditSim] Generating splice-aware synthetic reads in BED/BED12 files...")
    for relative_peak_ind in tqdm(range(len(peak_nonzero_id))):
        peak_ind = peak_nonzero_id[relative_peak_ind]
        rec = open_peak[peak_ind]
        rec_name = '_'.join(rec)
        UMI_read_dict_pergene = defaultdict(lambda: [])
        start_to_blocks = defaultdict(list)  # (start BAM 0-based, strand) → list of block_str
        reads = samfile.fetch(rec[0], int(rec[1]), int(rec[2]))
        for read in reads:
            if read.has_tag(UMI_tag):
                UMI = read.get_tag(UMI_tag)
                start = read.reference_start
                strand = "-" if read.is_reverse else "+"
                rel_blocks = _get_read_splice_blocks(read)
                block_str = _encode_splice_blocks(rel_blocks) if rel_blocks is not None else ""
                # Index splice pattern by (start, strand) to ensure strand consistency
                start_to_blocks[(start, strand)].append(block_str)
                # Store: "start:strand" only — splice pattern resolved via start_to_blocks
                UMI_read_dict_pergene[UMI].append("%d:%s" % (start, strand))
        UMI_real_vec = list(UMI_read_dict_pergene.keys())
        nread_perUMI = [len(x) for x in UMI_read_dict_pergene.values()]
        if not nread_perUMI:
            continue  # no real reads in this feature; skip
        UMI_count_vec = UMI_count_mat[peak_ind, :]
        nonzer_UMI_zero_id = np.nonzero(UMI_count_vec)[0]
        synthetic_nread_perUMI_percell = [
            np.random.choice(nread_perUMI, size=UMI_count_vec[i], replace=True)
            for i in nonzer_UMI_zero_id
        ]
        nread_synthetic = sum(np.sum(x) for x in synthetic_nread_perUMI_percell)
        nread_UMI_dic = defaultdict(lambda: [])
        for i, item in enumerate(nread_perUMI):
            nread_UMI_dic[item].append(UMI_real_vec[i])
        synthetic_nread_perUMI_percell_unlist = [xs for x in synthetic_nread_perUMI_percell for xs in list(x)]
        synthetic_realUMI_assign_array = np.array(synthetic_nread_perUMI_percell_unlist).astype(str)
        synthetic_nread_perUMI_percell_unlist_array = np.array(synthetic_nread_perUMI_percell_unlist)
        for i in set(synthetic_nread_perUMI_percell_unlist):
            tmp_ind = np.where(synthetic_nread_perUMI_percell_unlist_array == i)[0]
            synthetic_realUMI_assign_array[tmp_ind] = np.random.choice(nread_UMI_dic[i], size=len(tmp_ind), replace=True)
        synthetic_realUMI_assign_vec = list(synthetic_realUMI_assign_array)
        synthetic_read_list = [
            np.random.choice(UMI_read_dict_pergene[synthetic_realUMI_assign_vec[id]],
                             size=synthetic_nread_perUMI_percell_unlist[id], replace=True)
            for id in range(len(synthetic_realUMI_assign_vec))
        ]
        synthetic_read_unlist = [xs for x in synthetic_read_list for xs in list(x)]
        # Parse start, strand from "start:strand"
        parsed = [xs.split(':', 1) for xs in synthetic_read_unlist]
        synthetic_read_raw_start_list = [int(p[0]) for p in parsed]  # BAM 0-based, for start_to_blocks lookup
        synthetic_read_strand_list = [p[1] for p in parsed]
        UMI_synthetic_uniq = cellbarcode_generator(np.sum(UMI_count_vec), size=10)
        UMI_synthetic_list = np.repeat(np.array(UMI_synthetic_uniq), synthetic_nread_perUMI_percell_unlist)
        CB_synthetic_repeat = [np.sum(x) for x in synthetic_nread_perUMI_percell]
        CB_synthetic_list = np.repeat(np.array(random_cellbarcode_list)[nonzer_UMI_zero_id], CB_synthetic_repeat)
        read_name_remaining_list = [
            "CellNo" + str(nonzer_UMI_zero_id[ind] + 1) + ":" + str(rec_name) + "#" + str(count).zfill(4)
            for ind in range(len(CB_synthetic_repeat)) for count in range(CB_synthetic_repeat[ind])
        ]
        read_name_list = [
            CB_synthetic_list[id] + UMI_synthetic_list[id] + ":" + read_name_remaining_list[id]
            for id in range(nread_synthetic)
        ]
        jitter_value_vec = np.random.randint(-jitter_size, jitter_size, size=nread_synthetic)
        bed6_rows = []
        bed12_rows = []
        for i in range(nread_synthetic):
            j = jitter_value_vec[i]
            strand = synthetic_read_strand_list[i]
            # Apply jitter; if no same-strand reads exist at the jittered position, revert to original
            jittered_raw_start = synthetic_read_raw_start_list[i] + j
            candidates = start_to_blocks.get((jittered_raw_start, strand))
            if candidates:
                abs_start = jittered_raw_start  # pysam reference_start is already 0-based, matching BED12
            else:
                candidates = start_to_blocks.get((synthetic_read_raw_start_list[i], strand), [""])
                abs_start = synthetic_read_raw_start_list[i]  # revert to original start
            sampled_block_str = random.choice(candidates)
            rel_blocks = _decode_splice_blocks(sampled_block_str, read_len)
            chrom_end = abs_start + rel_blocks[-1][1]
            score = chrom_end - abs_start  # genomic span, mirrors original read_len usage
            bed6_rows.append([rec[0], abs_start, chrom_end, read_name_list[i], score, strand])
            bed12_rows.append(_make_bed12_row(rec[0], abs_start, read_name_list[i], score, strand, rel_blocks))
        pd.DataFrame(bed6_rows).to_csv(
            "%s/%s.read.bed" % (outdirectory, read_bedfile_prename),
            header=None, index=None, sep='\t', mode='a')
        pd.DataFrame(bed12_rows).to_csv(
            "%s/%s.read.bed12" % (outdirectory, read_bedfile_prename),
            header=None, index=None, sep='\t', mode='a')
    samfile.close()
    print("\n[scEditSim] Created:")
    print("[scEditSim] BED6 file : %s/%s.read.bed" % (outdirectory, read_bedfile_prename))
    print("[scEditSim] BED12 file: %s/%s.read.bed12" % (outdirectory, read_bedfile_prename))


def combine_bed12(outdirectory, gene_read_bedfile_prename, intergene_read_bedfile_prename,
                  BED_filename_combined_pre):
    """Combine gene and intergene BED12 files into one sorted BED12 file.

    Companion to scRNA_GenerateBAMCoord_spliced. Used before scRNA_BED2FASTQ_spliced.

    Parameters
    ----------
    outdirectory: `str`
        Directory containing the individual BED12 files.
    gene_read_bedfile_prename: `str`
        Base name of the gene reads BED12 file.
    intergene_read_bedfile_prename: `str`
        Base name of the intergene reads BED12 file.
    BED_filename_combined_pre: `str`
        Base name for the combined output BED12 file.
    """
    print("[scEditSim] Combining BED12 files from genes and inter-genes.")
    combine_cmd = (
        "cat %s/%s.read.bed12 %s/%s.read.bed12 | sort -k1,1 -k2,2n > %s/%s.read.bed12"
        % (outdirectory, gene_read_bedfile_prename,
           outdirectory, intergene_read_bedfile_prename,
           outdirectory, BED_filename_combined_pre)
    )
    _, error = subprocess.Popen(
        combine_cmd, shell=True, executable="/bin/bash",
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    ).communicate()
    if error:
        print('[ERROR] Failed to combine BED12 files:\n', error.decode())
    print("[scEditSim] Combined BED12: %s/%s.read.bed12" % (outdirectory, BED_filename_combined_pre))


def scRNA_BED2FASTQ_spliced(bedtools_directory, seqtk_directory, referenceGenome_file,
                             outdirectory, BED_filename_combined, synthetic_fastq_prename):
    """Convert splice-aware BED12 synthetic reads to FASTQ.

    Uses ``bedtools getfasta -split`` so that only exon block sequences are
    extracted and concatenated for each read, correctly modelling spliced mRNA.
    Replaces the scRNA_BED2FASTQ call when model_splicing is enabled.

    Parameters
    ----------
    bedtools_directory: `str`
        Path to directory containing bedtools executable.
    seqtk_directory: `str`
        Path to directory containing seqtk executable.
    referenceGenome_file: `str`
        Reference genome FASTA file (must be indexed with samtools faidx).
    outdirectory: `str`
        Output directory.
    BED_filename_combined: `str`
        Base name of the combined BED12 file (from combine_bed12).
    synthetic_fastq_prename: `str`
        Base name for the output FASTQ files.
    """
    print('[scEditSim] Generating splice-aware FASTA from BED12 (bedtools getfasta -split)...')
    fasta_read2_cmd = (
        "%s/bedtools getfasta -s -nameOnly -split -fi %s -bed %s/%s.read.bed12 -fo %s/%s.read2.strand.bed2fa.fa"
        % (bedtools_directory, referenceGenome_file,
           outdirectory, BED_filename_combined,
           outdirectory, synthetic_fastq_prename)
    )
    _, error = subprocess.Popen(
        fasta_read2_cmd, shell=True, executable="/bin/bash",
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    ).communicate()
    if error:
        print(error.decode())
    # Remove trailing (+) / (-) appended by bedtools to FASTA headers
    strip_strand_cmd = (
        "sed '/^>/s/.\\{3\\}$//' %s/%s.read2.strand.bed2fa.fa > %s/%s.read2.bed2fa.fa"
        % (outdirectory, synthetic_fastq_prename, outdirectory, synthetic_fastq_prename)
    )
    _, error = subprocess.Popen(
        strip_strand_cmd, shell=True, executable="/bin/bash",
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    ).communicate()
    if error:
        print('[ERROR] Failed to strip strand from FASTA headers:\n', error.decode())
    # Read 1: first 26 bp of read 2 sequence (10x CB+UMI)
    read1_cmd = (
        "awk 'NR%%2==0 {print substr(p,2,26);} NR%%2 {p=$0;print p;}' "
        "%s/%s.read2.bed2fa.fa > %s/%s.read1.bed2fa.fa"
        % (outdirectory, synthetic_fastq_prename, outdirectory, synthetic_fastq_prename)
    )
    _, error = subprocess.Popen(
        read1_cmd, shell=True, executable="/bin/bash",
        stdout=subprocess.PIPE, stderr=subprocess.PIPE
    ).communicate()
    if error:
        print(error.decode())
    print('[scEditSim] Converting FASTA to FASTQ...')
    for read_num in ('read1', 'read2'):
        fq_cmd = (
            "%s/seqtk seq -F 'F' %s/%s.%s.bed2fa.fa > %s/%s.%s.bed2fa.fq"
            % (seqtk_directory, outdirectory, synthetic_fastq_prename, read_num,
               outdirectory, synthetic_fastq_prename, read_num)
        )
        _, error = subprocess.Popen(
            fq_cmd, shell=True, executable="/bin/bash",
            stdout=subprocess.PIPE, stderr=subprocess.PIPE
        ).communicate()
        if error:
            print('[ERROR] seqtk %s: %s' % (read_num, error.decode()))
    print('[scEditSim] Sorting FASTQ files...')
    for read_num in ('read1', 'read2'):
        sort_cmd = (
            "cat %s/%s.%s.bed2fa.fq | paste - - - - | sort -k1,1 -S 3G | tr '\\t' '\\n' "
            "> %s/%s.%s.bed2fa.sorted.fq"
            % (outdirectory, synthetic_fastq_prename, read_num,
               outdirectory, synthetic_fastq_prename, read_num)
        )
        _, error = subprocess.Popen(
            sort_cmd, shell=True, executable="/bin/bash",
            stdout=subprocess.PIPE, stderr=subprocess.PIPE
        ).communicate()
        if error:
            print('[ERROR] sort %s: %s' % (read_num, error.decode()))
    print("\n[scEditSim] Splice-aware FASTQ files created:")
    print("[scEditSim] Read 1: %s/%s.read1.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename))
    print("[scEditSim] Read 2: %s/%s.read2.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename))


##############################################################################
# Splice-aware RNA editing / SNP assignment
##############################################################################

def _parse_bed12_blocks(chrom_start, block_sizes_str, block_starts_str):
    """Parse BED12 block columns into a list of absolute (start, end) 0-based intervals.

    Parameters
    ----------
    chrom_start : int
        chromStart field (0-based).
    block_sizes_str : str
        Comma-separated block sizes from BED12 column 10.
    block_starts_str : str
        Comma-separated block starts (relative to chromStart) from BED12 column 11.

    Returns
    -------
    list of (int, int)
        Absolute 0-based half-open intervals [(block_abs_start, block_abs_end), ...].
    """
    sizes  = [int(x) for x in str(block_sizes_str).split(',')  if x]
    starts = [int(x) for x in str(block_starts_str).split(',') if x]
    return [(chrom_start + s, chrom_start + s + z) for s, z in zip(starts, sizes)]


def _genomic_pos_to_read_pos(position_1based, abs_blocks, strand):
    """Convert a 1-based genomic position to a 1-based position within a spliced read.

    Returns None if the position falls in an intron (not covered by any exon block).

    For a spliced read the sequence is built by bedtools getfasta -split as:
      concat(block0_seq, block1_seq, ...)   then reverse-complemented if strand=='-'

    Parameters
    ----------
    position_1based : int
        Genomic position (1-based, as stored in the RNA editing / SNP tables).
    abs_blocks : list of (int, int)
        Absolute 0-based half-open exon intervals, ordered by genomic position.
    strand : str
        '+' or '-'.

    Returns
    -------
    int or None
        1-based position within the read sequence, or None if intronic.
    """
    cumulative = 0
    for block_start_0, block_end_0 in abs_blocks:
        # Convert 1-based genomic position to 0-based index
        pos_0 = position_1based - 1
        if block_start_0 <= pos_0 < block_end_0:
            # Position falls in this exon block
            offset_in_block = pos_0 - block_start_0   # 0-based offset within block
            fwd_pos_0 = cumulative + offset_in_block   # 0-based position in concat sequence
            if strand == '+':
                return fwd_pos_0 + 1                   # convert to 1-based
            else:
                total_read_len = sum(e - s for s, e in abs_blocks)
                return total_read_len - fwd_pos_0      # 1-based from 5' end of revcomp
        cumulative += block_end_0 - block_start_0
    return None   # intronic


def process_read_chunk_parallel_spliced(chunk, rna_editing_df):
    """Splice-aware version of process_read_chunk_parallel_new.

    Reads the BED12 chunk (12 columns including block info) and for each read:
      1. Only considers editing sites that fall within an exon block (not intronic).
      2. Calculates the correct within-read position accounting for the exon
         block structure of the spliced sequence.

    Parameters
    ----------
    chunk : pandas.DataFrame
        Chunk of reads from the BED12 file.  Must have columns:
        [chr, start, end, read_name, score, strand,
         thickStart, thickEnd, itemRgb, blockCount, blockSizes, blockStarts]
    rna_editing_df : pandas.DataFrame
        RNA editing / SNP sites table (same format as prepare_editing_parallel_new).

    Returns
    -------
    tuple : (list of dicts, list of DataFrames)
        Same structure as process_read_chunk_parallel_new.
    """
    output_df = []
    all_overlapping_edits = []

    # --- One-time position index over the editing/SNP table (built per chunk) ----
    # The original code copied + boolean-scanned the ENTIRE rna_editing_df once PER
    # READ (tens of millions of reads x ~50k sites -> a quadratic blow-up; this was
    # the long stall between feature_allelic_ratios and Synthetic_RNA_editing_events).
    # Here we sort site positions per Region ONCE, so each read finds its overlapping
    # sites with two binary searches instead of a full-table copy + scan.
    #
    # Result-preserving: the original `candidates` were the rows matching
    # (Region == chr_name) & (chrom_start < Position <= chrom_end), iterated in the
    # ORIGINAL TABLE (RangeIndex) ORDER. We reproduce that exact set AND order
    # (cand_idx is re-sorted ascending back into table order) and apply the identical
    # allele mask to those same rows, leaving every downstream step untouched -- so
    # the per-read candidate set, the masked editing levels, the number/order of
    # random.random() draws, and both output files are byte-for-byte identical to
    # before (verified on 13k reads spanning both alleles, homo + het SNPs, and
    # RNA-editing sites).
    _region_col = rna_editing_df['Region'].to_numpy()
    _pos_col    = rna_editing_df['Position'].to_numpy()
    _region_index = {}
    for _reg in pd.unique(_region_col):
        _ridx  = np.flatnonzero(_region_col == _reg)          # original row positions
        _order = np.argsort(_pos_col[_ridx], kind='stable')   # ordered by Position
        _region_index[_reg] = (_ridx[_order], _pos_col[_ridx][_order])

    # NOTE: the inner per-read tqdm was removed deliberately. Under loky with a
    # non-TTY log it printed one progress line per read (the multi-GB / ~25M-line run
    # log) and added lock overhead; the outer per-chunk tqdm in the caller still
    # reports progress.
    for _, read in chunk.iterrows():
        read_strand   = read[5]
        chr_name      = read[0]
        chrom_start   = int(read[1])   # 0-based
        chrom_end     = int(read[2])   # 0-based exclusive
        read_name     = read[3]
        read_allelic  = read['allele']

        # Parse exon blocks
        abs_blocks = _parse_bed12_blocks(chrom_start, read[10], read[11])

        # Skip degenerate reads
        if chrom_end <= chrom_start:
            continue

        # Overlapping sites: Region == chr_name & chrom_start < Position <= chrom_end.
        # Binary-search equivalent of the original boolean mask: side='right' on both
        # bounds yields Position > chrom_start (strict) and Position <= chrom_end.
        _ri = _region_index.get(chr_name)
        if _ri is None:
            continue
        _sorted_idx, _sorted_pos = _ri
        _lo = np.searchsorted(_sorted_pos, chrom_start, side='right')
        _hi = np.searchsorted(_sorted_pos, chrom_end,   side='right')
        if _lo >= _hi:
            continue
        cand_idx = np.sort(_sorted_idx[_lo:_hi])   # restore original table order

        # Allele-specific editing-level mask, applied to ONLY these few candidate rows
        # (identical effect to masking the whole table then filtering, but ~O(k) not O(M)).
        candidates = rna_editing_df.iloc[cand_idx].copy()
        if read_allelic == 0:
            candidates.loc[candidates['allelic'] == "1", 'editing_level'] = 0
        elif read_allelic == 1:
            candidates.loc[candidates['allelic'] == "0", 'editing_level'] = 0

        if candidates.empty:
            continue

        # Keep only sites that fall in an exon block and compute read position
        exonic_edits = []
        for _, edit in candidates.iterrows():
            read_pos = _genomic_pos_to_read_pos(int(edit['Position']), abs_blocks, read_strand)
            if read_pos is None:
                continue   # intronic — skip
            exonic_edits.append((edit, read_pos))

        if not exonic_edits:
            continue

        overlapping_edits = candidates.loc[[e.name for e, _ in exonic_edits]]
        all_overlapping_edits.append(overlapping_edits)

        for edit, edit_position_in_read in exonic_edits:
            complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'}
            if edit['category'] in ('RNA_editing', 'snp'):
                if read_strand == edit['Strand']:
                    include_edit = "T"
                    if read_strand == "+":
                        ref_base = edit['Ref']
                        alt_base = edit['Ed']
                    else:
                        ref_base = complement.get(edit['Ref'], edit['Ref'])
                        alt_base = complement.get(edit['Ed'],  edit['Ed'])
                else:
                    include_edit = "F"
                    ref_base = complement.get(edit['Ref'], edit['Ref'])
                    alt_base = complement.get(edit['Ed'],  edit['Ed'])

            original_editing_level = edit['editing_level']
            if include_edit == 'T' and original_editing_level > 0:
                is_edited = random.random() < original_editing_level
                binary_editing_level = 1 if is_edited else 0
            else:
                binary_editing_level = 0

            output_df.append({
                'read_name':       read_name,
                'edit_position':   edit_position_in_read,
                'ref':             ref_base,
                'alt':             alt_base,
                'editing_level':   binary_editing_level,
                'strand':          read_strand,
                'Region':          edit['Region'],
                'Position_genome': edit['Position'],
                'category':        edit['category'],
                'include':         include_edit,
                'allelic':         edit['allelic'],
            })

    return output_df, all_overlapping_edits


def prepare_editing_parallel_spliced(outdirectory, read_bedfile_prename, RNA_editing_list,
                                      SNPs, n_jobs=32, mode="10x"):
    """Splice-aware version of prepare_editing_parallel_new.

    Reads the BED12 file (<read_bedfile_prename>.read.bed12) so that:
      - RNA editing / SNP sites in introns are NOT assigned to spliced reads.
      - Within-read positions are correctly computed from the exon block structure.

    Parameters are identical to prepare_editing_parallel_new.
    """
    if mode == '10x':
        # Read BED12 (12 columns)
        bed12_cols = ['chr', 'start', 'end', 'read_name', 'score', 'strand',
                      'thickStart', 'thickEnd', 'itemRgb',
                      'blockCount', 'blockSizes', 'blockStarts']
        reads_df = pd.read_csv(
            outdirectory + "/" + read_bedfile_prename + ".read.bed12",
            sep='\t', header=None, names=bed12_cols
        )

        # Assign alleles (same as original)
        reads_df['allele'] = [random.choice([0, 1]) for _ in range(len(reads_df))]
        allele_file = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
        reads_df[['read_name', 'allele']].to_csv(allele_file, sep='\t', index=False)
        print(f"Saved read allele assignments to {allele_file}")

        rna_editing_df = pd.read_csv(RNA_editing_list, sep='\t')
        rna_editing_df.rename(columns={rna_editing_df.columns[-1]: 'editing_level'}, inplace=True)

        try:
            snps_df = pd.read_csv(SNPs, sep='\t')
        except pd.errors.EmptyDataError:
            columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep', 'allelic',
                       'editing_level', 'Strand', 'category']
            snps_df = pd.DataFrame(columns=columns)

        rna_editing_df['category'] = "RNA_editing"
        rna_editing_df['allelic']  = "homo"
        rna_editing_df = pd.concat([snps_df, rna_editing_df], ignore_index=True, sort=False)

        read_chunks = [reads_df.iloc[i:i + 10000] for i in range(0, len(reads_df), 10000)]

        results = Parallel(n_jobs=n_jobs, backend='loky', batch_size='auto')(
            delayed(process_read_chunk_parallel_spliced)(chunk, rna_editing_df)
            for chunk in tqdm(read_chunks, desc="Processing RNA editing chunks (splice-aware)")
        )

        output_df = []
        all_overlapping_edits = []
        for result in results:
            output_df.extend(result[0])
            all_overlapping_edits.extend(result[1])

        output_df = pd.DataFrame(output_df)
        output_df.to_csv(outdirectory + "/" + 'read_editing_positions.csv', index=False)

        all_overlapping_edits_df = pd.concat(all_overlapping_edits, ignore_index=True) \
            if all_overlapping_edits else pd.DataFrame()
        if not all_overlapping_edits_df.empty:
            all_overlapping_edits_df['unedited_reads'] = 0
            all_overlapping_edits_df['edited_reads']   = 0
            all_overlapping_edits_df = all_overlapping_edits_df.drop_duplicates()
            all_overlapping_edits_df = all_overlapping_edits_df[
                all_overlapping_edits_df['editing_level'] != 0
            ]
        all_overlapping_edits_df.to_csv(
            outdirectory + "/" + 'Synthetic_RNA_editing_events.csv', index=False
        )


