def replace_fastq_quality_with_sequence(fastq_file, error_rate_file):
    """Replace each base's quality with a realistic, POSITION-specific Phred score.

    A Phred quality is, by definition, Q = -10*log10(P[this base call is wrong]).  The best
    position-specific estimate of that probability is the overall per-position error rate
    measured by fgbio ErrorRateByReadPosition -- the 'error_rate' column (mismatches / bases
    at that read position).  We therefore assign, to EVERY base at read position p,

        Q(p) = -10 * log10( error_rate[p] )

    independent of the base letter.  This is deliberately NOT nucleotide-specific: a base's
    quality reflects the instrument's per-cycle confidence, not the base's identity, so the
    introduced SNPs / RNA-edits / somatic SNVs do NOT change a base's quality (as in real
    sequencing, where quality is uncorrelated with variant status).  Read length is
    preserved; only the quality line of each FASTQ record is rewritten.
    """
    # Per-position overall error rate -> Phred ASCII char (fgbio 'position' is 1-based).
    df = pd.read_csv(error_rate_file, sep='\t')
    qual_lookup = {}
    for _, row in df.iterrows():
        pos = int(row['position']) - 1                 # 0-based index into the read
        rate = max(float(row['error_rate']), 1e-6)     # floor avoids log10(0)
        phred = int(round(-10 * np.log10(rate)))
        qual_lookup[pos] = chr(min(max(phred + 33, 33), 126))
    # Fallback for any position past the measured table (e.g. indel-extension bases):
    # reuse the last measured position's score.
    default_qual = qual_lookup[max(qual_lookup)] if qual_lookup else chr(33 + 30)

    with open(fastq_file, 'r') as f:
        lines = f.readlines()
    with open(fastq_file, 'w') as f:
        for i, line in enumerate(lines):
            if (i + 1) % 4 == 0:  # quality line: rebuild from per-position scores
                seqlen = len(lines[i - 2].strip())
                f.write(''.join(qual_lookup.get(p, default_qual) for p in range(seqlen)) + '\n')
            else:
                f.write(line)

    print(f"Quality scores updated (position-specific): {fastq_file}")


def scRNA_ErrorBase(fgbio_jarfile, INPUT_bamfile, referenceGenome_file, outdirectory, synthetic_fastq_prename):
    """Introduce random substitution errors into synthetic reads according to real data error rates.

    Parameters
    ----------
    fgbio_jarfile: `str`
        Path to software fgbio jar script.
    INPUT_bamfile: `str`
        Input BAM file for anlaysis.
    referenceGenome_file: 'str'
        Reference genome FASTA file that the synthteic reads should align.
    outdirectory: `str`
        Specify the output directory of the synthteic FASTQ file with random errors.
    synthetic_fastq_prename: `str`
        Base name of the synthetic FASTQ files output by function `scATAC_BED2FASTQ`.
    """
    print('[scReadSim] Substitution error calculating...')
    combine_read1_cmd = "java -jar %s ErrorRateByReadPosition -i %s -r %s -o %s/Real --collapse false" % (fgbio_jarfile, INPUT_bamfile, referenceGenome_file, outdirectory)
    output, error = subprocess.Popen(combine_read1_cmd, shell=True, executable="/bin/bash", stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
    if error:
        print('[Messages] Running fgbio on real bam file:\n', error.decode())
    # Generate Errors into fastq files
    real_error_rate_file = outdirectory + "/" + "Real.error_rate_by_read_position.txt"
    SubstiError(real_error_rate_file, outdirectory, synthetic_fastq_prename)
    # Combine FASTQs
    print('[scReadSim] Sorting FASTQ files...')
    sort_fastq_read1_cmd = "cat %s/%s.read1.bed2fa.fq | paste - - - - | sort -k1,1 -S 3G | tr '\t' '\n' > %s/%s.ErrorIncluded.read1.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename, outdirectory, synthetic_fastq_prename)
    output, error = subprocess.Popen(sort_fastq_read1_cmd, shell=True, executable="/bin/bash", stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
    if error:
            print('[ERROR] Fail to sort read1 synthetic fastq file:', error.decode())
    sort_fastq_read2_cmd = "cat %s/%s.ErrorIncluded.read2.bed2fa.fq | paste - - - - | sort -k1,1 -S 3G | tr '\t' '\n' > %s/%s.ErrorIncluded.read2.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename, outdirectory, synthetic_fastq_prename)
    output, error = subprocess.Popen(sort_fastq_read2_cmd, shell=True, executable="/bin/bash", stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()
    if error:
            print('[ERROR] Fail to sort read2 synthetic fastq file:', error.decode())
    print("\n[scReadSim] Created:")
    print("[scReadSim] Read 1 FASTQ file with substitution error: %s/%s.ErrorIncluded.read1.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename))
    print("[scReadSim] Read 2 FASTQ file with substitution error: %s/%s.ErrorIncluded.read2.bed2fa.sorted.fq" % (outdirectory, synthetic_fastq_prename))
    print("[scReadSim] Done.")

def SubstiError(real_error_rate_file, outdirectory, synthetic_fastq_prename):
    """Generate random errors for single-end sequencing reads according to input real data error rates. 

    Parameters
    ----------
    real_error_rate_file: `str`
        Path to software fgbio jar script.
    outdirectory: `str`
        Specify the output directory of the synthteic FASTQ file with random errors.
    synthetic_fastq_prename: `str`
        Specify the base name of the synthetic erroneous reads' FASTQ files.
    """
    # Read in real error rates
    real_error_rate_dir = real_error_rate_file
    real_error_rate = pd.read_csv(real_error_rate_dir, header=0, delimiter="\t")
    # Read in perfect reads
    read2_fq = outdirectory  + "/" + synthetic_fastq_prename + ".read2.bed2fa.fq"
    read2_df = pd.read_csv(read2_fq, header=None).to_numpy()
    # Real data quality score
    # Error rate to Qscore
    ErroneousRead(real_error_rate, read2_df, outdirectory + "/" + synthetic_fastq_prename + ".ErrorIncluded.read2.bed2fa.fq") 

def ErroneousRead(real_error_rate_read, read_df, output_fq_file):
    """Generate random errors according to input real data error rates. 

    """
    n_read = int(np.shape(read_df)[0]/4)
    ## Prepare Error rate
    real_error_rate_read_A = real_error_rate_read[['a_to_c_error_rate', 'a_to_g_error_rate', 'a_to_t_error_rate']].to_numpy() 
    real_error_rate_read_A_prop = real_error_rate_read_A/real_error_rate_read_A.sum(axis=1,keepdims=1)
    real_error_rate_read_A_prop[np.isnan(real_error_rate_read_A_prop).any(axis=1),:] = 1/3
    real_error_rate_read_C = real_error_rate_read[['c_to_a_error_rate', 'c_to_g_error_rate', 'c_to_t_error_rate']].to_numpy() 
    real_error_rate_read_C_prop = real_error_rate_read_C/real_error_rate_read_C.sum(axis=1,keepdims=1)
    real_error_rate_read_C_prop[np.isnan(real_error_rate_read_C_prop).any(axis=1),:] = 1/3
    real_error_rate_read_G = real_error_rate_read[['g_to_a_error_rate', 'g_to_c_error_rate', 'g_to_t_error_rate']].to_numpy() 
    real_error_rate_read_G_prop = real_error_rate_read_G/real_error_rate_read_G.sum(axis=1,keepdims=1)
    real_error_rate_read_G_prop[np.isnan(real_error_rate_read_G_prop).any(axis=1),:] = 1/3
    real_error_rate_read_T = real_error_rate_read[['t_to_a_error_rate', 't_to_c_error_rate', 't_to_g_error_rate']].to_numpy() 
    real_error_rate_read_T_prop = real_error_rate_read_T/real_error_rate_read_T.sum(axis=1,keepdims=1)
    real_error_rate_read_T_prop[np.isnan(real_error_rate_read_T_prop).any(axis=1),:] = 1/3
    # Base decision matrix
    real_error_rate_read_prop_dict = {'A': real_error_rate_read_A_prop, 'C': real_error_rate_read_C_prop, 'G': real_error_rate_read_G_prop, 'T': real_error_rate_read_T_prop}
    # Error decision vector
    real_error_rate_read_perbase = real_error_rate_read['error_rate'].to_numpy()
    ## Decide whether error occurs for each read
    read_length = real_error_rate_read.shape[0]
    error_read_perbase_indicator = np.zeros((n_read, read_length), dtype=int)
    random.seed(1)
    for base_id in range(read_length):
        error_read_perbase_indicator[:,base_id] = np.random.binomial(n=1, p=real_error_rate_read_perbase[base_id], size=n_read)
    erroneous_read_id = np.where(np.sum(error_read_perbase_indicator, axis=1) > 0)[0]
    ## For erroneous reads, generate erroneous base based on the probability matrix
    base_call_ref = {'A': ['C', 'G', 'T'], 'C': ['A', 'G', 'T'], 'G': ['A', 'C', 'T'], 'T': ['A', 'C', 'G']}
    random.seed(2021)
    read_df_witherror = read_df
    for read_id_tqdm in tqdm(range(len(erroneous_read_id))):
        read_id = erroneous_read_id[read_id_tqdm]
        read_cur = read_df[(read_id*4) : (read_id*4 + 4)]
        bases = list(read_cur[1][0].upper())
        Qscores = list(read_cur[3][0])
        for errorneous_base_id in np.where(error_read_perbase_indicator[read_id,:] > 0)[0]:
            if errorneous_base_id < len(bases):
                base_cur = bases[errorneous_base_id]
                if base_cur in real_error_rate_read_prop_dict:
                    prop = real_error_rate_read_prop_dict[base_cur][errorneous_base_id]
                    # Decide error base
                    err_base_call = ErrorBase(base_cur, prop, base_call_ref)
                    bases[errorneous_base_id] = err_base_call
                    # Decide Q score
                    # Use 9 (Phred score 24) for erroneous base
                    # Qscores[errorneous_base_id] = '9'
                    # modified by weijian 20250831
                    position_error_rate = real_error_rate_read_perbase[errorneous_base_id]
                    if position_error_rate > 0:
                        qscore = int(-10 * np.log10(position_error_rate))
                        qscore = max(2, min(60, qscore))  # Clamp between 2 and 60
                    else:
                        qscore = 60  # Very high quality if no errors expected
                    Qscores[errorneous_base_id] = chr(qscore + 33)  # Convert to ASCII
        read_df_witherror[read_id*4+1] = ''.join(bases)
        read_df_witherror[read_id*4+3] = ''.join(Qscores)
    ## Write out
    np.savetxt(output_fq_file, read_df_witherror, fmt='%s')


## Error rate
def ErrorBase(base, prop, base_call_ref):
    """Sample random errors. 

    """
    err_base_call_id = np.random.choice(a=[0, 1, 2], size=1, p=prop)[0]      
    err_base_call = base_call_ref[base][err_base_call_id]
    return err_base_call

def process_indels_in_reads(outdirectory, read_bedfile_prename, reference_file, n_jobs=32):
    """
    Process indels in synthetic reads, modify FASTQ files and update read editing positions.
    Maintains constant read length by trimming or padding as needed.
    Handles strand-specific indel representation correctly.
    
    Parameters:
    -----------
    outdirectory : str
        Output directory
    read_bedfile_prename : str
        Base name of the read bed file
    indels_file : str
        Path to indels file (from prepare_SNP_RED_list)
    reference_file : str
        Path to reference genome FASTA
    n_jobs : int
        Number of parallel jobs
    """
    
    # Read files
    reads_df = pd.read_csv(f"{outdirectory}/{read_bedfile_prename}.read.bed", 
                          sep='\t', header=None, 
                          names=['chr', 'start', 'end', 'read_name', 'length', 'strand'])
    indels_file = outdirectory + "/" + "indels.txt"
    read_allelic = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
    try:
        indels_df = pd.read_csv(indels_file, sep='\t')
        read_allelic_df = pd.read_csv(read_allelic, sep='\t')
    except pd.errors.EmptyDataError:
        print("No indels found, skipping indel processing")
        return
    
    if indels_df.empty:
        print("No indels to process")
        return
    read_allelic_dict = dict(zip(read_allelic_df['read_name'], read_allelic_df['allele']))
    # Open reference genome
    reference = pysam.FastaFile(reference_file)
    
    # Find overlapping reads for each indel
    indel_read_mapping = {}
    indel_coverage = {} 

    for idx, indel in tqdm(indels_df.iterrows(), total=len(indels_df), desc="Finding overlapping reads"):
        chrom = indel['chrom']
        pos = int(indel['pos'])
        ref = indel['ref']
        alt = indel['alt']
        freq = indel['freq']
        allelic = indel['allelic']
        
        # Find reads that overlap this position
        overlapping_reads = reads_df[
            (reads_df['chr'] == chrom) &
            (reads_df['start'] <= pos) &
            (reads_df['end'] >= pos)
        ]
        
        # Create unique indel identifier and count overlapping reads
        indel_id = f"{chrom}:{pos}:{ref}:{alt}"
        indel_coverage[indel_id] = len(overlapping_reads)

        for _, read in overlapping_reads.iterrows():
            read_name = read['read_name']
            read_start = read['start']
            read_end = read['end']
            read_strand = read['strand']
            
            # Calculate position within read based on strand
            # For + strand: position from start
            # For - strand: position from end (in the sequenced read orientation)
            if read_strand == '+':
                pos_in_read = pos - read_start
                # For insertions, check if the entire indel fits in the read
                indel_end_pos = pos + len(ref) - 1
                if indel_end_pos > read_end:
                    continue  # Indel extends beyond read
            else:
                # For reverse strand, the read is sequenced from right to left
                # So position in read is counted from the right end
                pos_in_read = read_end - pos - len(ref) + 1
                # For deletions on reverse strand at the beginning of the read,
                # the deletion would not be captured in the sequenced read
                indel_start_in_read = read_end - pos - len(ref) + 1
                if indel_start_in_read < 0:
                    # Deletion starts before the read begins (in sequenced orientation)
                    continue  # Skip this indel for this read
            
            # Skip if position is out of bounds
            if pos_in_read < 0 or pos_in_read >= (read_end - read_start):
                continue
            
            if read_name not in indel_read_mapping:
                indel_read_mapping[read_name] = []
            
            indel_read_mapping[read_name].append({
                'chrom': chrom,
                'genome_pos': pos,
                'pos_in_read': pos_in_read,
                'ref': ref,
                'alt': alt,
                'freq': freq,
                'allelic': allelic,
                'strand': read_strand,
                'read_strand': read_strand,
                'indel_type': 'insertion' if len(alt) > len(ref) else 'deletion',
                'read_start': read_start,
                'read_end': read_end,
                'indel_id': f"{chrom}:{pos}:{ref}:{alt}"
            })
    
    # Read FASTQ files
    fastq_file = f"{outdirectory}/{read_bedfile_prename}.read2.bed2fa.fq"
    
    # Process FASTQ and create modified sequences
    modified_reads = {}
    
    for record in tqdm(SeqIO.parse(fastq_file, "fastq"), desc="Processing FASTQ"):
        read_name = record.id
        
        if read_name not in indel_read_mapping:
            continue
        
        # Assign allele for this read
        read_allelic = read_allelic_dict.get(read_name, 0)
        
        original_sequence = str(record.seq)
        original_length = len(original_sequence)
        original_quality = record.letter_annotations["phred_quality"]
        
        sequence = original_sequence
        quality = original_quality.copy()
        
        # Sort indels by position (process from right to left to maintain positions)
        indels_for_read = sorted(indel_read_mapping[read_name], 
                                key=lambda x: x['pos_in_read'], 
                                reverse=True)
        
        applied_indels = []
        
        for indel in indels_for_read:
            # Check if this indel should be applied based on allelic state
            if indel['allelic'] == 'homo':
                apply_indel = True
            elif indel['allelic'] == str(read_allelic):
                apply_indel = True
            else:
                apply_indel = False
            
            if not apply_indel:
                continue
            pos = indel['pos_in_read']
            # Ensure position is within bounds
            if pos < 0 or pos >= len(sequence):
                continue
            chrom = indel['chrom']
            ref_len = len(indel['ref'])
            alt_len = len(indel['alt'])
            read_strand = indel['read_strand']
            
            if indel['indel_type'] == 'insertion':
                # Insertion: add bases at position
                insert_seq = indel['alt'][ref_len:]  # Get inserted bases
                insert_len = len(insert_seq)
                
                # For reverse strand, we need to reverse complement the insertion
                if read_strand == '-':
                    insert_seq = str(Seq(insert_seq).reverse_complement())
                
                # Insert the bases
                sequence = sequence[:pos] + insert_seq + sequence[pos:]
                
                # Adjust quality scores
                insert_qual = [37] * insert_len  # Default quality for inserted bases
                quality = quality[:pos] + insert_qual + quality[pos:]
                
                # Trim from the appropriate end to maintain original length
                    # Trim from the end (3' end)
                sequence = sequence[:original_length]
                quality = quality[:original_length]
                applied_indels.append({
                    'chrom':chrom,
                    'pos': pos,
                    'type': indel['indel_type'],
                    'shift': insert_len,
                    'genome_pos': indel['genome_pos'],
                    'ref': indel['ref'],
                    'alt': indel['alt']
                })
                
            else:  # deletion
                # Deletion: remove bases
                del_len = ref_len - alt_len
                
                # Get the genomic coordinates for extension
                read_start = indel['read_start']
                read_end = indel['read_end']
                chrom = indel['chrom']
                
                # Remove deleted bases
                if pos + del_len <= len(sequence):
                    sequence = sequence[:pos] + sequence[pos + del_len:]
                    quality = quality[:pos] + quality[pos + del_len:]
                else:
                    # Deletion extends beyond read end
                    sequence = sequence[:pos]
                    quality = quality[:pos]
                
                # Extend from reference to maintain read length
                extension_needed = original_length - len(sequence)
                
                if extension_needed > 0:
                    try:
                        if read_strand == '+':
                            # Extend from the right (3' end / downstream in genome)
                            ext_start = read_end
                            ext_end = read_end + extension_needed
                            extension = reference.fetch(chrom, ext_start, ext_end)
                            
                            # Add extension at the end
                            sequence = sequence + extension[:extension_needed]
                            
                        else:
                            # For reverse strand, extend from the left (5' end of read, 5' in genome)
                            ext_end = read_start
                            ext_start = max(0, read_start - extension_needed)
                            extension = reference.fetch(chrom, ext_start, ext_end)
                            # Reverse complement for minus strand
                            extension = str(Seq(extension).reverse_complement())
                            
                            # Add extension at the beginning
                            sequence = sequence + extension[:extension_needed]
                        
                        # Add quality scores for extension (use default quality)
                        ext_qual = [37] * extension_needed
                        if read_strand == '+':
                            quality = quality + ext_qual
                        else:
                            quality = ext_qual + quality
                        
                    except Exception as e:
                        print(f"Warning: Could not extend sequence for read {read_name}: {e}")
                        # If extension fails, pad with Ns
                        pad_seq = 'N' * extension_needed
                        pad_qual = [2] * extension_needed
                        if read_strand == '+':
                            sequence = sequence + pad_seq
                            quality = quality + pad_qual
                        else:
                            sequence = pad_seq + sequence
                            quality = pad_qual + quality
                
                applied_indels.append({
                    'chrom':chrom,
                    'pos': pos,
                    'type': indel['indel_type'],
                    'shift': -del_len,
                    'genome_pos': indel['genome_pos'],
                    'ref': indel['ref'],
                    'alt': indel['alt']
                })
            modified_reads[read_name] = {
                'sequence': sequence,
                'quality': quality,
                'indels': applied_indels,
                'original_length': original_length,
                'new_length': len(sequence),
                'strand': indels_for_read[0]['read_strand']
            }
            
            # Verify length
            assert len(sequence) == original_length, f"Length mismatch for {read_name}: {len(sequence)} != {original_length}"
    
    # Update FASTQ file
    update_fastq_with_indels(fastq_file, modified_reads)
    
    # Update read_editing_positions file
    update_editing_positions_for_indels(
        f"{outdirectory}/read_editing_positions.csv",
        modified_reads
    )
    
    reference.close()

    # === OUTPUT MODIFIED_READS AS CSV ===
    csv_rows = []
    for read_name, data in modified_reads.items():
        for indel in data['indels']:
            indel_id = f"{indel.get('chrom', 'NA')}:{indel['genome_pos']}:{indel['ref']}:{indel['alt']}"
            csv_rows.append({
                'read_name': read_name,
                'sequence': data['sequence'],
                'original_length': data['original_length'],
                'new_length': data['new_length'],
                'strand': data['strand'],
                'indel_pos': indel['pos'],
                'indel_type': indel['type'],
                'indel_shift': indel['shift'],
                'indel_genome_pos': indel['genome_pos'],
                'indel_chrom':indel['chrom'],
                'indel_ref': indel['ref'],
                'indel_alt': indel['alt'],
                'num_original_reads_covering': indel_coverage.get(indel_id, 0)
            })
    
    csv_df = pd.DataFrame(csv_rows)
    csv_output = f"{outdirectory}/{read_bedfile_prename}.introduced_indel.csv"
    csv_df.to_csv(csv_output, index=False)
    print(f"Modified reads CSV saved to {csv_output}")

    return modified_reads


def process_indels_in_reads_spliced(outdirectory, read_bedfile_prename, reference_file, n_jobs=32):
    """Splice-aware version of process_indels_in_reads.

    Reads the BED12 file so that:
      1. Indel sites falling in introns of spliced reads are excluded.
      2. Within-read positions are correctly calculated from the exon block structure
         using _genomic_pos_to_read_pos.
      3. Deletion extension fetches sequence from the correct exon boundary rather
         than the full genomic span end (which may sit inside an intron gap).

    All FASTQ modification logic (update_fastq_with_indels, update_editing_positions_for_indels)
    is shared with the original function.
    """
    bed12_cols = ['chr', 'start', 'end', 'read_name', 'score', 'strand',
                  'thickStart', 'thickEnd', 'itemRgb',
                  'blockCount', 'blockSizes', 'blockStarts']
    reads_df = pd.read_csv(f"{outdirectory}/{read_bedfile_prename}.read.bed12",
                           sep='\t', header=None, names=bed12_cols)

    indels_file = outdirectory + "/" + "indels.txt"
    read_allelic_path = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
    try:
        indels_df = pd.read_csv(indels_file, sep='\t')
        read_allelic_df = pd.read_csv(read_allelic_path, sep='\t')
    except pd.errors.EmptyDataError:
        print("No indels found, skipping indel processing")
        return

    if indels_df.empty:
        print("No indels to process")
        return

    read_allelic_dict = dict(zip(read_allelic_df['read_name'], read_allelic_df['allele']))
    reference = pysam.FastaFile(reference_file)

    indel_read_mapping = {}
    indel_coverage = {}

    for idx, indel in tqdm(indels_df.iterrows(), total=len(indels_df),
                           desc="Finding overlapping reads (splice-aware)"):
        chrom  = indel['chrom']
        pos    = int(indel['pos'])       # 1-based genomic position
        ref    = indel['ref']
        alt    = indel['alt']
        freq   = indel['freq']
        allelic = indel['allelic']

        # Pre-filter by chromosome and genomic span
        candidates = reads_df[
            (reads_df['chr'] == chrom) &
            (reads_df['start'] < pos) &    # 0-based start < 1-based pos
            (reads_df['end']   >= pos)     # 0-based end   >= 1-based pos
        ]

        indel_id = f"{chrom}:{pos}:{ref}:{alt}"
        indel_coverage[indel_id] = 0

        for _, read in candidates.iterrows():
            read_name   = read['read_name']
            read_strand = read['strand']
            chrom_start = int(read['start'])
            chrom_end   = int(read['end'])

            # Parse exon blocks
            abs_blocks = _parse_bed12_blocks(chrom_start, read['blockSizes'], read['blockStarts'])

            # Check if indel position is in an exon block and get read-level position
            pos_in_read = _genomic_pos_to_read_pos(pos, abs_blocks, read_strand)
            if pos_in_read is None:
                continue   # intronic — skip

            # Convert 1-based pos_in_read to 0-based index for sequence manipulation
            pos_in_read_0 = pos_in_read - 1

            # Check that the full span of the indel (anchor through last ref base) is exonic.
            # For + strand this is positions pos..pos+len(ref)-1 (increasing genomic coords).
            # For - strand the same genomic span applies; the last ref base maps to the
            # 5'-most position in the revcomp read, so the same _genomic_pos_to_read_pos
            # check covers both strands correctly.
            indel_end_pos = pos + len(ref) - 1
            indel_end_read = _genomic_pos_to_read_pos(indel_end_pos, abs_blocks, read_strand)
            if indel_end_read is None:
                continue   # indel spans an intron or extends beyond the read

            # Bounds check
            total_read_len = sum(e - s for s, e in abs_blocks)
            if pos_in_read_0 < 0 or pos_in_read_0 >= total_read_len:
                continue

            indel_coverage[indel_id] = indel_coverage.get(indel_id, 0) + 1

            if read_name not in indel_read_mapping:
                indel_read_mapping[read_name] = []

            # For deletion extension: use the correct exon boundary, not chromEnd/chromStart
            # + strand: extend from end of last exon block
            # - strand: extend from start of first exon block
            exon_read_end   = abs_blocks[-1][1]   # 0-based, exclusive — last exon end
            exon_read_start = abs_blocks[0][0]    # 0-based — first exon start

            indel_read_mapping[read_name].append({
                'chrom':        chrom,
                'genome_pos':   pos,
                'pos_in_read':  pos_in_read_0,    # 0-based, consistent with original
                'ref':          ref,
                'alt':          alt,
                'freq':         freq,
                'allelic':      allelic,
                'strand':       read_strand,
                'read_strand':  read_strand,
                'indel_type':   'insertion' if len(alt) > len(ref) else 'deletion',
                'read_start':   exon_read_start,  # first exon start (for - strand extension)
                'read_end':     exon_read_end,    # last exon end   (for + strand extension)
                'indel_id':     indel_id,
            })

    # ── FASTQ modification (identical logic to original) ──────────────────────
    fastq_file = f"{outdirectory}/{read_bedfile_prename}.read2.bed2fa.fq"

    modified_reads = {}

    for record in tqdm(SeqIO.parse(fastq_file, "fastq"), desc="Processing FASTQ (splice-aware indels)"):
        read_name = record.id
        if read_name not in indel_read_mapping:
            continue

        read_allelic_val = read_allelic_dict.get(read_name, 0)
        original_sequence = str(record.seq)
        original_length   = len(original_sequence)
        sequence = original_sequence
        quality  = record.letter_annotations["phred_quality"].copy()

        indels_for_read = sorted(indel_read_mapping[read_name],
                                 key=lambda x: x['pos_in_read'], reverse=True)
        applied_indels = []

        for indel in indels_for_read:
            if indel['allelic'] == 'homo':
                apply_indel = True
            elif indel['allelic'] == str(read_allelic_val):
                apply_indel = True
            else:
                apply_indel = False

            if not apply_indel:
                continue

            pos_i     = indel['pos_in_read']
            ref_len   = len(indel['ref'])
            alt_len   = len(indel['alt'])
            read_strand = indel['read_strand']
            chrom_i   = indel['chrom']

            if pos_i < 0 or pos_i >= len(sequence):
                continue

            if indel['indel_type'] == 'insertion':
                insert_seq = indel['alt'][ref_len:]
                insert_len = len(insert_seq)
                if read_strand == '-':
                    # On minus strand the revcomp of the inserted sequence goes BEFORE
                    # the anchor base (VCF insertion is after anchor on + strand, which
                    # maps to before anchor after reverse-complement).
                    insert_seq = str(Seq(insert_seq).reverse_complement())
                    sequence = sequence[:pos_i] + insert_seq + sequence[pos_i:]
                    insert_qual = [37] * insert_len
                    quality = quality[:pos_i] + insert_qual + quality[pos_i:]
                else:
                    sequence = sequence[:pos_i + 1] + insert_seq + sequence[pos_i + 1:]
                    insert_qual = [37] * insert_len
                    quality = quality[:pos_i + 1] + insert_qual + quality[pos_i + 1:]
                sequence = sequence[:original_length]
                quality  = quality[:original_length]
                applied_indels.append({'chrom': chrom_i, 'pos': pos_i, 'type': indel['indel_type'],
                                       'shift': insert_len, 'genome_pos': indel['genome_pos'],
                                       'ref': indel['ref'], 'alt': indel['alt']})

            else:   # deletion
                del_len = ref_len - alt_len
                if read_strand == '-':
                    # On minus strand the deleted bases are BEFORE the anchor:
                    # genomic positions p+1..p+del_len map to read positions
                    # pos_i-1..pos_i-del_len after reverse-complement.
                    start_del = pos_i - del_len
                    if start_del >= 0:
                        sequence = sequence[:start_del] + sequence[pos_i:]
                        quality  = quality[:start_del]  + quality[pos_i:]
                    else:
                        sequence = sequence[pos_i:]
                        quality  = quality[pos_i:]
                else:
                    if pos_i + ref_len <= len(sequence):
                        sequence = sequence[:pos_i + 1] + sequence[pos_i + ref_len:]
                        quality  = quality[:pos_i + 1]  + quality[pos_i + ref_len:]
                    else:
                        sequence = sequence[:pos_i + 1]
                        quality  = quality[:pos_i + 1]

                extension_needed = original_length - len(sequence)
                if extension_needed > 0:
                    try:
                        if read_strand == '+':
                            # Extend from end of last exon block (correct for spliced reads)
                            ext_start = indel['read_end']
                            extension = reference.fetch(chrom_i, ext_start,
                                                        ext_start + extension_needed)
                            sequence = sequence + extension[:extension_needed]
                            quality  = quality  + [37] * extension_needed
                        else:
                            # Extend from start of first exon block (correct for spliced reads)
                            ext_end   = indel['read_start']
                            ext_start = max(0, ext_end - extension_needed)
                            extension = reference.fetch(chrom_i, ext_start, ext_end)
                            extension = str(Seq(extension).reverse_complement())
                            sequence = sequence + extension[:extension_needed]
                            quality  = quality  + [37] * extension_needed
                    except Exception as e:
                        print(f"Warning: Could not extend for {read_name}: {e}")
                        pad = 'N' * extension_needed
                        sequence = sequence + pad
                        quality  = quality  + [2] * extension_needed

                applied_indels.append({'chrom': chrom_i, 'pos': pos_i, 'type': indel['indel_type'],
                                       'shift': -del_len, 'genome_pos': indel['genome_pos'],
                                       'ref': indel['ref'], 'alt': indel['alt']})

        modified_reads[read_name] = {
            'sequence':        sequence,
            'quality':         quality,
            'indels':          applied_indels,
            'original_length': original_length,
            'new_length':      len(sequence),
            'strand':          indels_for_read[0]['read_strand'],
        }
        assert len(sequence) == original_length, \
            f"Length mismatch for {read_name}: {len(sequence)} != {original_length}"

    update_fastq_with_indels(fastq_file, modified_reads)
    update_editing_positions_for_indels(f"{outdirectory}/read_editing_positions.csv", modified_reads)

    reference.close()

    csv_rows = []
    for read_name, data in modified_reads.items():
        for indel in data['indels']:
            indel_id = f"{indel.get('chrom','NA')}:{indel['genome_pos']}:{indel['ref']}:{indel['alt']}"
            csv_rows.append({
                'read_name':               read_name,
                'sequence':                data['sequence'],
                'original_length':         data['original_length'],
                'new_length':              data['new_length'],
                'strand':                  data['strand'],
                'indel_pos':               indel['pos'],
                'indel_type':              indel['type'],
                'indel_shift':             indel['shift'],
                'indel_genome_pos':        indel['genome_pos'],
                'indel_chrom':             indel['chrom'],
                'indel_ref':               indel['ref'],
                'indel_alt':               indel['alt'],
                'num_original_reads_covering': indel_coverage.get(indel_id, 0),
            })

    csv_df = pd.DataFrame(csv_rows)
    csv_output = f"{outdirectory}/{read_bedfile_prename}.introduced_indel.csv"
    csv_df.to_csv(csv_output, index=False)
    print(f"Modified reads CSV saved to {csv_output}")

    return modified_reads


def update_fastq_with_indels(fastq_file, modified_reads):
    """
    Update FASTQ file with modified sequences containing indels.
    Maintains original read length.
    """
    
    updated_records = []
    
    for record in SeqIO.parse(fastq_file, "fastq"):
        if record.id in modified_reads:
            mod = modified_reads[record.id]
            
            # Verify length matches original
            assert len(mod['sequence']) == len(str(record.seq)), \
                f"Length mismatch for {record.id}"
            
            # Create new record with modified sequence and quality
            new_record = SeqRecord(
                Seq(mod['sequence']),
                id=record.id,
                name=record.name,
                description=record.description
            )
            
            # Convert quality scores back to phred format
            new_record.letter_annotations["phred_quality"] = mod['quality']
            updated_records.append(new_record)
        else:
            updated_records.append(record)
    
    # Write updated FASTQ
    with open(fastq_file, 'w') as out_handle:
        SeqIO.write(updated_records, out_handle, "fastq")
    
    print(f"Updated {len(modified_reads)} reads with indels in {fastq_file}")


def update_editing_positions_for_indels(editing_pos_file, modified_reads):
    """
    Update read_editing_positions.csv to account for position shifts caused by indels.
    Removes editing positions that fall outside the read after indel application.
    Handles strand-specific position adjustments correctly.

    Vectorized rewrite (byte-identical output to the previous per-row version, verified by
    md5 on a 5.5M-row real file): build a read_name -> row-index map ONCE and apply each
    read's indel shifts to its editing positions with numpy masks, instead of scanning the
    whole edit_df for every modified read (the old code did `edit_df['read_name'] == read_name`
    plus scalar `.loc` per site, i.e. O(num_reads * num_edit_rows) -> hours). Indel order does
    not affect the result: each shift's condition depends only on the original position and the
    shifts are summed. Runtime on a 5.5M-row table drops from ~hours to a few seconds.
    """
    # Read editing positions
    edit_df = pd.read_csv(editing_pos_file)

    # read_name -> positional row indices into edit_df, computed ONCE
    # (was an O(num_reads * num_edit_rows) full-column scan per read).
    groups = edit_df.groupby('read_name', sort=False).indices
    positions = edit_df['edit_position'].to_numpy()   # 1-based within-read positions

    rows_to_remove = []   # positional row indices

    # For each read with indels, adjust its editing positions
    for read_name, mod_info in tqdm(modified_reads.items(), desc="Updating editing positions"):
        idxs = groups.get(read_name)
        if idxs is None:
            continue   # no editing sites on this read

        read_strand = mod_info['strand']
        original_pos = positions[idxs]
        new_pos = original_pos.copy()

        # Apply cumulative shifts from indels.
        # indel['pos'] is 0-based; original_pos is 1-based.
        # For the same genomic site: indel['pos'] == original_pos - 1.
        #
        # + strand: insertion goes AFTER anchor (sequence[:pos_i+1]+ins+sequence[pos_i+1:]),
        #           deletion removes AFTER anchor (sequence[:pos_i+1]+sequence[pos_i+ref_len:]).
        #           Anchor stays in place → only positions strictly after anchor shift.
        #           Condition: indel['pos'] < original_pos - 1  (excludes anchor)
        #
        # - strand: insertion goes BEFORE anchor (sequence[:pos_i]+ins+sequence[pos_i:]),
        #           deletion removes BEFORE anchor (sequence[:pos_i-del_len]+sequence[pos_i:]).
        #           Anchor itself moves → positions at or after anchor shift.
        #           Condition: indel['pos'] < original_pos  (includes anchor)
        for indel in sorted(mod_info['indels'], key=lambda x: x['pos']):
            if read_strand == '+':
                mask = indel['pos'] < original_pos - 1
            else:
                mask = indel['pos'] < original_pos
            new_pos[mask] += indel['shift']

        # Editing sites whose new position fell outside the read are dropped; rest are updated.
        out_of_bounds = (new_pos < 1) | (new_pos > mod_info['original_length'])
        rows_to_remove.extend(idxs[out_of_bounds].tolist())
        positions[idxs[~out_of_bounds]] = new_pos[~out_of_bounds]

    edit_df['edit_position'] = positions

    # Remove editing positions that fell outside reads
    if rows_to_remove:
        edit_df = edit_df.drop(edit_df.index[rows_to_remove])
        print(f"Removed {len(rows_to_remove)} editing positions that fell outside reads after indel application")

    # Save updated editing positions
    edit_df.to_csv(editing_pos_file, index=False)
    print(f"Updated editing positions in {editing_pos_file}")


def assign_read_alleles(outdirectory, read_bedfile_prename):
    """
    Assign allele (0 or 1) to each read and save the assignments.
    
    Parameters:
    -----------
    outdirectory : str
        Output directory
    read_bedfile_prename : str
        Base name for output files
    
    Returns:
    --------
    dict : Dictionary mapping read_name to allele (0 or 1)
    """
    import random
    random.seed(2023)
    reads_df = pd.read_csv(f"{outdirectory}/{read_bedfile_prename}.read.bed", 
                          sep='\t', header=None, 
                          names=['chr', 'start', 'end', 'read_name', 'length', 'strand'])
    # Assign random allele to each read
    read_alleles = {}
    for read_name in reads_df['read_name']:
        read_alleles[read_name] = random.choice([0, 1])
    
    # Save allele assignments
    allele_df = pd.DataFrame([
        {'read_name': read_name, 'allele': allele}
        for read_name, allele in read_alleles.items()
    ])
    
    allele_file = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
    allele_df.to_csv(allele_file, sep='\t', index=False)
    print(f"Saved read allele assignments to {allele_file}")
    
    # return read_alleles




