"""
Enhanced somatic mutation code with EXACT per-position tracking during FASTQ application.

This version tracks exactly what happened to each mutation during apply_somatic_mutations_to_fastq:
- How many reads were supposed to get each mutation
- How many actually got the mutation (success)
- How many failed (bounds/ref mismatch)
- Which specific cells succeeded vs failed
"""

import pandas as pd
import numpy as np
import os
from collections import defaultdict


def parse_bed_file(bed_file):
    """Parse BED file to get read coordinates and cell barcodes."""
    reads_by_position = defaultdict(list)
    with open(bed_file, 'r') as f:
        for line in f:
            if line.startswith('#') or line.strip() == '':
                continue
            
            parts = line.strip().split('\t')
            if len(parts) < 6:
                continue
                
            chrom = parts[0]
            start = int(parts[1]) + 1
            end = int(parts[2])
            read_name = parts[3]
            strand = parts[5]
            
            # Extract cell barcode from read name
            if ':' in read_name:
                barcode = read_name.split(':')[0][:16]
            else:
                barcode = read_name[:16] if len(read_name) >= 16 else read_name
            
            reads_by_position[(chrom, start, end)].append((barcode, read_name, strand))
    
    return reads_by_position


def find_overlapping_reads(mutation_pos, reads_by_position, window=1000):
    """Find all reads that overlap a specific mutation position."""
    chrom, pos = mutation_pos
    overlapping_reads = defaultdict(list)
    
    for (read_chr, read_start, read_end), read_list in reads_by_position.items():
        if read_chr == chrom and read_start <= pos <= read_end:
            for barcode, read_name, strand in read_list:
                overlapping_reads[barcode].append((read_name, strand, read_start, read_end))
    
    return overlapping_reads


def sample_cells_for_mutation(overlapping_cells, baf_alt, min_cells=1):
    """Sample cells based on BAF_alt value."""
    if len(overlapping_cells) == 0:
        return []
    
    total_reads = sum(len(reads) for reads in overlapping_cells.values())
    n_reads_to_mutate = max(min_cells, int(np.round(total_reads * baf_alt)))
    
    all_reads = []
    for barcode, read_list in overlapping_cells.items():
        for read_name, strand, start, end in read_list:
            all_reads.append((barcode, read_name, strand, start, end))
    
    if n_reads_to_mutate >= len(all_reads):
        return all_reads
    else:
        sampled_indices = np.random.choice(len(all_reads), size=n_reads_to_mutate, replace=False)
        return [all_reads[i] for i in sampled_indices]


def load_exclusion_sites(somatic_mutation_df, snp_file=None, editing_file=None):
    """Load SNP and RNA editing sites to exclude from somatic mutations."""
    snp_file = pd.read_csv(snp_file, sep='\t')
    editing_file = pd.read_csv(editing_file, sep='\t')
    
    result = somatic_mutation_df.merge(
        snp_file[['Region', 'Position']], 
        on=['Region', 'Position'], 
        how='left', indicator=True)
    df_filtered = result[result['_merge'] == 'left_only'].drop('_merge', axis=1)
    
    result2 = df_filtered.merge(
        editing_file[['Region', 'Position']], 
        on=['Region', 'Position'], 
        how='left', indicator=True)
    df_filtered2 = result2[result2['_merge'] == 'left_only'].drop('_merge', axis=1)
    
    return df_filtered2


def create_mutation_map(somatic_mutations_file, bed_file, outdirectory, min_baf=0.0, 
                        snp_file=None, editing_file=None):
    """
    Create a mapping of which reads should have which somatic mutations.
    WITH COVERAGE AND CELL TRACKING
    """
    print("Loading somatic mutations table...")
    
    # Auto-detect separator
    with open(somatic_mutations_file, 'r') as f:
        first_line = f.readline()
        separator = ',' if ',' in first_line else '\t'
    
    print(f"Detected separator: {'comma (CSV)' if separator == ',' else 'tab (TSV)'}")
    
    mutations_df = pd.read_csv(somatic_mutations_file, sep=separator)
    
    print(f"Loaded {len(mutations_df)} mutations from file")
    print(f"Columns detected: {list(mutations_df.columns)[:5]}...")
    
    mutations_df.columns.values[:4] = ['Region', 'Position', 'Ref', 'Ed']

    # Load exclusion sites
    mutations_df = load_exclusion_sites(somatic_mutation_df=mutations_df, 
                                       snp_file=snp_file, 
                                       editing_file=editing_file)
    
    # Filter by quality scores
    mutations_df = mutations_df[
        (mutations_df['SVM_pos_score'] > 0.1) &
        (mutations_df['LDrefine_merged_score'] > 0.25) &
        (mutations_df['BAF_alt'] >= 0.1) &
        (mutations_df['BAF_alt'] < 0.5) &
        (mutations_df['Depth_ref'] > 5) &
        (mutations_df['Depth_alt'] > 5)]

    # Parse BED file
    reads_by_position = parse_bed_file(bed_file)
    
    # Store mutations per read
    read_mutations = defaultdict(list)
    
    # Statistics
    stats = {
        'total_mutations': len(mutations_df),
        'mutations_with_overlaps': 0,
        'total_reads_mutated': 0,
        'mutations_by_baf': defaultdict(int)
    }
    
    # Tracking: planned mutations
    mutation_tracking = []
    
    print("\nProcessing mutations with detailed tracking...")
    for idx, row in mutations_df.iterrows():
        chrom = row['Region']
        pos = int(row['Position'])
        ref = row['Ref']
        alt = row['Ed']
        baf_alt = float(row['BAF_alt'])
        
        # Find overlapping reads
        overlapping_cells = find_overlapping_reads((chrom, pos), reads_by_position)
        
        # Count total reads covering
        total_reads_covering = sum(len(reads) for reads in overlapping_cells.values())
        
        if len(overlapping_cells) == 0:
            mutation_tracking.append({
                'Chr': chrom,
                'Position': pos,
                'Ref': ref,
                'Alt': alt,
                'BAF_alt': baf_alt,
                'reads_covering': 0,
                'reads_planned': 0,
                'cells_planned': ''
            })
            continue
            
        stats['mutations_with_overlaps'] += 1
        
        # Sample reads to mutate
        reads_to_mutate = sample_cells_for_mutation(overlapping_cells, baf_alt)
        
        n_reads_planned = len(reads_to_mutate)
        
        stats['total_reads_mutated'] += n_reads_planned
        stats['mutations_by_baf'][f"{baf_alt:.2f}"] += 1
        
        # Track which cells are planned to get the mutation
        cells_planned = set()
        
        # Record mutations for each sampled read
        for barcode, read_name, strand, start, end in reads_to_mutate:
            cells_planned.add(barcode)
            
            rel_pos = pos - start
            read_mutations[read_name].append({
                'pos': pos,
                'ref': ref,
                'alt': alt,
                'rel_pos': rel_pos,
                'strand': strand,
                'barcode': barcode,
                'baf_alt': baf_alt
            })
        
        # Store planned mutation info
        mutation_tracking.append({
            'Chr': chrom,
            'Position': pos,
            'Ref': ref,
            'Alt': alt,
            'BAF_alt': baf_alt,
            'reads_covering': total_reads_covering,
            'reads_planned': n_reads_planned,
            'cells_planned': ','.join(sorted(cells_planned))
        })
    
    # Save basic statistics
    stats_file = os.path.join(outdirectory, 'somatic_mutation_stats.txt')
    with open(stats_file, 'w') as f:
        f.write(f"Total mutations in table: {stats['total_mutations']}\n")
        f.write(f"Mutations with overlapping reads: {stats['mutations_with_overlaps']}\n")
        f.write(f"Total reads planned to mutate: {stats['total_reads_mutated']}\n")
        f.write(f"\nMutations by BAF_alt:\n")
        for baf, count in sorted(stats['mutations_by_baf'].items()):
            f.write(f"  BAF {baf}: {count} mutations\n")
    
    print(f"\nStatistics saved to {stats_file}")
    print(f"Total reads planned to mutate: {stats['total_reads_mutated']}")
    
    # Save planned mutations (before application)
    mutation_tracking_df = pd.DataFrame(mutation_tracking)
    tracking_file = os.path.join(outdirectory, 'mutation_planning.tsv')
    mutation_tracking_df.to_csv(tracking_file, sep='\t', index=False)
    print(f"Mutation planning saved to {tracking_file}")
    
    # Save per-read mutation map
    mutation_map_file = os.path.join(outdirectory, 'read_somatic_mutations.csv')
    mutation_records = []
    for read_name, mutations in read_mutations.items():
        for mut in mutations:
            mutation_records.append({
                'read_name': read_name,
                'barcode': mut['barcode'],
                'pos': mut['pos'],
                'ref': mut['ref'],
                'alt': mut['alt'],
                'rel_pos': mut['rel_pos'],
                'strand': mut['strand'],
                'baf_alt': mut['baf_alt']
            })
    
    mutation_map_df = pd.DataFrame(mutation_records)
    mutation_map_df.to_csv(mutation_map_file, index=False)
    print(f"Mutation map saved to {mutation_map_file}")
    
    return read_mutations

def introduce_somatic_mutations(somatic_mutations_file, BED_filename_combined_pre, 
                                 outdirectory, min_baf=0.0):
    """
    Main function to introduce somatic mutations with EXACT tracking.
    """
    print("=" * 80)
    print("Introducing Somatic Mutations with EXACT APPLICATION TRACKING")
    print("=" * 80)
    bed_file_combined = outdirectory + "/" + BED_filename_combined_pre + ".read.bed"
    input_fastq_r2 = outdirectory + "/" + BED_filename_combined_pre + ".ErrorIncluded.read2.bed2fa.sorted.fq"
    output_fastq_r2 = outdirectory + "/" + BED_filename_combined_pre + ".ErrorIncluded.SomaticIncluded.read2.bed2fa.sorted.fq"
    snp_file = outdirectory + "/" + "SNPs.txt"
    editing_file = outdirectory + "/" + "RNA_editing_sites_levels.txt"
    # Step 1: Create mutation map (plan mutations)
    read_mutations = create_mutation_map(
        somatic_mutations_file=somatic_mutations_file,
        bed_file=bed_file_combined,
        outdirectory=outdirectory,
        min_baf=min_baf,
        snp_file=snp_file,
        editing_file=editing_file
    )
    
    print("\n" + "=" * 80)
    print("Applying mutations to FASTQ files with EXACT tracking")
    print("=" * 80)
    
    # Step 2: Apply mutations with exact tracking
    r2_results = apply_somatic_mutations_to_fastq(
        input_fastq=input_fastq_r2,
        output_fastq=output_fastq_r2,
        read_mutations=read_mutations,
        outdirectory=outdirectory
    )
    
    # Step 3: Merge planning and results
    print("\n" + "=" * 80)
    print("Merging planning and application results")
    print("=" * 80)
    
    # Load planning data
    planning_df = pd.read_csv(os.path.join(outdirectory, 'mutation_planning.tsv'), sep='\t')
    results_df = r2_results['results_df']
    
    # Merge
    final_df = planning_df.merge(
        results_df, 
        on='Position', 
        how='left'
    )
    
    # Fill NaN for positions that were planned but never attempted (shouldn't happen)
    final_df = final_df.fillna({
        'reads_attempted': 0,
        'reads_success': 0,
        'reads_failed_bounds': 0,
        'reads_failed_ref_mismatch': 0,
        'success_rate': 0.0
    })
    
    # Calculate discrepancies
    final_df['discrepancy'] = final_df['reads_planned'] - final_df['reads_attempted']
    
    # Save final comprehensive report
    final_file = os.path.join(outdirectory, 'mutation_complete_report.tsv')
    final_df.to_csv(final_file, sep='\t', index=False)
    
    print(f"\n✓ COMPLETE MUTATION REPORT: {final_file}")
    print(f"  This file contains:")
    print(f"    - Planning: reads_covering, reads_planned, cells_planned")
    print(f"    - Results: reads_attempted, reads_success, reads_failed_*")
    print(f"    - Success rate per position")
    print(f"    - Which cells succeeded vs failed")
    
    # Print summary statistics
    print(f"\n{'='*80}")
    print("FINAL SUMMARY")
    print('='*80)
    print(f"Total mutation sites: {len(final_df)}")
    print(f"Sites with coverage: {(final_df['reads_covering'] > 0).sum()}")
    print(f"Sites with planned mutations: {(final_df['reads_planned'] > 0).sum()}")
    print(f"Sites with successful mutations: {(final_df['reads_success'] > 0).sum()}")
    print(f"\nReads:")
    print(f"  Planned: {final_df['reads_planned'].sum()}")
    print(f"  Attempted: {final_df['reads_attempted'].sum()}")
    print(f"  Success: {final_df['reads_success'].sum()}")
    print(f"  Failed (bounds): {final_df['reads_failed_bounds'].sum()}")
    print(f"  Failed (ref mismatch): {final_df['reads_failed_ref_mismatch'].sum()}")
    
    # Check for discrepancies
    discrepancies = final_df[final_df['discrepancy'] != 0]
    if len(discrepancies) > 0:
        print(f"\n⚠ WARNING: {len(discrepancies)} positions have discrepancies")
        print(f"  (planned ≠ attempted - check {final_file})")
    
    print("\n" + "=" * 80)
    print("✓ Somatic mutations successfully introduced with EXACT tracking!")
    print("=" * 80)
    
    return {
        'final_report': final_df,
        'r2_results': r2_results
    }


def reverse_complement(seq):
    """
    Get reverse complement of a DNA sequence.
    """
    complement = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G', 'N': 'N'}
    return ''.join([complement.get(base.upper(), base) for base in seq[::-1]])


def apply_somatic_mutations_to_fastq(input_fastq, output_fastq, read_mutations, outdirectory):
    """
    Apply somatic mutations to FASTQ file with EXACT per-position tracking.
    
    *** STRAND-AWARE: Reverse complements ref/alt for minus strand reads ***
    *** POSITION-AWARE: Calculates position from opposite end for minus strand ***
    
    Args:
        input_fastq: input FASTQ file path
        output_fastq: output FASTQ file path
        read_mutations: dict mapping read_name to list of mutations
        outdirectory: directory to save tracking results
    
    Returns:
        Dictionary with detailed per-position results
    """
    print(f"\nApplying somatic mutations to {input_fastq} with EXACT tracking...")
    print("*** STRAND-AWARE: Will reverse complement ref/alt for minus strand reads ***")
    print("*** POSITION-AWARE: Calculates position from read end for minus strand ***")
    
    reads_processed = 0
    reads_mutated = 0
    total_mutations_applied = 0
    
    # Track results per position
    position_results = defaultdict(lambda: {
        'attempted': 0,
        'success': 0,
        'failed_bounds': 0,
        'failed_ref_mismatch': 0,
        'cells_attempted': set(),
        'cells_success': set(),
        'cells_failed': set(),
        'strand_plus': 0,
        'strand_minus': 0
    })
    
    with open(input_fastq, 'r') as infile, open(output_fastq, 'w') as outfile:
        while True:
            # Read FASTQ record (4 lines)
            header = infile.readline()
            if not header:
                break
            
            sequence = infile.readline().strip()
            plus = infile.readline()
            quality = infile.readline().strip()
            
            reads_processed += 1
            
            # Extract read name from header
            read_name = header.strip().split()[0][1:]
            
            # Check if this read should be mutated
            if read_name in read_mutations:
                sequence = list(sequence)
                read_length = len(sequence)
                
                for mut in read_mutations[read_name]:
                    rel_pos = mut['rel_pos']
                    ref = mut['ref']
                    alt = mut['alt']
                    pos = mut['pos']
                    barcode = mut['barcode']
                    strand = mut['strand']
                    
                    # *** CRITICAL: Handle minus strand differently ***
                    if strand == '-':
                        # Reverse complement ref and alt
                        ref_to_check = reverse_complement(ref)
                        alt_to_apply = reverse_complement(alt)
                        
                        # *** FIX: Calculate position from opposite end ***
                        # For minus strand: position 0 should be at the read end
                        rel_pos_adjusted = read_length - 1 - rel_pos
                        
                        position_results[pos]['strand_minus'] += 1
                    else:
                        # Plus strand: use as-is
                        ref_to_check = ref
                        alt_to_apply = alt
                        rel_pos_adjusted = rel_pos
                        
                        position_results[pos]['strand_plus'] += 1
                    
                    # Track attempt
                    position_results[pos]['attempted'] += 1
                    position_results[pos]['cells_attempted'].add(barcode)
                    
                    # Check bounds
                    if 0 <= rel_pos_adjusted < read_length:
                        # Verify reference allele matches
                        if sequence[rel_pos_adjusted].upper() == ref_to_check.upper():
                            sequence[rel_pos_adjusted] = alt_to_apply
                            total_mutations_applied += 1
                            
                            # Track success
                            position_results[pos]['success'] += 1
                            position_results[pos]['cells_success'].add(barcode)
                        else:
                            # Track ref mismatch
                            position_results[pos]['failed_ref_mismatch'] += 1
                            position_results[pos]['cells_failed'].add(barcode)
                    else:
                        # Track out of bounds
                        position_results[pos]['failed_bounds'] += 1
                        position_results[pos]['cells_failed'].add(barcode)
                
                sequence = ''.join(sequence)
                reads_mutated += 1
            
            # Write record
            outfile.write(header)
            outfile.write(sequence + '\n')
            outfile.write(plus)
            outfile.write(quality + '\n')
    
    print(f"Processed {reads_processed} reads")
    print(f"Mutated {reads_mutated} reads")
    print(f"Applied {total_mutations_applied} mutations")
    
    # Create detailed per-position results table
    results_records = []
    for pos, results in position_results.items():
        results_records.append({
            'Position': pos,
            'reads_attempted': results['attempted'],
            'reads_success': results['success'],
            'reads_failed_bounds': results['failed_bounds'],
            'reads_failed_ref_mismatch': results['failed_ref_mismatch'],
            'strand_plus_count': results['strand_plus'],
            'strand_minus_count': results['strand_minus'],
            'cells_attempted': ','.join(sorted(results['cells_attempted'])),
            'cells_success': ','.join(sorted(results['cells_success'])),
            'cells_failed': ','.join(sorted(results['cells_failed'])),
            'success_rate': results['success'] / results['attempted'] if results['attempted'] > 0 else 0.0
        })
    
    results_df = pd.DataFrame(results_records).sort_values('Position')
    
    # Save exact application results
    results_file = os.path.join(outdirectory, 'mutation_application_results.tsv')
    results_df.to_csv(results_file, sep='\t', index=False)
    
    print(f"\n{'='*80}")
    print("EXACT MUTATION APPLICATION RESULTS (STRAND-AWARE)")
    print('='*80)
    print(f"Results saved to: {results_file}")
    print(f"\nSummary:")
    print(f"  Total positions attempted: {len(results_df)}")
    print(f"  Total reads attempted: {results_df['reads_attempted'].sum()}")
    print(f"  Total reads success: {results_df['reads_success'].sum()}")
    print(f"  Total reads failed (bounds): {results_df['reads_failed_bounds'].sum()}")
    print(f"  Total reads failed (ref mismatch): {results_df['reads_failed_ref_mismatch'].sum()}")
    print(f"  Overall success rate: {results_df['reads_success'].sum() / results_df['reads_attempted'].sum():.4f}")
    print(f"\nStrand distribution:")
    print(f"  Plus strand reads: {results_df['strand_plus_count'].sum()}")
    print(f"  Minus strand reads: {results_df['strand_minus_count'].sum()}")
    
    # Check for positions with failures
    failed_positions = results_df[
        (results_df['reads_failed_bounds'] > 0) | 
        (results_df['reads_failed_ref_mismatch'] > 0)
    ]
    
    if len(failed_positions) > 0:
        print(f"\n⚠ WARNING: {len(failed_positions)} positions had some failures")
        print(f"  See {results_file} for details")
    
    return {
        'results_df': results_df,
        'total_attempted': results_df['reads_attempted'].sum(),
        'total_success': results_df['reads_success'].sum(),
        'total_failed_bounds': results_df['reads_failed_bounds'].sum(),
        'total_failed_ref_mismatch': results_df['reads_failed_ref_mismatch'].sum()
    }


def output_vcf_from_csvs(snv_csv, indel_csv, out_vcf, dp_threshold=0):
    """
    Simple pandas translation of your R:
      - filter SNVs: category=='snp', editing_level>0, (unedited_reads+edited_reads) >= dp_threshold
      - drop duplicates ignoring 'Strand'
      - group INDELs, compute edited/unedited reads, filter by DP >= dp_threshold
      - write a minimal-valid VCF (8 mandatory columns)
    """
    # --- SNV ---
    snv = pd.read_csv(snv_csv)
    snv = snv.rename(columns={
        snv.columns[0]: "chr",
        snv.columns[1]: "edit_position_whole_genome",
        snv.columns[2]: "orig_seq",
        snv.columns[3]: "mutated_seq",
    })
    # ensure needed columns exist
    for c in ["category", "editing_level", "unedited_reads", "edited_reads", "Strand"]:
        if c not in snv.columns:
            snv[c] = 0 if c in ("unedited_reads", "edited_reads") else (0.0 if c=="editing_level" else ("unknown" if c=="category" else ""))
    gt_snp = snv[
        (snv["category"] == "snp") &
        (snv["editing_level"] > 0) &
        ((snv["unedited_reads"] + snv["edited_reads"]) >= dp_threshold)
    ].copy()
    gt_snp = gt_snp.drop_duplicates(subset=[c for c in gt_snp.columns if c != "Strand"])
    gt_snp = gt_snp[["chr","edit_position_whole_genome","orig_seq","mutated_seq"]]
    # --- INDEL ---
    indel_raw = pd.read_csv(indel_csv)
    gt_indel = (
        indel_raw.groupby(["indel_chrom","indel_genome_pos","indel_ref","indel_alt"], as_index=False)
        .agg(chr=("indel_chrom","first"),
             edit_position_whole_genome=("indel_genome_pos","first"),
             orig_seq=("indel_ref","first"),
             mutated_seq=("indel_alt","first"),
             edited_reads=("indel_alt","size"),
             total_reads=("num_original_reads_covering","first"))
    )
    gt_indel["unedited_reads"] = gt_indel["total_reads"] - gt_indel["edited_reads"]
    gt_indel["DP"] = gt_indel["edited_reads"] + gt_indel["unedited_reads"]
    gt_indel = gt_indel[gt_indel["DP"] >= dp_threshold]
    gt_indel = gt_indel[gt_indel["edited_reads"] >= 1]
    gt_indel = gt_indel[["chr","edit_position_whole_genome","orig_seq","mutated_seq"]]
    # --- Merge & sort ---
    merged = pd.concat([gt_snp, gt_indel], ignore_index=True)
    merged = merged.drop_duplicates().sort_values(["chr","edit_position_whole_genome","orig_seq","mutated_seq"])
    # --- Write minimal VCF (8 mandatory columns) ---
    with open(out_vcf, "w") as f:
        f.write("##fileformat=VCFv4.2\n")
        f.write("#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n")
        for _, r in merged.iterrows():
            ref, alt = str(r.orig_seq), str(r.mutated_seq)
            if not ref or not alt or ref == alt:
                continue
            f.write(f"{r.chr}\t{int(r.edit_position_whole_genome)}\t.\t{ref}\t{alt}\t.\tPASS\t.\n")
    # Compress and index properly
    subprocess.run(["bgzip", "-f", out_vcf], check=True)
    subprocess.run(["tabix", "-p", "vcf", out_vcf + ".gz"], check=True)


# ============================================================================
# Haplotype-aware allele-specific expression (ASE) extension
# ----------------------------------------------------------------------------
# New, additive functions (do NOT modify the originals above).  They make the
# simulator use the REAL phased genotype (GT) of the GIAB VCF to assign each
# variant to a haplotype, and assign reads to haplotypes per a per-gene/intergene
# allelic ratio sampled from an empirical pool, so that every read carries the
# variants of exactly one haplotype (plus homozygous variants) — preserving phase.
#
# Invariant: a variant's 'allelic' is ALWAYS a string 'homo' / '0' / '1', where
# '0'/'1' is the GT slot (left/right of a|b) carrying the ALT.  A read's 'allele'
# is an int 0/1 (the haplotype it is drawn from).  The existing gating
# (process_read_chunk_parallel_spliced / process_indels_in_reads_spliced) then
# links all same-haplotype variants automatically.
# ============================================================================

def _load_allelic_ratio_pool(rds_path, cache_npy=None, rscript_path=None):
    """Load the pooled allelic-ratio vector (an R .rds flat numeric vector in [0,1]).

    First call exports the vector to a float64 binary via ``Rscript`` (no rpy2 / R_HOME
    setup required) and caches it to ``<rds_path>.npy``; later calls memory-map the cache
    (near-zero RAM).  Call from the parent process only (not inside a joblib/loky worker).
    """
    import shutil
    if cache_npy is None:
        cache_npy = rds_path + ".npy"
    if os.path.exists(cache_npy):
        return np.load(cache_npy, mmap_mode='r')
    if rscript_path is None:
        rscript_path = (shutil.which("Rscript")
                        or "/u/home/w/weijian/.conda/envs/scIsoSim/bin/Rscript")
    bin_path = cache_npy + ".f64.bin"
    rcode = ('args <- commandArgs(trailingOnly=TRUE);'
             'x <- as.double(readRDS(args[1])); x <- x[is.finite(x)];'
             'con <- file(args[2], "wb"); writeBin(x, con, size=8); close(con)')
    subprocess.run([rscript_path, "-e", rcode, rds_path, bin_path], check=True)
    vec = np.fromfile(bin_path, dtype=np.float64)   # native endianness (writeBin default)
    np.save(cache_npy, vec)
    try:
        os.remove(bin_path)
    except OSError:
        pass
    return vec


def _gt_to_allelic(gt):
    """Map a phased biallelic GT string to an 'allelic' label.

    Returns 'homo' (both slots carry the ALT), '0'/'1' (the single slot carrying
    the ALT), or None if the genotype is unusable here: a no-call, homozygous
    reference (0|0), or multiallelic (any slot referencing ALT index >= 2, e.g.
    1|2 / 2|1).  Callers must also reject records with len(ALT) > 1.
    """
    if gt is None:
        return None
    slots = str(gt).replace('|', '/').split('/')
    if any(s in ('.', '') for s in slots):
        return None                       # missing / no-call
    if any(s not in ('0', '1') for s in slots):
        return None                       # multiallelic genotype -> drop
    carriers = [i for i, s in enumerate(slots) if s == '1']
    if len(carriers) == 0:
        return None                       # 0|0 -> no variant
    if len(slots) == 1 or len(carriers) == 2:
        return 'homo'                     # haploid-ALT or 1|1
    return str(carriers[0])               # heterozygous -> '0' or '1'


def prepare_SNP_RED_list_phased(INPUT_SNP_site, INPUT_INDEL_site, INPUT_RED_site, outdirectory,
                                min_edit=0.05, max_edit=0.95, tissue='Lung', include_SNPs=True,
                                sample_index=0):
    """Phased, haplotype-aware drop-in for prepare_SNP_RED_list.

    Writes SNPs.txt, indels.txt, RNA_editing_sites_levels.txt with the SAME columns
    as prepare_SNP_RED_list, EXCEPT each variant's 'allelic' label is derived from the
    phased genotype (GT) of VCF sample ``sample_index`` instead of being random:

        GT 0|1 -> '1'    GT 1|0 -> '0'    GT 1|1 -> 'homo'

    Multiallelic sites (len(ALT) > 1, or GT referencing allele index >= 2 such as
    1|2 / 2|1) are dropped.  'allelic' is stored as a STRING ('homo'/'0'/'1').
    """
    def _read_variants(path):
        rows = []
        reader = vcfpy.Reader.from_path(path)
        for record in reader:
            if len(record.ALT) != 1:
                continue                                  # drop multiallelic
            gt = record.calls[sample_index].data.get('GT') if record.calls else None
            allelic = _gt_to_allelic(gt)
            if allelic is None:
                continue
            rows.append({
                'chrom': record.CHROM,
                'pos': record.POS,
                'ref': record.REF,
                'alt': extract_alt_allele(record.ALT[0]),
                'freq': float(record.INFO.get('AF', [0])[0]),
                'allelic': allelic,
            })
        return rows

    var_cols = ['chrom', 'pos', 'ref', 'alt', 'freq', 'allelic']
    snps_df = pd.DataFrame(_read_variants(INPUT_SNP_site))
    if snps_df.empty:
        snps_df = pd.DataFrame(columns=var_cols)
    indels_df = pd.DataFrame(_read_variants(INPUT_INDEL_site))
    if indels_df.empty:
        indels_df = pd.DataFrame(columns=var_cols)

    # One row per position (no multiallelics remain after the drop above).
    indels_df = indels_df.drop_duplicates(subset=['chrom', 'pos'], keep='first').reset_index(drop=True)

    # Keep only single-base ACGT SNVs.
    snps_df = snps_df[(snps_df['ref'].str.len() == 1) &
                      (snps_df['alt'].str.len() == 1) &
                      (snps_df['ref'].isin(['A', 'T', 'C', 'G'])) &
                      (snps_df['alt'].isin(['A', 'T', 'C', 'G']))]
    snps_df = snps_df.drop_duplicates(subset=['chrom', 'pos'], keep='first')

    # RNA editing sites: drop any that coincide with a SNP, or that fall anywhere within an
    # indel's full REF span [pos, pos+len(ref)-1] (not just the anchor), so no editing site
    # sits inside a deletion.
    red_df_filtered = pd.read_csv(INPUT_RED_site, delimiter="\t")
    red_df_filtered = red_df_filtered[~red_df_filtered['Position'].isin(snps_df['pos'])]
    _indel_span = set()
    for _ip, _ir in zip(indels_df['pos'], indels_df['ref']):
        _ip = int(_ip)
        _indel_span.update(range(_ip, _ip + max(1, len(str(_ir)))))
    red_df_filtered = red_df_filtered[~red_df_filtered['Position'].isin(_indel_span)]
    preferred_columns = ['Accession', 'Region', 'Position', 'Ref', 'Ed', 'Strand',
                         'type', 'Func.wgEncodeGencodeBasicV45', 'Gene.wgEncodeGencodeBasicV45', tissue]
    essential_columns = ['Region', 'Position', 'Ref', 'Ed', 'Strand', tissue]
    existing_preferred = [col for col in preferred_columns if col in red_df_filtered.columns]
    existing_essential = [col for col in essential_columns if col in red_df_filtered.columns]
    if len(existing_preferred) >= 9:
        red_df_filtered = red_df_filtered[existing_preferred]
    else:
        red_df_filtered = red_df_filtered[existing_essential]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue] >= min_edit]
    red_df_filtered = red_df_filtered[red_df_filtered[tissue] <= max_edit]
    red_df_filtered.to_csv("%s" % (outdirectory + "/" + "RNA_editing_sites_levels.txt"), index=None, sep='\t')

    # SNP table -> output column names (allelic already set from GT).
    snps_df['keep'] = snps_df['freq'] >= 0
    snps_df = snps_df[snps_df['keep']]
    snps_df['chrom'] = snps_df['chrom'].astype(str)
    snps_df = snps_df.rename(columns={'chrom': 'Region', 'pos': 'Position',
                                      'ref': 'Ref', 'alt': 'Ed', 'freq': 'frequency'})
    snps_df['editing_level'] = 1

    # Biological constraint: one allele cannot carry both a SNP and an indel at the
    # same site. With real phasing we must NOT re-assign the SNP's allele (that would
    # clobber the phase); we only DROP SNPs that genuinely conflict:
    #   - homozygous indel        -> drop every overlapping SNP
    #   - het indel on allele 'a' -> drop overlapping homozygous SNPs and overlapping
    #                                het SNPs already on allele 'a'; keep het SNPs on
    #                                the other allele unchanged.
    snps_to_remove = set()
    for _, indel_row in indels_df.iterrows():
        indel_chrom = str(indel_row['chrom'])
        indel_pos = int(indel_row['pos'])
        indel_end = indel_pos + len(str(indel_row['ref'])) - 1
        overlap_mask = (
            (snps_df['Region'] == indel_chrom) &
            (snps_df['Position'] >= indel_pos) &
            (snps_df['Position'] <= indel_end)
        )
        indel_allele = str(indel_row['allelic'])
        if indel_allele == 'homo':
            snps_to_remove.update(snps_df[overlap_mask].index)
        else:
            conflict = overlap_mask & (
                (snps_df['allelic'] == 'homo') | (snps_df['allelic'] == indel_allele)
            )
            snps_to_remove.update(snps_df[conflict].index)
    if snps_to_remove:
        snps_df = snps_df.drop(index=snps_to_remove)

    # Duplicate each SNP for both strands (matches prepare_SNP_RED_list).
    snps_df_positive = snps_df.copy(); snps_df_positive['Strand'] = "+"
    snps_df_negative = snps_df.copy(); snps_df_negative['Strand'] = "-"
    snps_df = pd.concat([snps_df_positive, snps_df_negative])
    snps_df['category'] = 'snp'
    if include_SNPs == False:
        snps_df = pd.DataFrame()

    col_order = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep',
                 'allelic', 'editing_level', 'Strand', 'category']
    if not snps_df.empty:
        snps_df = snps_df[col_order]
    snps_df.to_csv("%s" % (outdirectory + "/" + "SNPs.txt"), index=None, sep='\t')
    indels_df.to_csv("%s" % (outdirectory + "/" + "indels.txt"), index=None, sep='\t')


def assign_read_alleles_ASE(outdirectory, read_bedfile_prename, allelic_ratio_rds,
                            per_cell=False, seed=2023, cache_npy=None):
    """Assign each read a haplotype (allele 0/1) by per-feature allele-specific expression.

    For each gene/intergene feature, one ratio r in [0,1] is sampled from the empirical
    pool ``allelic_ratio_rds``; r is the probability that a read of that feature is drawn
    from haplotype 0.  Reads are Bernoulli-assigned accordingly.  With per_cell=True the
    ratio is drawn independently per (feature, cell).

    Reads the combined ``<prename>.read.bed12`` (same read names the editing/indel steps
    use) and writes:
      ``<prename>.read_alleles.txt``     columns: read_name, allele
      ``feature_allelic_ratios.txt``     ground-truth per-feature (and per-cell) ratios
    """
    np.random.seed(seed)
    random.seed(seed)

    bed12_cols = ['chr', 'start', 'end', 'read_name', 'score', 'strand',
                  'thickStart', 'thickEnd', 'itemRgb',
                  'blockCount', 'blockSizes', 'blockStarts']
    reads_df = pd.read_csv(f"{outdirectory}/{read_bedfile_prename}.read.bed12",
                           sep='\t', header=None, names=bed12_cols)
    read_names = reads_df['read_name'].astype(str).tolist()

    # read name = {CB16}{UMI10}:CellNo{N}:{chrom_start_end}#{count}
    def parse_feature(rn):
        return rn.split(':')[2].split('#')[0]

    pool = _load_allelic_ratio_pool(allelic_ratio_rds, cache_npy=cache_npy)
    n_pool = len(pool)

    ratio_cache = {}
    def get_ratio(key):
        r = ratio_cache.get(key)
        if r is None:
            r = float(pool[np.random.randint(n_pool)])
            ratio_cache[key] = r
        return r

    rand = np.random.random(len(read_names))
    alleles = np.empty(len(read_names), dtype=int)
    grp_reads = defaultdict(int)
    grp_allele0 = defaultdict(int)
    grp_ratio = {}
    for i, rn in enumerate(read_names):
        feature = parse_feature(rn)
        key = (feature, rn[:16]) if per_cell else feature
        r = get_ratio(key)
        a = 0 if rand[i] < r else 1
        alleles[i] = a
        grp_reads[key] += 1
        grp_allele0[key] += int(a == 0)
        grp_ratio[key] = r

    allele_file = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
    pd.DataFrame({'read_name': read_names, 'allele': alleles}).to_csv(allele_file, sep='\t', index=False)
    print(f"Saved read allele assignments (per-feature ASE) to {allele_file}")

    rows = []
    for key in grp_reads:
        if per_cell:
            feature, cell = key
            rows.append({'feature': feature, 'cell': cell, 'ratio': grp_ratio[key],
                         'n_reads': grp_reads[key], 'n_allele0': grp_allele0[key]})
        else:
            rows.append({'feature': key, 'ratio': grp_ratio[key],
                         'n_reads': grp_reads[key], 'n_allele0': grp_allele0[key]})
    ratio_file = f"{outdirectory}/feature_allelic_ratios.txt"
    pd.DataFrame(rows).to_csv(ratio_file, sep='\t', index=False)
    print(f"Saved per-feature ASE ratios to {ratio_file}")


def prepare_editing_parallel_spliced_ASE(outdirectory, read_bedfile_prename, RNA_editing_list,
                                         SNPs, n_jobs=32, mode="10x"):
    """Haplotype/ASE version of prepare_editing_parallel_spliced.

    Identical to prepare_editing_parallel_spliced EXCEPT it does NOT re-randomize read
    alleles; it consumes the existing ``<prename>.read_alleles.txt`` written by
    assign_read_alleles_ASE, preserving the per-feature ASE / haplotype assignment.
    """
    if mode == '10x':
        bed12_cols = ['chr', 'start', 'end', 'read_name', 'score', 'strand',
                      'thickStart', 'thickEnd', 'itemRgb',
                      'blockCount', 'blockSizes', 'blockStarts']
        reads_df = pd.read_csv(
            outdirectory + "/" + read_bedfile_prename + ".read.bed12",
            sep='\t', header=None, names=bed12_cols
        )

        # Consume pre-assigned ASE alleles (do NOT re-randomize or overwrite the file).
        allele_file = f"{outdirectory}/{read_bedfile_prename}.read_alleles.txt"
        allele_df = pd.read_csv(allele_file, sep='\t')
        n_before = len(reads_df)
        reads_df = reads_df.merge(allele_df[['read_name', 'allele']], on='read_name', how='left')
        assert len(reads_df) == n_before, "read count changed after allele merge"
        assert reads_df['allele'].isna().sum() == 0, "some reads missing an allele assignment"
        reads_df['allele'] = reads_df['allele'].astype(int)

        rna_editing_df = pd.read_csv(RNA_editing_list, sep='\t')
        rna_editing_df.rename(columns={rna_editing_df.columns[-1]: 'editing_level'}, inplace=True)

        try:
            snps_df = pd.read_csv(SNPs, sep='\t')
        except pd.errors.EmptyDataError:
            columns = ['Region', 'Position', 'Ref', 'Ed', 'frequency', 'keep', 'allelic',
                       'editing_level', 'Strand', 'category']
            snps_df = pd.DataFrame(columns=columns)

        rna_editing_df['category'] = "RNA_editing"
        rna_editing_df['allelic'] = "homo"
        rna_editing_df = pd.concat([snps_df, rna_editing_df], ignore_index=True, sort=False)

        read_chunks = [reads_df.iloc[i:i + 10000] for i in range(0, len(reads_df), 10000)]

        results = Parallel(n_jobs=n_jobs, backend='loky', batch_size='auto')(
            delayed(process_read_chunk_parallel_spliced)(chunk, rna_editing_df)
            for chunk in tqdm(read_chunks, desc="Processing RNA editing chunks (splice-aware, ASE)")
        )

        output_df = []
        all_overlapping_edits = []
        for result in results:
            output_df.extend(result[0])
            all_overlapping_edits.extend(result[1])

        output_df = pd.DataFrame(output_df)
        output_df.to_csv(outdirectory + "/" + 'read_editing_positions.csv', index=False)

        all_overlapping_edits_df = pd.concat(all_overlapping_edits, ignore_index=True) \
            if all_overlapping_edits else pd.DataFrame()
        if not all_overlapping_edits_df.empty:
            all_overlapping_edits_df['unedited_reads'] = 0
            all_overlapping_edits_df['edited_reads'] = 0
            all_overlapping_edits_df = all_overlapping_edits_df.drop_duplicates()
            all_overlapping_edits_df = all_overlapping_edits_df[
                all_overlapping_edits_df['editing_level'] != 0
            ]
        all_overlapping_edits_df.to_csv(
            outdirectory + "/" + 'Synthetic_RNA_editing_events.csv', index=False
        )


# ============================================================================
# COSMIC-guided, cell-type-specific somatic SNVs (optional layer)
# ----------------------------------------------------------------------------
# Each somatic SNV is sampled from a COSMIC VCF (coding or non-coding), placed on
# ONE allele (allele 0) of the gene/feature that contains it, assigned to exactly
# one Louvain cell type, and carried by 1..max_cells cells. Its VAF = that gene's
# sampled allelic ratio (the allele-0 read fraction). Only sites with pseudobulk
# coverage >= min_pseudobulk_reads and not overlapping germline SNPs/indels are used.
#
# Implementation: the somatic SNVs are injected as rows into read_editing_positions.csv
# (category 'somatic', allelic '0', editing_level 1, include 'T') BEFORE process_indels
# runs, so that update_editing_positions_for_indels shifts their within-read positions
# for any indels and the existing mutate_fastq_sequences_parallel applies them. No
# separate FASTQ pass; correct indel-aware placement for free.
# ============================================================================

def _load_cosmic_snvs(cosmic_vcf, chrom, cache_path=None):
    """Extract single-base SNVs for `chrom` from a COSMIC VCF(.gz).

    Returns a DataFrame [chrom, pos, ref, alt] (deduped). COSMIC uses numeric chrom
    names ('1'); output uses the pipeline's 'chr1'. The per-chrom subset is cached
    next to the VCF for reuse across runs.
    """
    num = chrom[3:] if str(chrom).startswith("chr") else str(chrom)
    if cache_path is None:
        cache_path = "%s.%s.snv.tsv" % (cosmic_vcf, chrom)
    if not os.path.exists(cache_path):
        awk = (r"""awk -F'\t' -v c="%s" '$1==c && length($4)==1 && length($5)==1 """
               r"""&& $4 ~ /^[ACGT]$/ && $5 ~ /^[ACGT]$/ {print "chr"$1"\t"$2"\t"$4"\t"$5}'""") % num
        cmd = "set -o pipefail; zcat %s | grep -v '^#' | %s | sort -u > %s" % (cosmic_vcf, awk, cache_path)
        subprocess.run(cmd, shell=True, executable="/bin/bash", check=True)
    return pd.read_csv(cache_path, sep="\t", header=None, names=["chrom", "pos", "ref", "alt"])


def introduce_somatic_mutations_cosmic(outdirectory, BED_filename_combined_pre, referenceGenome_file,
                                       cosmic_coding_vcf, cosmic_noncoding_vcf, chrom,
                                       n_coding=200, n_noncoding=200, max_cells=200,
                                       min_pseudobulk_reads=10, seed=2024, bedtools_path=None):
    """Generate COSMIC-guided somatic SNVs and inject them into read_editing_positions.csv.

    MUST run after assign_read_alleles_ASE + prepare_editing_parallel_spliced_ASE and BEFORE
    process_indels_in_reads_spliced. See module header above for the model.
    """
    import shutil
    rng = np.random.RandomState(seed)
    if bedtools_path is None:
        bedtools_path = shutil.which("bedtools") or "/u/home/w/weijian/.conda/envs/scIsoSim/bin/bedtools"

    bed12_path    = "%s/%s.read.bed12" % (outdirectory, BED_filename_combined_pre)
    alleles_path  = "%s/%s.read_alleles.txt" % (outdirectory, BED_filename_combined_pre)
    editpos_path  = "%s/read_editing_positions.csv" % outdirectory
    celltype_path = "%s/synthetic_cell_barcode.txt.withSynthCluster" % outdirectory
    ratio_path    = "%s/feature_allelic_ratios.txt" % outdirectory
    snp_path      = "%s/SNPs.txt" % outdirectory
    indel_path    = "%s/indels.txt" % outdirectory

    # read -> allele, barcode -> celltype, feature -> ratio
    al_df = pd.read_csv(alleles_path, sep='\t', dtype={'read_name': str})
    read_allele = dict(zip(al_df['read_name'].astype(str), al_df['allele'].astype(int)))
    ct_df = pd.read_csv(celltype_path, sep='\t', header=None, names=['barcode', 'celltype'], dtype=str)
    barcode_celltype = dict(zip(ct_df['barcode'].astype(str), ct_df['celltype'].astype(str)))
    fr_df = pd.read_csv(ratio_path, sep='\t')
    feature_ratio = dict(zip(fr_df['feature'].astype(str), fr_df['ratio'].astype(float)))

    # germline exclusion: SNP positions + indel spans
    excl = set()
    try:
        s = pd.read_csv(snp_path, sep='\t')
        excl.update(int(x) for x in s['Position'].tolist())
    except Exception:
        pass
    try:
        i = pd.read_csv(indel_path, sep='\t')
        for _, rr in i.iterrows():
            p0 = int(rr['pos']); ln = max(1, len(str(rr['ref'])))
            excl.update(range(p0, p0 + ln))
    except Exception:
        pass
    # also avoid RNA-editing sites so a somatic SNV never collides with an edit at the same base
    try:
        red = pd.read_csv("%s/RNA_editing_sites_levels.txt" % outdirectory, sep='\t')
        excl.update(int(x) for x in red['Position'].tolist())
    except Exception:
        pass

    reference = pysam.FastaFile(referenceGenome_file)

    def covered_pool(cosmic_vcf, tag):
        snv = _load_cosmic_snvs(cosmic_vcf, chrom).drop_duplicates(subset=['pos'])
        snv = snv[~snv['pos'].isin(excl)].copy()
        snv['start'] = snv['pos'] - 1
        cand_bed = "%s/_som_cand_%s.bed" % (outdirectory, tag)
        snv[['chrom', 'start', 'pos', 'ref', 'alt']].sort_values(['chrom', 'start']).to_csv(
            cand_bed, sep='\t', header=False, index=False)
        cov_bed = "%s/_som_cov_%s.bed" % (outdirectory, tag)
        cmd = ("set -o pipefail; %s intersect -a %s -b %s -split -sorted -c | awk -F'\\t' '$6>=%d' > %s"
               % (bedtools_path, cand_bed, bed12_path, min_pseudobulk_reads, cov_bed))
        subprocess.run(cmd, shell=True, executable="/bin/bash", check=True)
        try:
            cov = pd.read_csv(cov_bed, sep='\t', header=None,
                              names=['chrom', 'start', 'pos', 'ref', 'alt', 'depth'])
        except pd.errors.EmptyDataError:
            cov = pd.DataFrame(columns=['chrom', 'start', 'pos', 'ref', 'alt', 'depth'])
        # keep only sites where COSMIC REF matches the reference genome
        keep = []
        for _, rr in cov.iterrows():
            try:
                base = reference.fetch(str(rr['chrom']), int(rr['pos']) - 1, int(rr['pos'])).upper()
            except Exception:
                base = ""
            keep.append(base == str(rr['ref']).upper())
        cov = cov[pd.Series(keep, index=cov.index)] if len(cov) else cov
        for f in (cand_bed, cov_bed):
            try:
                os.remove(f)
            except OSError:
                pass
        return cov.reset_index(drop=True)

    cov_cod = covered_pool(cosmic_coding_vcf, "coding")
    cov_non = covered_pool(cosmic_noncoding_vcf, "noncoding")
    print("[somatic] covered candidates (depth>=%d): coding=%d noncoding=%d"
          % (min_pseudobulk_reads, len(cov_cod), len(cov_non)))

    def make_buffer(cov, tag, n):
        if len(cov) == 0:
            return cov.assign(**{'class': []}) if 'class' not in cov else cov
        take = min(len(cov), n * 5)
        b = cov.iloc[rng.choice(len(cov), size=take, replace=False)].copy()
        b['class'] = tag
        return b
    buf = pd.concat([make_buffer(cov_cod, "coding", n_coding),
                     make_buffer(cov_non, "noncoding", n_noncoding)], ignore_index=True)
    if buf.empty:
        print("[somatic] WARNING: no covered candidates; nothing introduced.")
        reference.close()
        return

    buf['name'] = (buf['class'] + "|" + buf['ref'].astype(str) + "|" + buf['alt'].astype(str)
                   + "|" + buf['depth'].astype(str))
    buf_bed = "%s/_som_buf.bed" % outdirectory
    buf[['chrom', 'start', 'pos', 'name']].sort_values(['chrom', 'start']).to_csv(
        buf_bed, sep='\t', header=False, index=False)
    isec = "%s/_som_buf_reads.txt" % outdirectory
    subprocess.run("%s intersect -a %s -b %s -split -sorted -wa -wb > %s"
                   % (bedtools_path, buf_bed, bed12_path, isec),
                   shell=True, executable="/bin/bash", check=True)
    cols = ['a_chrom', 'a_start', 'a_pos', 'a_name',
            'b_chrom', 'b_start', 'b_end', 'b_name', 'b_score', 'b_strand',
            'b_thickStart', 'b_thickEnd', 'b_rgb', 'b_blockCount', 'b_blockSizes', 'b_blockStarts']
    try:
        ir = pd.read_csv(isec, sep='\t', header=None, names=cols)
    except pd.errors.EmptyDataError:
        ir = pd.DataFrame(columns=cols)
    for f in (buf_bed, isec):
        try:
            os.remove(f)
        except OSError:
            pass

    feature_of = lambda rn: rn.split(':')[2].split('#')[0]
    rows = []
    gt = []
    placed = {'coding': 0, 'noncoding': 0}
    target = {'coding': n_coding, 'noncoding': n_noncoding}

    grouped = list(ir.groupby(['a_pos', 'a_name']))
    used_pos = set()
    for gi in rng.permutation(len(grouped)) if len(grouped) else []:
        (a_pos, a_name), grp = grouped[int(gi)]
        cls, ref, alt, depth = str(a_name).split('|')
        if placed[cls] >= target[cls]:
            continue
        pos = int(a_pos)
        if pos in used_pos:                      # never mutate the same position twice
            continue
        # allele-0 covering reads only
        recs = [rr for _, rr in grp.iterrows() if read_allele.get(str(rr['b_name']), 1) == 0]
        if not recs:
            continue
        feats = [feature_of(str(rr['b_name'])) for rr in recs]
        feature = max(set(feats), key=feats.count)
        r = feature_ratio.get(feature)
        if r is None:
            continue
        cell_reads = defaultdict(list)
        for rr in recs:
            cell_reads[str(rr['b_name'])[:16]].append(rr)
        cells_by_type = defaultdict(list)
        for cb in cell_reads:
            cells_by_type[barcode_celltype.get(cb, "NA")].append(cb)
        cells_by_type.pop("NA", None)
        if not cells_by_type:
            continue
        celltype = str(rng.choice(sorted(cells_by_type.keys())))
        elig_cells = cells_by_type[celltype]
        # Draw the DESIRED carrier-cell count uniformly over [1, max_cells], THEN cap at the
        # number of eligible cells. The previous draw, Uniform[1, N_eligible], has a marginal
        # that piles up at 1 cell: most sites have few eligible cells (~half of placed sites
        # have only 1-2), so a per-site uniform draw is small far more often than not, wasting
        # ~2/3 of the available coverage (mean ceiling 18 vs mean realized 7). Sampling the
        # target first instead pushes each site toward its own eligible-cell ceiling, which
        # flattens the cells-per-mutation distribution and ~1.6x's total carrier coverage.
        # No model assumption changes: same allele-0 eligibility, same single (random) cell
        # type, same >=10x candidate sites, mutation still only in covering cells. Sites with a
        # single eligible cell still yield 1 cell -- a hard floor set by the data, not sampling.
        k = min(int(rng.randint(1, max_cells + 1)), len(elig_cells))
        chosen = [str(c) for c in rng.choice(elig_cells, size=k, replace=False)]
        site_rows = 0
        for cb in chosen:
            for rr in cell_reads[cb]:
                rn = str(rr['b_name']); strand = str(rr['b_strand'])
                abs_blocks = _parse_bed12_blocks(int(rr['b_start']), rr['b_blockSizes'], rr['b_blockStarts'])
                epos = _genomic_pos_to_read_pos(pos, abs_blocks, strand)
                if epos is None:
                    continue
                if strand == '+':
                    ref_b, alt_b = ref, alt
                else:
                    ref_b, alt_b = get_complement(ref), get_complement(alt)
                rows.append([rn, epos, ref_b, alt_b, 1, strand, chrom, pos, "somatic", "T", "0"])
                site_rows += 1
        if site_rows == 0:
            continue
        gt.append({'chrom': chrom, 'pos': pos, 'ref': ref, 'alt': alt, 'class': cls,
                   'feature': feature, 'allele': 0, 'celltype': celltype, 'vaf_r': r,
                   'n_cells_target': k, 'n_cells_realized': len(chosen),
                   'pseudobulk_depth': int(depth), 'cell_barcodes': ";".join(chosen)})
        placed[cls] += 1
        used_pos.add(pos)

    reference.close()
    print("[somatic] placed: coding=%d/%d noncoding=%d/%d (somatic read-rows=%d)"
          % (placed['coding'], n_coding, placed['noncoding'], n_noncoding, len(rows)))
    if placed['coding'] < n_coding or placed['noncoding'] < n_noncoding:
        print("[somatic] WARNING: fewer somatic sites than requested (coverage/eligibility limited).")

    cols11 = ['read_name', 'edit_position', 'ref', 'alt', 'editing_level', 'strand',
              'Region', 'Position_genome', 'category', 'include', 'allelic']
    som_df = pd.DataFrame(rows, columns=cols11)
    base = pd.read_csv(editpos_path)
    pd.concat([base, som_df], ignore_index=True).to_csv(editpos_path, index=False)

    gt_df = pd.DataFrame(gt)
    gt_df.to_csv("%s/somatic_mutations_ground_truth.tsv" % outdirectory, sep='\t', index=False)
    with open("%s/somatic_mutations.vcf" % outdirectory, 'w') as vf:
        vf.write("##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n")
        for g in gt:
            vf.write("%s\t%d\t.\t%s\t%s\t.\tPASS\tCLASS=%s;FEATURE=%s;CELLTYPE=%s;VAF=%.4f;NCELLS=%d\n"
                     % (g['chrom'], g['pos'], g['ref'], g['alt'], g['class'], g['feature'],
                        g['celltype'], g['vaf_r'], g['n_cells_realized']))
    print("[somatic] wrote somatic_mutations_ground_truth.tsv and somatic_mutations.vcf")

